--
-- Name: apply_employee_import_batch(uuid, uuid, text, jsonb, uuid, jsonb, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.apply_employee_import_batch(p_org_id uuid, p_run_id uuid, p_source_ref text, p_rows jsonb, p_actor uuid, p_apply_audit jsonb, p_trace_id text, p_span_id text) RETURNS TABLE(report jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_run public.data_import_runs%ROWTYPE;
    v_row JSONB;
    v_employee public.employees%ROWTYPE;
    v_employee_id UUID;
    v_employee_updated_at TIMESTAMPTZ;
    v_balance_result RECORD;
    v_source_key TEXT;
    v_company TEXT;
    v_name TEXT;
    v_idempotency_key TEXT;
    v_identity_strategy TEXT;
    v_identity_confidence TEXT;
    v_identity_review_required BOOLEAN;
    v_outcome TEXT;
    v_outcomes JSONB := '[]'::JSONB;
    v_report JSONB;
    v_input_rows INTEGER;
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_actor,p_trace_id,p_span_id);
    PERFORM leave_api.assert_employee_importer(p_org_id,p_actor);
    IF char_length(pg_catalog.btrim(p_source_ref)) NOT BETWEEN 1 AND 256
       OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='employee_import_batch.invalid_payload';
    END IF;
    v_input_rows := jsonb_array_length(p_rows);

    IF p_run_id IS NOT NULL THEN
        SELECT * INTO v_run
          FROM public.data_import_runs r
         WHERE r.org_id=p_org_id AND r.id=p_run_id
         FOR UPDATE;
        IF NOT FOUND OR v_run.entity_type <> 'employee_hr' THEN
            RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='employee_import_batch.run_not_found';
        END IF;
        IF v_run.status = 'APPLIED' THEN
            SELECT v_run.apply_summary || pg_catalog.jsonb_build_object(
                'inserted',0,
                'updated',0,
                'skipped',coalesce((v_run.apply_summary->>'input_rows')::INTEGER,0),
                'companies',coalesce((
                    SELECT jsonb_agg(item || pg_catalog.jsonb_build_object(
                        'inserted',0,
                        'updated',0,
                        'skipped',coalesce((item->>'input_rows')::INTEGER,0)
                    ) ORDER BY item->>'company')
                    FROM jsonb_array_elements(
                        coalesce(v_run.apply_summary->'companies','[]'::JSONB)
                    ) item
                ),'[]'::JSONB)
            ) INTO v_report;
            RETURN QUERY SELECT v_report, true;
            RETURN;
        END IF;
        IF v_run.status <> 'DRY_RUN' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='employee_import_batch.run_not_dry_run';
        END IF;
        IF p_source_ref <> 'run:' || p_run_id::TEXT
           OR v_input_rows <> v_run.candidate_rows
           OR (SELECT count(DISTINCT item->>'source_key')
                 FROM jsonb_array_elements(p_rows) item) <> v_run.candidate_rows
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(p_rows) item
                 WHERE NOT EXISTS (
                    SELECT 1 FROM public.data_import_rows ir
                     WHERE ir.org_id=p_org_id AND ir.run_id=p_run_id
                       AND ir.row_status='CANDIDATE'
                       AND ir.source_key=item->>'source_key'
                 )
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(p_rows) item
                  JOIN public.data_import_rows ir
                    ON ir.org_id=p_org_id
                   AND ir.run_id=p_run_id
                   AND ir.row_status='CANDIDATE'
                   AND ir.source_key=item->>'source_key'
                 CROSS JOIN LATERAL (
                    SELECT CASE
                        WHEN ir.canonical_row#>>'{source_metadata,identity_resolution,strategy}'
                             IN ('employee_number','legal_identifier_hash',
                                 'birth_hire_fingerprint','source_row_fingerprint')
                        THEN ir.canonical_row#>>'{source_metadata,identity_resolution,strategy}'
                        ELSE 'source_row_fingerprint'
                    END AS strategy
                 ) identity
                 WHERE item IS DISTINCT FROM (
                    ir.canonical_row || pg_catalog.jsonb_build_object(
                        'raw_row',ir.raw_row,
                        'identity',pg_catalog.jsonb_build_object(
                            'strategy',identity.strategy,
                            'confidence',CASE identity.strategy
                                WHEN 'employee_number' THEN 'high'
                                WHEN 'legal_identifier_hash' THEN 'high'
                                WHEN 'birth_hire_fingerprint' THEN 'medium'
                                ELSE 'low'
                            END,
                            'review_required',NOT (
                                coalesce((ir.canonical_row#>>
                                    '{source_metadata,identity_resolution,manual_review_required}')
                                    ::BOOLEAN,true) = false
                                AND identity.strategy IN (
                                    'employee_number','legal_identifier_hash'
                                )
                            )
                        )
                    )
                 )
           ) THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='employee_import_batch.run_payload_mismatch';
        END IF;
    END IF;

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
    LOOP
        v_company := pg_catalog.btrim(v_row->>'company');
        v_name := pg_catalog.btrim(v_row->>'name');
        v_source_key := pg_catalog.btrim(v_row->>'source_key');
        IF coalesce(v_company,'') = '' OR coalesce(v_name,'') = ''
           OR coalesce(v_source_key,'') = ''
           OR coalesce(pg_catalog.btrim(v_row->>'source_filename'),'') = ''
           OR coalesce(pg_catalog.btrim(v_row->>'source_sheet'),'') = ''
           OR coalesce((v_row->>'source_row')::INTEGER,0) <= 0
           OR jsonb_typeof(v_row->'raw_row') IS DISTINCT FROM 'object'
           OR jsonb_typeof(v_row->'source_metadata') IS DISTINCT FROM 'object'
           OR jsonb_typeof(v_row->'canonical') IS DISTINCT FROM 'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='employee_import_batch.invalid_row';
        END IF;

        v_idempotency_key := 'employee-import:' || pg_catalog.encode(
            public.digest(p_source_ref || ':' || v_source_key,'sha256'),'hex'
        );
        SELECT * INTO v_employee
          FROM public.employees e
         WHERE e.org_id=p_org_id AND e.source_key=v_source_key
         FOR UPDATE;

        -- A prior receipt means this exact source row already committed. Call
        -- the protected command to verify its payload binding, but deliberately
        -- do not rewrite ordinary roster fields or updated_at on replay.
        IF FOUND AND EXISTS (
            SELECT 1 FROM public.leave_balance_import_receipts r
             WHERE r.org_id=p_org_id AND r.idempotency_key=v_idempotency_key
        ) THEN
            SELECT * INTO v_balance_result
              FROM leave_api.import_employee_leave_balance(
                p_org_id,v_employee.id,v_employee.updated_at,
                v_row#>>'{canonical,leave_accrued}',
                v_row#>>'{canonical,leave_used}',
                v_row#>>'{canonical,leave_remaining}',
                'employee_import',p_source_ref,v_idempotency_key,
                p_actor,p_trace_id,p_span_id
              );
            v_outcome := 'skipped';
        ELSE
            v_identity_strategy := coalesce(
                v_row#>>'{identity,strategy}','source_row_fingerprint'
            );
            v_identity_confidence := coalesce(v_row#>>'{identity,confidence}','low');
            v_identity_review_required := coalesce(
                (v_row#>>'{identity,review_required}')::BOOLEAN,true
            );
            INSERT INTO public.employees (
                org_id,company,name,source_filename,source_sheet,source_row,
                source_key,raw_row,source_metadata,employee_number,org_unit,job,
                position,worksite_name,worksite_address,hire_date,exit_date,
                employment_status,identity_resolution_strategy,
                identity_resolution_confidence,identity_review_required,
                identity_name_only_merge
            ) VALUES (
                p_org_id,v_company,v_name,v_row->>'source_filename',
                v_row->>'source_sheet',(v_row->>'source_row')::INTEGER,
                v_source_key,v_row->'raw_row',v_row->'source_metadata',
                v_row#>>'{canonical,employee_number}',
                v_row#>>'{canonical,org_unit}',v_row#>>'{canonical,job}',
                v_row#>>'{canonical,position}',v_row#>>'{canonical,worksite_name}',
                v_row#>>'{canonical,worksite_address}',v_row#>>'{canonical,hire_date}',
                v_row#>>'{canonical,exit_date}',
                coalesce(v_row#>>'{canonical,employment_status}','ACTIVE'),
                v_identity_strategy,v_identity_confidence,
                v_identity_review_required,false
            )
            ON CONFLICT (org_id,source_key) DO UPDATE SET
                company=EXCLUDED.company,name=EXCLUDED.name,
                source_filename=EXCLUDED.source_filename,
                source_sheet=EXCLUDED.source_sheet,source_row=EXCLUDED.source_row,
                raw_row=EXCLUDED.raw_row,source_metadata=EXCLUDED.source_metadata,
                employee_number=EXCLUDED.employee_number,org_unit=EXCLUDED.org_unit,
                job=EXCLUDED.job,position=EXCLUDED.position,
                worksite_name=EXCLUDED.worksite_name,
                worksite_address=EXCLUDED.worksite_address,
                hire_date=EXCLUDED.hire_date,exit_date=EXCLUDED.exit_date,
                employment_status=EXCLUDED.employment_status,
                identity_resolution_strategy=EXCLUDED.identity_resolution_strategy,
                identity_resolution_confidence=EXCLUDED.identity_resolution_confidence,
                identity_review_required=EXCLUDED.identity_review_required,
                identity_name_only_merge=false,updated_at=pg_catalog.clock_timestamp()
            RETURNING id,updated_at,
                CASE WHEN xmax=0 THEN 'inserted' ELSE 'updated' END
              INTO v_employee_id,v_employee_updated_at,v_outcome;

            SELECT * INTO v_balance_result
              FROM leave_api.import_employee_leave_balance(
                p_org_id,v_employee_id,v_employee_updated_at,
                v_row#>>'{canonical,leave_accrued}',
                v_row#>>'{canonical,leave_used}',
                v_row#>>'{canonical,leave_remaining}',
                'employee_import',p_source_ref,v_idempotency_key,
                p_actor,p_trace_id,p_span_id
              );
        END IF;
        v_outcomes := v_outcomes || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object('company',v_company,'outcome',v_outcome)
        );
    END LOOP;

    SELECT pg_catalog.jsonb_build_object(
        'input_rows',v_input_rows,
        'inserted',(SELECT count(*) FROM jsonb_array_elements(v_outcomes) item
                    WHERE item->>'outcome'='inserted'),
        'updated',(SELECT count(*) FROM jsonb_array_elements(v_outcomes) item
                   WHERE item->>'outcome'='updated'),
        'skipped',(SELECT count(*) FROM jsonb_array_elements(v_outcomes) item
                   WHERE item->>'outcome'='skipped'),
        'companies',coalesce((
            SELECT jsonb_agg(pg_catalog.jsonb_build_object(
                'company',company,'input_rows',input_rows,
                'inserted',inserted,'updated',updated,'skipped',skipped
            ) ORDER BY company)
            FROM (
                SELECT item->>'company' AS company,count(*) AS input_rows,
                    count(*) FILTER (WHERE item->>'outcome'='inserted') AS inserted,
                    count(*) FILTER (WHERE item->>'outcome'='updated') AS updated,
                    count(*) FILTER (WHERE item->>'outcome'='skipped') AS skipped
                FROM jsonb_array_elements(v_outcomes) item
                GROUP BY item->>'company'
            ) companies
        ),'[]'::JSONB)
    ) INTO v_report;

    IF p_run_id IS NOT NULL THEN
        UPDATE public.data_import_runs r
           SET status='APPLIED',apply_summary=v_report,applied_by=p_actor,
               applied_at=pg_catalog.clock_timestamp(),updated_at=pg_catalog.clock_timestamp()
         WHERE r.org_id=p_org_id AND r.id=p_run_id;
    END IF;
    -- A successful first application always has intrinsic command-owned
    -- evidence, including legacy direct imports and roster-only/null-balance
    -- rows. Pure receipt/APPLIED replay is side-effect-free and reuses the
    -- original evidence rather than appending a misleading duplicate.
    IF p_run_id IS NOT NULL OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_outcomes) item
        WHERE item->>'outcome' <> 'skipped'
    ) THEN
        INSERT INTO public.audit_events
            (actor,action,target_type,target_id,before_snap,after_snap,
             trace_id,span_id,occurred_at,org_id)
        VALUES (
            p_actor,'data_import.apply',
            CASE WHEN p_run_id IS NULL THEN 'employee_import_batch' ELSE 'data_import_run' END,
            coalesce(p_run_id::TEXT,pg_catalog.btrim(p_source_ref)),NULL,
            coalesce(p_apply_audit,'{}'::JSONB) || pg_catalog.jsonb_build_object(
                'run_id',p_run_id,'entity_type','employee_hr',
                'source_ref',pg_catalog.btrim(p_source_ref),'report',v_report
            ),p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id
        );
    END IF;
    RETURN QUERY SELECT v_report,false;
END;
$$;


ALTER FUNCTION leave_api.apply_employee_import_batch(p_org_id uuid, p_run_id uuid, p_source_ref text, p_rows jsonb, p_actor uuid, p_apply_audit jsonb, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: assert_context(uuid, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.assert_context(p_org_id uuid, p_actor uuid, p_trace_id text, p_span_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
BEGIN
    IF p_org_id IS NULL OR p_actor IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_write.context_required';
    END IF;
    PERFORM pg_catalog.set_config('app.current_org', p_org_id::TEXT, true);
    IF NOT EXISTS (
        SELECT 1 FROM public.users u
        WHERE u.id = p_actor AND u.org_id = p_org_id AND u.is_active
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.actor_forbidden';
    END IF;
    IF p_trace_id !~ '^[0-9a-f]{32}$' OR p_span_id !~ '^[0-9a-f]{16}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_write.invalid_trace';
    END IF;
END;
$_$;


ALTER FUNCTION leave_api.assert_context(p_org_id uuid, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: assert_employee_directory_manager(uuid, uuid); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.assert_employee_directory_manager(p_org_id uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.users u
        WHERE u.id = p_actor
          AND u.org_id = p_org_id
          AND u.is_active
          AND (
              u.roles @> ARRAY['SUPER_ADMIN']::TEXT[]
              OR (
                  -- A custom grant can only be org-wide when the actor has
                  -- the resolver's live All scope (EXECUTIVE/SUPER_ADMIN).
                  (u.roles @> ARRAY['SUPER_ADMIN']::TEXT[]
                   OR u.roles @> ARRAY['EXECUTIVE']::TEXT[])
                  AND EXISTS (
                      SELECT 1
                      FROM public.user_role_assignments ura
                      JOIN public.policy_roles pr
                        ON pr.org_id = ura.org_id AND pr.id = ura.role_id
                      JOIN public.policy_role_permissions prp
                        ON prp.org_id = pr.org_id AND prp.role_id = pr.id
                      WHERE ura.org_id = p_org_id
                        AND ura.user_id = p_actor
                        AND pr.status = 'ACTIVE'
                        AND NOT pr.is_system
                        AND prp.feature_key = 'employee_directory_manage'
                        AND prp.permission_level = 'allow'
                        AND NOT EXISTS (
                            SELECT 1
                            FROM public.policy_role_conditions prc
                            WHERE prc.org_id = pr.org_id
                              AND prc.role_id = pr.id
                              AND (
                                  prc.operator NOT IN ('equals', 'in')
                                  OR prc.attribute = 'branch'
                                  OR prc.attribute <> 'team'
                                  OR u.team IS NULL
                                  OR NOT EXISTS (
                                      SELECT 1
                                      FROM pg_catalog.unnest(prc.condition_values) value
                                      WHERE pg_catalog.btrim(value) = u.team
                                         OR pg_catalog.upper(pg_catalog.btrim(value)) = CASE u.team
                                              WHEN '정비' THEN 'MAINTENANCE'
                                              WHEN '예방' THEN 'PREVENTION'
                                              WHEN '관리' THEN 'MANAGEMENT'
                                              WHEN '접수' THEN 'RECEPTION'
                                              ELSE NULL
                                            END
                                  )
                              )
                        )
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'employee_create.actor_forbidden';
    END IF;
END;
$$;


ALTER FUNCTION leave_api.assert_employee_directory_manager(p_org_id uuid, p_actor uuid) OWNER TO console_leave_definer;

--
-- Name: assert_employee_importer(uuid, uuid); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.assert_employee_importer(p_org_id uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.users u
        WHERE u.id = p_actor AND u.org_id = p_org_id AND u.is_active
          AND (
              u.roles @> ARRAY['SUPER_ADMIN']::TEXT[]
              OR (
                  -- The application can produce an org-wide custom grant only
                  -- from an EXECUTIVE principal's live All scope. Re-evaluate
                  -- the persisted grant here rather than trusting a caller
                  -- boolean at the SECURITY DEFINER boundary.
                  u.roles @> ARRAY['EXECUTIVE']::TEXT[]
                  AND EXISTS (
                      SELECT 1
                      FROM public.user_role_assignments ura
                      JOIN public.policy_roles pr
                        ON pr.org_id = ura.org_id AND pr.id = ura.role_id
                      JOIN public.policy_role_permissions prp
                        ON prp.org_id = pr.org_id AND prp.role_id = pr.id
                      WHERE ura.org_id = p_org_id
                        AND ura.user_id = p_actor
                        AND pr.status = 'ACTIVE'
                        AND NOT pr.is_system
                        AND prp.feature_key = 'employee_directory_manage'
                        AND prp.permission_level = 'allow'
                        AND NOT EXISTS (
                            SELECT 1
                            FROM public.policy_role_conditions prc
                            WHERE prc.org_id = pr.org_id
                              AND prc.role_id = pr.id
                              AND (
                                  prc.operator NOT IN ('equals', 'in')
                                  -- Branch conditions narrow All and therefore
                                  -- cannot authorize this org-wide command.
                                  OR prc.attribute <> 'team'
                                  OR u.team IS NULL
                                  OR NOT EXISTS (
                                      SELECT 1
                                      FROM pg_catalog.unnest(prc.condition_values) value
                                      WHERE pg_catalog.btrim(value) = u.team
                                         OR pg_catalog.upper(pg_catalog.btrim(value)) = CASE u.team
                                              WHEN '정비' THEN 'MAINTENANCE'
                                              WHEN '예방' THEN 'PREVENTION'
                                              WHEN '관리' THEN 'MANAGEMENT'
                                              WHEN '접수' THEN 'RECEPTION'
                                              ELSE NULL
                                            END
                                  )
                              )
                        )
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_balance_import.actor_forbidden';
    END IF;
END;
$$;


ALTER FUNCTION leave_api.assert_employee_importer(p_org_id uuid, p_actor uuid) OWNER TO console_leave_definer;

--
-- Name: assert_manager(uuid, uuid, uuid); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.assert_manager(p_org_id uuid, p_actor uuid, p_branch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.users u
        WHERE u.id = p_actor AND u.org_id = p_org_id AND u.is_active
          AND (u.roles @> ARRAY['SUPER_ADMIN']::TEXT[]
               OR (u.roles @> ARRAY['ADMIN']::TEXT[] AND EXISTS (
                    SELECT 1 FROM public.user_branches ub
                    WHERE ub.org_id = p_org_id AND ub.user_id = p_actor
                      AND ub.branch_id = p_branch_id)))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.branch_forbidden';
    END IF;
END;
$$;


ALTER FUNCTION leave_api.assert_manager(p_org_id uuid, p_actor uuid, p_branch_id uuid) OWNER TO console_leave_definer;

--
-- Name: assert_org_admin(uuid, uuid); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.assert_org_admin(p_org_id uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.users u
        WHERE u.id = p_actor AND u.org_id = p_org_id AND u.is_active
          AND u.roles @> ARRAY['SUPER_ADMIN']::TEXT[]
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.org_admin_required';
    END IF;
END;
$$;


ALTER FUNCTION leave_api.assert_org_admin(p_org_id uuid, p_actor uuid) OWNER TO console_leave_definer;

--
-- Name: canonical_charge_snapshot(uuid, text, text, date, date, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.canonical_charge_snapshot(p_home_branch_id uuid, p_leave_type text, p_partial_day_period text, p_start_date date, p_end_date date, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb) RETURNS TABLE(snapshot jsonb, charge_units numeric, server_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE
    v_expected_days INTEGER;
    v_total NUMERIC(16,6);
    v_scheduled INTEGER;
    v_body JSONB;
BEGIN
    IF p_leave_type NOT IN ('annual', 'half_day')
       OR p_end_date < p_start_date
       OR (p_leave_type = 'half_day') IS DISTINCT FROM (p_partial_day_period IS NOT NULL)
       OR (p_partial_day_period IS NOT NULL AND p_partial_day_period NOT IN ('am', 'pm')) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_intent';
    END IF;
    IF pg_catalog.jsonb_typeof(p_date_charges) <> 'array'
       OR pg_catalog.jsonb_array_length(p_date_charges) = 0
       OR pg_catalog.jsonb_typeof(p_calendar_revision_ref) <> 'object'
       OR pg_catalog.jsonb_typeof(p_policy_revision_ref) <> 'object'
       OR pg_catalog.jsonb_typeof(p_supporting_source_refs) <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_evidence_shape';
    END IF;
    IF EXISTS (
        SELECT 1 FROM (VALUES (p_calendar_revision_ref), (p_policy_revision_ref)) r(doc)
        WHERE NULLIF(pg_catalog.btrim(doc->>'kind'), '') IS NULL
           OR NULLIF(pg_catalog.btrim(doc->>'reference'), '') IS NULL
           OR NULLIF(pg_catalog.btrim(doc->>'revision'), '') IS NULL
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_supporting_source_refs) x
        WHERE pg_catalog.jsonb_typeof(x) <> 'object'
           OR NULLIF(pg_catalog.btrim(x->>'kind'), '') IS NULL
           OR NULLIF(pg_catalog.btrim(x->>'reference'), '') IS NULL
           OR NULLIF(pg_catalog.btrim(x->>'revision'), '') IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_source_reference';
    END IF;

    v_expected_days := p_end_date - p_start_date + 1;
    IF pg_catalog.jsonb_array_length(p_date_charges) <> v_expected_days
       OR (SELECT pg_catalog.count(DISTINCT (x->>'date')::DATE)
           FROM pg_catalog.jsonb_array_elements(p_date_charges) x) <> v_expected_days
       OR (SELECT pg_catalog.min((x->>'date')::DATE)
           FROM pg_catalog.jsonb_array_elements(p_date_charges) x) <> p_start_date
       OR (SELECT pg_catalog.max((x->>'date')::DATE)
           FROM pg_catalog.jsonb_array_elements(p_date_charges) x) <> p_end_date THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.incomplete_date_evidence';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_date_charges) x
        WHERE pg_catalog.jsonb_typeof(x) <> 'object'
           OR x->>'kind' IS NOT NULL
           OR pg_catalog.jsonb_typeof(x->'obligation') <> 'object'
           OR (x->'obligation'->>'kind') NOT IN ('scheduled', 'not_scheduled')
           OR NULLIF(x->>'units', '') IS NULL
           OR (x->>'units') !~ '^[0-9]{1,3}(\.[0-9]{1,6})?$'
           OR (x->>'units')::NUMERIC < 0
           OR (x->>'units')::NUMERIC > 1
           OR ((x->'obligation'->>'kind') = 'scheduled'
               AND (COALESCE((x->'obligation'->>'minutes')::INTEGER, 0) <= 0
                    OR (x->>'units')::NUMERIC <= 0))
           OR ((x->'obligation'->>'kind') = 'not_scheduled'
               AND ((x->>'units')::NUMERIC <> 0
                    OR NULLIF(pg_catalog.btrim(x->'obligation'->>'basis'), '') IS NULL))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_date_evidence';
    END IF;

    SELECT COALESCE(pg_catalog.sum((x->>'units')::NUMERIC), 0),
           pg_catalog.count(*) FILTER (WHERE x->'obligation'->>'kind' = 'scheduled')
      INTO v_total, v_scheduled
      FROM pg_catalog.jsonb_array_elements(p_date_charges) x;
    IF v_total <= 0 OR v_total > 366 OR pg_catalog.scale(v_total) > 6 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_total';
    END IF;
    IF p_leave_type = 'annual' AND EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_date_charges) x
        WHERE x->'obligation'->>'kind' = 'scheduled' AND (x->>'units')::NUMERIC <> 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.annual_units_must_be_one';
    END IF;
    IF p_leave_type = 'half_day'
       AND (p_start_date <> p_end_date OR v_scheduled <> 1 OR v_total >= 1) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_charge.invalid_half_day';
    END IF;

    v_body := pg_catalog.jsonb_build_object(
        'home_branch_id', p_home_branch_id,
        'leave_type', p_leave_type,
        'partial_day_period', p_partial_day_period,
        'calendar_revision_ref', p_calendar_revision_ref,
        'policy_revision_ref', p_policy_revision_ref,
        'supporting_source_refs', p_supporting_source_refs,
        'date_charges', p_date_charges,
        'total_units', pg_catalog.to_char(v_total, 'FM999999999999990.000000')
    );
    server_digest := pg_catalog.encode(public.digest(
        pg_catalog.convert_to(v_body::TEXT, 'UTF8'), 'sha256'), 'hex');
    snapshot := v_body || pg_catalog.jsonb_build_object('server_digest', server_digest);
    charge_units := v_total;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION leave_api.canonical_charge_snapshot(p_home_branch_id uuid, p_leave_type text, p_partial_day_period text, p_start_date date, p_end_date date, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb) OWNER TO console_leave_definer;

--
-- Name: create_employee(uuid, uuid, text, text, text, text, text, text, text, text, uuid, numeric, text, text, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.create_employee(p_org_id uuid, p_employee_id uuid, p_employee_number text, p_name text, p_company text, p_employment_type text, p_phone_e164 text, p_org_unit text, p_position text, p_site text, p_home_branch_id uuid, p_base_pay numeric, p_idempotency_key text, p_request_hash text, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(employee_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_stored_hash TEXT;
    v_existing_employee_id UUID;
BEGIN
    PERFORM leave_api.assert_context(p_org_id, p_actor, p_trace_id, p_span_id);
    PERFORM leave_api.assert_employee_directory_manager(p_org_id, p_actor);

    IF NOT EXISTS (
        SELECT 1 FROM public.branches b
        WHERE b.org_id = p_org_id
          AND b.id = p_home_branch_id
          AND b.deactivated_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'employee_create.active_branch_required';
    END IF;

    INSERT INTO public.employee_create_idempotency (org_id, idempotency_key, request_hash)
    VALUES (p_org_id, p_idempotency_key, p_request_hash)
    ON CONFLICT (org_id, idempotency_key) DO NOTHING;

    SELECT i.request_hash, i.employee_id
      INTO v_stored_hash, v_existing_employee_id
      FROM public.employee_create_idempotency i
     WHERE i.org_id = p_org_id AND i.idempotency_key = p_idempotency_key
     FOR UPDATE;
    IF v_stored_hash IS DISTINCT FROM p_request_hash THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'employee_create.idempotency_conflict';
    END IF;
    IF v_existing_employee_id IS NOT NULL THEN
        RETURN QUERY SELECT v_existing_employee_id, true;
        RETURN;
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtext(p_org_id::TEXT || ':' || p_employee_number)
    );
    IF EXISTS (
        SELECT 1 FROM public.employees e
        WHERE e.org_id = p_org_id AND e.employee_number = p_employee_number
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'employee_create.employee_number_conflict';
    END IF;

    INSERT INTO public.employees (
        id, org_id, company, name, employee_number, org_unit, position,
        worksite_name, home_branch_id, source_filename, source_sheet,
        source_row, source_key, raw_row, source_metadata,
        identity_resolution_strategy, identity_resolution_confidence,
        identity_review_required, identity_name_only_merge
    ) VALUES (
        p_employee_id, p_org_id, p_company, p_name, p_employee_number,
        p_org_unit, p_position, p_site, p_home_branch_id, 'console', 'people',
        1, 'console:' || p_employee_number, '{}'::jsonb, '{}'::jsonb,
        'employee_number', 'high', false, false
    );
    INSERT INTO public.employee_employment_profiles (
        employee_id, org_id, employment_type, phone_e164, base_pay,
        idempotency_key, request_hash, created_by
    ) VALUES (
        p_employee_id, p_org_id, p_employment_type, p_phone_e164, p_base_pay,
        p_idempotency_key, p_request_hash, p_actor
    );
    INSERT INTO public.employee_lifecycle_events (
        id, org_id, employee_id, event_type, to_status, to_company,
        to_org_unit, to_position, effective_date, comment, signoffs, created_by
    ) VALUES (
        pg_catalog.gen_random_uuid(), p_org_id, p_employee_id, 'ONBOARD', 'ACTIVE',
        p_company, p_org_unit, p_position, CURRENT_DATE::TEXT,
        'Created through People & Workforce', '{}'::jsonb, p_actor
    );
    UPDATE public.employee_create_idempotency
       SET employee_id = p_employee_id
     WHERE org_id = p_org_id AND idempotency_key = p_idempotency_key;
    INSERT INTO public.audit_events (
        actor, action, target_type, target_id, branch_id, before_snap, after_snap,
        trace_id, span_id, occurred_at, org_id
    ) VALUES (
        p_actor, 'employee.create', 'employee', p_employee_id::TEXT, p_home_branch_id,
        NULL, pg_catalog.jsonb_build_object(
            'employee_number', p_employee_number,
            'employment_type', p_employment_type,
            'home_branch_id', p_home_branch_id,
            'compensation_recorded', true,
            'phone_recorded', true
        ), p_trace_id, p_span_id, pg_catalog.statement_timestamp(), p_org_id
    );
    RETURN QUERY SELECT p_employee_id, false;
END;
$$;


ALTER FUNCTION leave_api.create_employee(p_org_id uuid, p_employee_id uuid, p_employee_number text, p_name text, p_company text, p_employment_type text, p_phone_e164 text, p_org_unit text, p_position text, p_site text, p_home_branch_id uuid, p_base_pay numeric, p_idempotency_key text, p_request_hash text, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: create_request(uuid, uuid, uuid, text, date, date, text, text[], uuid, jsonb, jsonb, jsonb, jsonb, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.create_request(p_org_id uuid, p_request_id uuid, p_requester uuid, p_leave_type text, p_start_date date, p_end_date date, p_partial_day_period text, p_review_reasons text[], p_evidence_home_branch_id uuid, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb, p_submission_key uuid, p_trace_id text, p_span_id text) RETURNS TABLE(request_id uuid, subject_employee_id uuid, branch_id uuid, request_version bigint, charge_version bigint, charge_units numeric, server_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_subject UUID;
    v_branch UUID;
    v_snapshot JSONB;
    v_units NUMERIC(16,6);
    v_digest TEXT;
    v_submission_digest TEXT;
    v_resolved BOOLEAN := p_date_charges IS NOT NULL;
    v_resolution_id UUID;
    v_existing public.leave_requests%ROWTYPE;
    v_existing_server_digest TEXT;
BEGIN
    PERFORM leave_api.assert_context(p_org_id, p_requester, p_trace_id, p_span_id);
    IF p_submission_key IS NULL
       OR p_end_date < p_start_date
       OR p_leave_type NOT IN ('annual','half_day')
       OR (p_leave_type = 'half_day') IS DISTINCT FROM (p_partial_day_period IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_create.invalid_intent';
    END IF;

    -- Idempotency is bound only to normalized client intent. Mutable routing
    -- and evidence validation deliberately occur after this replay check so a
    -- committed response can be recovered even if home branch, calendar, or
    -- policy state changed before the retry arrived.
    v_submission_digest := pg_catalog.encode(public.digest(
        pg_catalog.convert_to(pg_catalog.jsonb_build_object(
            'leave_type', p_leave_type,
            'start_date', p_start_date,
            'end_date', p_end_date,
            'partial_day_period', p_partial_day_period
        )::TEXT, 'UTF8'), 'sha256'), 'hex');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_org_id::TEXT || ':' || p_requester::TEXT || ':' || p_submission_key::TEXT, 166
    ));
    SELECT * INTO v_existing
      FROM public.leave_requests lr
     WHERE lr.org_id = p_org_id
       AND lr.requester_user_id = p_requester
       AND lr.submission_key = p_submission_key;
    IF FOUND THEN
        IF v_existing.submission_digest IS DISTINCT FROM v_submission_digest THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_create.idempotency_conflict';
        END IF;
        SELECT r.server_digest INTO v_existing_server_digest
          FROM public.leave_charge_resolutions r
         WHERE r.org_id = p_org_id
           AND r.request_id = v_existing.id
           AND r.charge_version = 1
           AND v_existing.submission_initial_charge_version = 1;
        RETURN QUERY SELECT v_existing.id, v_existing.subject_employee_id,
            v_existing.branch_id, 1::BIGINT,
            v_existing.submission_initial_charge_version,
            CASE WHEN v_existing.submission_initial_charge_version = 0 THEN NULL::NUMERIC
                 ELSE (SELECT r.charge_units
                         FROM public.leave_charge_resolutions r
                        WHERE r.org_id = p_org_id
                          AND r.request_id = v_existing.id
                          AND r.charge_version = 1) END,
            v_existing_server_digest;
        RETURN;
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_requester::TEXT, 166));
    SELECT e.id, e.home_branch_id INTO v_subject, v_branch
      FROM public.users u
      JOIN public.employees e ON e.id = u.employee_id AND e.org_id = u.org_id
     WHERE u.id = p_requester AND u.org_id = p_org_id AND u.is_active
       AND e.employment_status = 'ACTIVE'
     FOR UPDATE OF e;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_create.self_employee_required';
    END IF;
    IF v_branch IS NOT NULL THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_branch::TEXT, 166));
    END IF;
    IF v_branch IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.branches b
        WHERE b.id = v_branch AND b.org_id = p_org_id AND b.deactivated_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'leave_create.home_branch_required';
    END IF;
    IF v_resolved IS DISTINCT FROM (p_review_reasons IS NULL OR cardinality(p_review_reasons) = 0)
       OR (v_resolved AND p_evidence_home_branch_id IS DISTINCT FROM v_branch)
       OR (NOT v_resolved AND (p_evidence_home_branch_id IS NOT NULL
           OR p_date_charges IS NOT NULL
           OR p_calendar_revision_ref IS NOT NULL
           OR p_policy_revision_ref IS NOT NULL
           OR p_supporting_source_refs IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_create.invalid_charge_choice';
    END IF;
    IF NOT v_resolved AND (
        cardinality(p_review_reasons) = 0 OR p_review_reasons IS NULL
        OR pg_catalog.array_position(p_review_reasons, NULL) IS NOT NULL
        OR NOT p_review_reasons <@ ARRAY['missing_calendar','ambiguous_calendar',
            'calendar_source_unavailable','missing_policy','ambiguous_policy',
            'policy_source_unavailable']::TEXT[]
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'leave_create.invalid_review_reasons';
    END IF;

    IF v_resolved THEN
        SELECT c.snapshot, c.charge_units, c.server_digest
          INTO v_snapshot, v_units, v_digest
          FROM leave_api.canonical_charge_snapshot(v_branch, p_leave_type,
               p_partial_day_period, p_start_date, p_end_date, p_date_charges,
               p_calendar_revision_ref, p_policy_revision_ref,
               p_supporting_source_refs) c;
    END IF;

    INSERT INTO public.leave_requests
        (id, org_id, branch_id, requester_user_id, subject_employee_id, days,
         leave_type, start_date, end_date, partial_day_period, status,
         charge_state, charge_review_reasons, charge_units, charge_version,
         submission_key, submission_digest, submission_initial_charge_version)
    VALUES
        (p_request_id, p_org_id, v_branch, p_requester, v_subject,
         CASE WHEN p_leave_type = 'half_day' THEN 0.5::NUMERIC
              ELSE (p_end_date - p_start_date + 1)::NUMERIC END,
         p_leave_type, p_start_date, p_end_date,
         p_partial_day_period, 'pending', 'review_required',
         CASE WHEN v_resolved THEN ARRAY['missing_calendar']::TEXT[] ELSE p_review_reasons END,
         NULL, 0, p_submission_key, v_submission_digest,
         CASE WHEN v_resolved THEN 1 ELSE 0 END);

    IF v_resolved THEN
        v_resolution_id := public.gen_random_uuid();
        INSERT INTO public.leave_charge_resolutions
            (id, org_id, request_id, charge_version, home_branch_id, charge_units,
             date_charges, calendar_revision_ref, policy_revision_ref,
             supporting_source_refs, snapshot, server_digest, resolution_origin,
             resolved_by, resolved_at)
        VALUES
            (v_resolution_id, p_org_id, p_request_id, 1, v_branch, v_units,
             p_date_charges, p_calendar_revision_ref, p_policy_revision_ref,
             p_supporting_source_refs, v_snapshot, v_digest, 'automated', NULL, pg_catalog.statement_timestamp());
        UPDATE public.leave_requests
           SET charge_state = 'resolved',
               charge_review_reasons = ARRAY[]::TEXT[],
               charge_units = v_units,
               charge_version = 1,
               current_charge_resolution_id = v_resolution_id
         WHERE org_id = p_org_id AND id = p_request_id;
    END IF;

    INSERT INTO public.audit_events
        (actor, action, target_type, target_id, branch_id, before_snap, after_snap,
         trace_id, span_id, occurred_at, org_id)
    VALUES
        (p_requester, 'leave_request.create', 'leave_request', p_request_id::TEXT,
         v_branch, NULL,
         pg_catalog.jsonb_build_object('status','pending','leave_type',p_leave_type,
            'subject_employee_id',v_subject,'branch_id',v_branch,
            'charge_state',CASE WHEN v_resolved THEN 'resolved' ELSE 'review_required' END,
            'request_version',1,
            'charge_version',CASE WHEN v_resolved THEN 1 ELSE 0 END,
            'server_digest',v_digest),
         p_trace_id, p_span_id, pg_catalog.statement_timestamp(), p_org_id);

    RETURN QUERY SELECT p_request_id, v_subject, v_branch, 1::BIGINT,
        CASE WHEN v_resolved THEN 1::BIGINT ELSE 0::BIGINT END, v_units, v_digest;
END;
$$;


ALTER FUNCTION leave_api.create_request(p_org_id uuid, p_request_id uuid, p_requester uuid, p_leave_type text, p_start_date date, p_end_date date, p_partial_day_period text, p_review_reasons text[], p_evidence_home_branch_id uuid, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb, p_submission_key uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: decide_request(uuid, uuid, uuid, bigint, text, text, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.decide_request(p_org_id uuid, p_request_id uuid, p_decider uuid, p_expected_version bigint, p_decision text, p_comment text, p_trace_id text, p_span_id text) RETURNS TABLE(request_id uuid, request_version bigint, charge_version bigint, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_request public.leave_requests%ROWTYPE;
    v_resolution public.leave_charge_resolutions%ROWTYPE;
    v_new_version BIGINT;
    v_new_status TEXT;
    v_ledger_before JSONB;
    v_ledger_after JSONB;
    v_work_date DATE;
    v_headcount INT;
    v_already_out INT;
    v_minimum_on_duty INT := 1;
    v_projected BIGINT;
    v_grounds TEXT;
    v_evidence JSONB;
    v_exercises INT;
    v_leave_year INT;
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_decider,p_trace_id,p_span_id);
    IF p_decision NOT IN ('approve','time_change')
       OR (p_decision = 'time_change' AND NULLIF(pg_catalog.btrim(p_comment),'') IS NULL)
       OR (p_comment IS NOT NULL AND char_length(pg_catalog.btrim(p_comment)) > 500) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_decide.invalid_decision';
    END IF;
    SELECT * INTO v_request FROM public.leave_requests lr
     WHERE lr.org_id=p_org_id AND lr.id=p_request_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_decide.not_found'; END IF;
    PERFORM leave_api.assert_manager(p_org_id,p_decider,v_request.branch_id);
    IF v_request.status <> 'pending' THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_decide.not_pending';
    END IF;
    IF p_expected_version IS NOT NULL
       AND v_request.request_version <> p_expected_version THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_decide.concurrent_modification';
    END IF;
    IF v_request.requester_user_id=p_decider THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='leave_decide.requester_forbidden';
    END IF;

    IF p_decision='approve' THEN
        IF v_request.current_charge_resolution_id IS NOT NULL THEN
            PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_request.current_charge_resolution_id::TEXT, 166));
            SELECT * INTO v_resolution FROM public.leave_charge_resolutions r
             WHERE r.org_id=p_org_id AND r.id=v_request.current_charge_resolution_id
               AND r.request_id=p_request_id;
        END IF;
        IF v_request.charge_state <> 'resolved' OR NOT FOUND
           OR v_resolution.home_branch_id IS DISTINCT FROM v_request.branch_id
           OR v_resolution.charge_units IS DISTINCT FROM v_request.charge_units
           OR v_resolution.charge_version IS DISTINCT FROM v_request.charge_version THEN
            INSERT INTO public.audit_events
                (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
                 trace_id,span_id,occurred_at,org_id)
            VALUES
                (p_decider,'leave_request.approval_blocked','leave_request',p_request_id::TEXT,
                 v_request.branch_id,
                 pg_catalog.jsonb_build_object('status',v_request.status,
                    'charge_state',v_request.charge_state,
                    'request_version',v_request.request_version,
                    'charge_version',v_request.charge_version),
                 pg_catalog.jsonb_build_object('outcome','blocked_no_mutation'),
                 p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
            RETURN QUERY SELECT p_request_id,v_request.request_version,
                v_request.charge_version,'charge_review_required'::TEXT;
            RETURN;
        END IF;
        IF v_resolution.resolved_by=p_decider THEN
            RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='leave_decide.resolver_forbidden';
        END IF;
        FOR v_work_date IN
            SELECT work_date::DATE
              FROM pg_catalog.generate_series(v_request.start_date, v_request.end_date, INTERVAL '1 day') AS work_date
             ORDER BY work_date
        LOOP
            PERFORM public.console_employee_day_eligibility_lock(
                v_request.org_id, v_request.subject_employee_id, v_work_date
            );
        END LOOP;
        SELECT pg_catalog.jsonb_build_object('leave_used',e.leave_used,
                   'leave_remaining',e.leave_remaining)
          INTO v_ledger_before
          FROM public.employees e
         WHERE e.org_id=p_org_id AND e.id=v_request.subject_employee_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_decide.employee_not_found';
        END IF;
        UPDATE public.employees e
           SET leave_used=COALESCE(e.leave_used,0)+v_resolution.charge_units,
               leave_remaining=COALESCE(e.leave_remaining,0)-v_resolution.charge_units,
               updated_at=pg_catalog.now()
         WHERE e.org_id=p_org_id AND e.id=v_request.subject_employee_id
           AND COALESCE(e.leave_remaining,0)>=v_resolution.charge_units
        RETURNING pg_catalog.jsonb_build_object('leave_used',e.leave_used,
                    'leave_remaining',e.leave_remaining) INTO v_ledger_after;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_decide.insufficient_balance';
        END IF;
    ELSE
        -- §60⑤ 요건 자동 판정 (domain::judge_time_change_eligibility).
        -- Headcount is ACTIVE roster only — EXITED rows retaining home_branch_id
        -- must not inflate coverage and refuse a real shortfall (console-we1 critic).
        SELECT count(*)::INT INTO v_headcount
          FROM public.employees e
         WHERE e.org_id = p_org_id
           AND e.home_branch_id = v_request.branch_id
           AND e.employment_status = 'ACTIVE';
        SELECT count(DISTINCT lr.subject_employee_id)::INT INTO v_already_out
          FROM public.leave_requests lr
         WHERE lr.org_id = p_org_id
           AND lr.branch_id = v_request.branch_id
           AND lr.status = 'approved'
           AND lr.subject_employee_id IS DISTINCT FROM v_request.subject_employee_id
           AND lr.start_date <= v_request.end_date
           AND lr.end_date >= v_request.start_date;
        v_projected := v_headcount::BIGINT - v_already_out::BIGINT - 1;
        v_evidence := pg_catalog.jsonb_build_object(
            'headcount', v_headcount,
            'already_out', v_already_out,
            'minimum_on_duty', v_minimum_on_duty,
            'projected_available', v_projected
        );
        IF v_headcount = 0 OR v_projected >= v_minimum_on_duty THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='leave_decide.time_change_ineligible';
        END IF;
        v_grounds := 'branch_coverage_shortfall';
    END IF;

    v_new_version := v_request.request_version + 1;
    IF v_new_version <= v_request.request_version THEN
        RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='leave_decide.version_exhausted';
    END IF;
    v_new_status := CASE p_decision WHEN 'approve' THEN 'approved'
                         ELSE 'time_change_consult' END;
    UPDATE public.leave_requests
       SET status=v_new_status, decided_by=p_decider, decided_at=pg_catalog.statement_timestamp(),
           decision_comment=NULLIF(pg_catalog.btrim(p_comment),''),
           charge_state=CASE WHEN p_decision='approve' THEN charge_state ELSE 'not_required' END,
           charge_review_reasons=CASE WHEN p_decision='approve' THEN charge_review_reasons ELSE ARRAY[]::TEXT[] END,
           charge_units=CASE WHEN p_decision='approve' THEN charge_units ELSE NULL END,
           current_charge_resolution_id=CASE WHEN p_decision='approve' THEN current_charge_resolution_id ELSE NULL END,
           time_change_grounds=CASE WHEN p_decision='time_change' THEN v_grounds ELSE NULL END,
           time_change_evidence=CASE WHEN p_decision='time_change' THEN v_evidence ELSE NULL END,
           request_version=v_new_version
     WHERE org_id=p_org_id AND id=p_request_id;
    INSERT INTO public.audit_events
        (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
         trace_id,span_id,occurred_at,org_id)
    VALUES
        (p_decider,'leave_request.decide','leave_request',p_request_id::TEXT,
         v_request.branch_id,
         pg_catalog.jsonb_build_object('status',v_request.status,
             'charge_state',v_request.charge_state,
             'request_version',v_request.request_version,
             'charge_version',v_request.charge_version,
             'ledger',v_ledger_before),
         pg_catalog.jsonb_build_object('status',v_new_status,'decision',p_decision,
             'request_version',v_new_version,
             'charge_version',v_request.charge_version,'ledger',v_ledger_after,
             'time_change_grounds',v_grounds,
             'time_change_evidence',v_evidence),
         p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);

    IF p_decision = 'time_change' THEN
        v_leave_year := pg_catalog.date_part('year', v_request.start_date)::INT;
        SELECT count(*)::INT INTO v_exercises
          FROM public.leave_requests lr
         WHERE lr.org_id = p_org_id
           AND lr.subject_employee_id = v_request.subject_employee_id
           AND lr.status = 'time_change_consult'
           AND pg_catalog.date_part('year', lr.start_date)::INT = v_leave_year;
        IF v_exercises >= 2 THEN
            INSERT INTO public.audit_events
                (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
                 trace_id,span_id,occurred_at,org_id)
            VALUES
                (p_decider,'leave_request.time_change_repeat_audit','leave_request',
                 p_request_id::TEXT, v_request.branch_id,
                 pg_catalog.jsonb_build_object('leave_year', v_leave_year),
                 pg_catalog.jsonb_build_object(
                    'subject_employee_id', v_request.subject_employee_id,
                    'leave_year', v_leave_year,
                    'exercises_in_leave_year', v_exercises,
                    'audit_flag', true,
                    'grounds', v_grounds
                 ),
                 p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
        END IF;
    END IF;

    RETURN QUERY SELECT p_request_id,v_new_version,v_request.charge_version,'decided'::TEXT;
END;
$$;


ALTER FUNCTION leave_api.decide_request(p_org_id uuid, p_request_id uuid, p_decider uuid, p_expected_version bigint, p_decision text, p_comment text, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: employee_import_apply_audit_required(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.employee_import_apply_audit_required() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_matching_audits BIGINT;
BEGIN
    IF OLD.entity_type = 'employee_hr'
       AND NEW.entity_type = 'employee_hr'
       AND OLD.status = 'DRY_RUN'
       AND NEW.status = 'APPLIED' THEN
        PERFORM pg_catalog.set_config('app.current_org', NEW.org_id::TEXT, true);
        SELECT pg_catalog.count(*)
          INTO v_matching_audits
          FROM public.audit_events a
          JOIN public.users u
            ON u.id = a.actor
           AND u.org_id = a.org_id
           AND u.is_active
         WHERE a.org_id = NEW.org_id
           AND a.action = 'data_import.apply'
           AND a.target_type = 'data_import_run'
           AND a.target_id = NEW.id::TEXT
           AND a.actor = NEW.applied_by
           AND a.xmin = pg_catalog.pg_current_xact_id()::xid;
        IF v_matching_audits <> 1 THEN
            RAISE EXCEPTION USING
                ERRCODE = '23514',
                MESSAGE = 'employee_import_run.current_transaction_audit_required';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.employee_import_apply_audit_required() OWNER TO console_leave_definer;

--
-- Name: employee_import_run_writer_guard(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.employee_import_run_writer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.entity_type IS DISTINCT FROM OLD.entity_type THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'data_import_run.entity_type_immutable';
    END IF;
    IF current_user <> 'console_leave_definer' THEN
        IF TG_OP = 'INSERT' AND NEW.entity_type = 'employee_hr' AND (
            NEW.status = 'APPLIED'
            OR NEW.apply_summary IS DISTINCT FROM '{}'::JSONB
            OR NEW.applied_by IS NOT NULL
            OR NEW.applied_at IS NOT NULL
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'employee_import_run.command_required';
        ELSIF TG_OP = 'UPDATE'
           AND (OLD.entity_type = 'employee_hr' OR NEW.entity_type = 'employee_hr')
           AND (
                ((OLD.status = 'APPLIED' OR NEW.status = 'APPLIED')
                    AND NEW.status IS DISTINCT FROM OLD.status)
                OR NEW.apply_summary IS DISTINCT FROM OLD.apply_summary
                OR NEW.applied_by IS DISTINCT FROM OLD.applied_by
                OR NEW.applied_at IS DISTINCT FROM OLD.applied_at
           ) THEN
            IF current_user <> 'console_rt'
               OR OLD.entity_type <> 'employee_hr'
               OR NEW.entity_type <> 'employee_hr'
               OR OLD.status <> 'DRY_RUN'
               OR NEW.status <> 'APPLIED'
               OR NEW.applied_by IS NULL
               OR NEW.applied_at IS NULL
               OR (pg_catalog.to_jsonb(NEW) - ARRAY[
                    'status','apply_summary','applied_by','applied_at','updated_at'
                  ]::TEXT[]) IS DISTINCT FROM
                  (pg_catalog.to_jsonb(OLD) - ARRAY[
                    'status','apply_summary','applied_by','applied_at','updated_at'
                  ]::TEXT[]) THEN
                RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'employee_import_run.command_required';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.employee_import_run_writer_guard() OWNER TO console_leave_definer;

--
-- Name: employee_leave_writer_guard(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.employee_leave_writer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF current_user <> 'console_leave_definer' THEN
        IF current_user = 'console_rt' THEN
            -- Expand compatibility is intentionally limited to the surface the
            -- f6ff236 binary already owned. Its immediate and staged employee
            -- imports INSERT/UPSERT the protected balance columns directly, and
            -- its legacy leave approval updates used/remaining in-transaction.
            -- It never writes the additive home-branch authority introduced by
            -- 0166, which remains command-only throughout the mixed-version
            -- window. There is no trustworthy marker in the old SQL that can
            -- distinguish an import balance write from another console_rt balance
            -- write; pretending otherwise would break rollback or create a
            -- bypassable guard. The later contract migration removes this
            -- compatibility branch after f6ff236 is outside the rollback set.
            IF (TG_OP = 'INSERT' AND NEW.home_branch_id IS NOT NULL)
               OR (TG_OP = 'UPDATE'
                   AND NEW.home_branch_id IS DISTINCT FROM OLD.home_branch_id) THEN
                RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
            END IF;
        ELSIF TG_OP = 'INSERT' AND (
            NEW.home_branch_id IS NOT NULL
            OR NEW.leave_accrued IS NOT NULL
            OR NEW.leave_used IS NOT NULL
            OR NEW.leave_remaining IS NOT NULL
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
        ELSIF TG_OP = 'UPDATE' AND (
            NEW.home_branch_id IS DISTINCT FROM OLD.home_branch_id
            OR NEW.leave_accrued IS DISTINCT FROM OLD.leave_accrued
            OR NEW.leave_used IS DISTINCT FROM OLD.leave_used
            OR NEW.leave_remaining IS DISTINCT FROM OLD.leave_remaining
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.employee_leave_writer_guard() OWNER TO console_leave_definer;

--
-- Name: import_employee_leave_balance(uuid, uuid, timestamp with time zone, text, text, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.import_employee_leave_balance(p_org_id uuid, p_employee_id uuid, p_expected_updated_at timestamp with time zone, p_leave_accrued text, p_leave_used text, p_leave_remaining text, p_source_kind text, p_source_ref text, p_idempotency_key text, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(employee_id uuid, updated_at timestamp with time zone, changed boolean, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE
    v_old_accrued NUMERIC(16,6);
    v_old_used NUMERIC(16,6);
    v_old_remaining NUMERIC(16,6);
    v_old_updated TIMESTAMPTZ;
    v_new_accrued NUMERIC(16,6);
    v_new_used NUMERIC(16,6);
    v_new_remaining NUMERIC(16,6);
    v_new_updated TIMESTAMPTZ;
    v_payload JSONB;
    v_digest TEXT;
    v_receipt public.leave_balance_import_receipts%ROWTYPE;
    v_changed BOOLEAN;
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_actor,p_trace_id,p_span_id);
    PERFORM leave_api.assert_employee_importer(p_org_id,p_actor);
    IF p_source_kind <> 'employee_import'
       OR char_length(pg_catalog.btrim(p_source_ref)) NOT BETWEEN 1 AND 256
       OR char_length(pg_catalog.btrim(p_idempotency_key)) NOT BETWEEN 16 AND 256 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_balance_import.invalid_source';
    END IF;
    IF (p_leave_accrued IS NOT NULL AND p_leave_accrued !~ '^-?(0|[1-9][0-9]*)(\.[0-9]{1,6})?$')
       OR (p_leave_used IS NOT NULL AND p_leave_used !~ '^-?(0|[1-9][0-9]*)(\.[0-9]{1,6})?$')
       OR (p_leave_remaining IS NOT NULL AND p_leave_remaining !~ '^-?(0|[1-9][0-9]*)(\.[0-9]{1,6})?$') THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_balance_import.invalid_amount';
    END IF;
    BEGIN
        v_new_accrued := p_leave_accrued::NUMERIC(16,6);
        v_new_used := p_leave_used::NUMERIC(16,6);
        v_new_remaining := p_leave_remaining::NUMERIC(16,6);
    EXCEPTION WHEN numeric_value_out_of_range THEN
        RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='leave_balance_import.amount_out_of_range';
    END;
    v_payload := pg_catalog.jsonb_build_object(
        'employee_id',p_employee_id,
        'leave_accrued',CASE WHEN v_new_accrued IS NULL THEN NULL ELSE v_new_accrued::TEXT END,
        'leave_used',CASE WHEN v_new_used IS NULL THEN NULL ELSE v_new_used::TEXT END,
        'leave_remaining',CASE WHEN v_new_remaining IS NULL THEN NULL ELSE v_new_remaining::TEXT END,
        'source_kind',p_source_kind,'source_ref',pg_catalog.btrim(p_source_ref)
    );
    v_digest := pg_catalog.encode(public.digest(v_payload::TEXT,'sha256'),'hex');
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_org_id::TEXT || ':' || p_idempotency_key, 166)
    );
    SELECT * INTO v_receipt FROM public.leave_balance_import_receipts r
     WHERE r.org_id=p_org_id AND r.idempotency_key=p_idempotency_key;
    IF FOUND THEN
        IF v_receipt.employee_id IS DISTINCT FROM p_employee_id
           OR v_receipt.payload_digest IS DISTINCT FROM v_digest THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_balance_import.idempotency_conflict';
        END IF;
        RETURN QUERY SELECT p_employee_id,v_receipt.result_updated_at,v_receipt.changed,true;
        RETURN;
    END IF;
    SELECT e.leave_accrued,e.leave_used,e.leave_remaining,e.updated_at
      INTO v_old_accrued,v_old_used,v_old_remaining,v_old_updated
      FROM public.employees e WHERE e.org_id=p_org_id AND e.id=p_employee_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_balance_import.employee_not_found';
    END IF;
    IF v_old_updated IS DISTINCT FROM p_expected_updated_at THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_balance_import.concurrent_modification';
    END IF;
    v_changed := v_old_accrued IS DISTINCT FROM v_new_accrued
        OR v_old_used IS DISTINCT FROM v_new_used
        OR v_old_remaining IS DISTINCT FROM v_new_remaining;
    IF v_changed THEN
        UPDATE public.employees e
           SET leave_accrued=v_new_accrued,leave_used=v_new_used,
               leave_remaining=v_new_remaining,updated_at=pg_catalog.clock_timestamp()
         WHERE e.org_id=p_org_id AND e.id=p_employee_id
         RETURNING e.updated_at INTO v_new_updated;
        INSERT INTO public.audit_events
            (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
             trace_id,span_id,occurred_at,org_id)
        VALUES
            (p_actor,'employee.leave_balance_import','employee',p_employee_id::TEXT,NULL,
             pg_catalog.jsonb_build_object(
                 'leave_accrued',v_old_accrued::TEXT,'leave_used',v_old_used::TEXT,
                 'leave_remaining',v_old_remaining::TEXT,'updated_at',v_old_updated),
             v_payload || pg_catalog.jsonb_build_object('updated_at',v_new_updated,
                 'idempotency_key',p_idempotency_key),
             p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
    ELSE
        v_new_updated := v_old_updated;
    END IF;
    INSERT INTO public.leave_balance_import_receipts
        (org_id,employee_id,source_kind,source_ref,idempotency_key,payload_digest,
         result_updated_at,changed,actor,trace_id,span_id)
    VALUES
        (p_org_id,p_employee_id,p_source_kind,pg_catalog.btrim(p_source_ref),p_idempotency_key,
         v_digest,v_new_updated,v_changed,p_actor,p_trace_id,p_span_id);
    RETURN QUERY SELECT p_employee_id,v_new_updated,v_changed,false;
END;
$_$;


ALTER FUNCTION leave_api.import_employee_leave_balance(p_org_id uuid, p_employee_id uuid, p_expected_updated_at timestamp with time zone, p_leave_accrued text, p_leave_used text, p_leave_remaining text, p_source_kind text, p_source_ref text, p_idempotency_key text, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: kr_labor_guardrails_guard(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.kr_labor_guardrails_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.reason IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'leave_write.kr_annual_no_reason';
        END IF;
        IF NEW.status IN ('returned', 'rejected') THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'leave_write.kr_no_refusal';
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.reason IS NOT NULL AND NEW.reason IS DISTINCT FROM OLD.reason THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'leave_write.kr_annual_no_reason';
        END IF;
        IF NEW.status IN ('returned', 'rejected') AND NEW.status IS DISTINCT FROM OLD.status THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'leave_write.kr_no_refusal';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.kr_labor_guardrails_guard() OWNER TO console_leave_definer;

--
-- Name: legacy_leave_audit_required(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.legacy_leave_audit_required() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_action TEXT;
    v_actor UUID;
    v_matching_audits BIGINT;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_action := 'leave_request.create';
        v_actor := NEW.requester_user_id;
    ELSIF TG_OP = 'UPDATE'
       AND OLD.status = 'pending'
       AND NEW.status IN ('approved', 'returned', 'rejected') THEN
        v_action := 'leave_request.decide';
        v_actor := NEW.decided_by;
    ELSE
        RETURN NEW;
    END IF;

    PERFORM pg_catalog.set_config('app.current_org', NEW.org_id::TEXT, true);
    SELECT pg_catalog.count(*)
      INTO v_matching_audits
      FROM public.audit_events a
     WHERE a.org_id = NEW.org_id
       AND a.action = v_action
       AND a.target_type = 'leave_request'
       AND a.target_id = NEW.id::TEXT
       AND a.actor = v_actor
       AND a.branch_id IS NOT DISTINCT FROM NEW.branch_id
       AND a.xmin = pg_catalog.pg_current_xact_id()::xid;
    IF v_matching_audits <> 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'leave_request.current_transaction_audit_required';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.legacy_leave_audit_required() OWNER TO console_leave_definer;

--
-- Name: propose_alternate_dates(uuid, uuid, uuid, date, date, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.propose_alternate_dates(p_org_id uuid, p_request_id uuid, p_proposer uuid, p_start_date date, p_end_date date, p_trace_id text, p_span_id text) RETURNS TABLE(request_id uuid, request_version bigint, alternate_start_date date, alternate_end_date date, alternate_partial_day_period text, alternate_proposed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_request public.leave_requests%ROWTYPE;
    v_proposed_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_proposer,p_trace_id,p_span_id);
    IF p_end_date < p_start_date THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_alternate.invalid_dates';
    END IF;
    IF (p_end_date - p_start_date) >= 366 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_alternate.invalid_dates';
    END IF;
    SELECT * INTO v_request FROM public.leave_requests lr
     WHERE lr.org_id=p_org_id AND lr.id=p_request_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_alternate.not_found';
    END IF;
    IF v_request.status <> 'time_change_consult' THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_alternate.not_consult';
    END IF;
    IF v_request.requester_user_id <> p_proposer THEN
        -- 대체 일자는 근로자 선택 — employer/manager writes are unrepresentable.
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='leave_alternate.requester_only';
    END IF;
    IF v_request.alternate_start_date IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_alternate.already_proposed';
    END IF;
    IF p_start_date = v_request.start_date AND p_end_date = v_request.end_date THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_alternate.same_as_original';
    END IF;
    IF v_request.leave_type = 'half_day' AND p_start_date <> p_end_date THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='leave_alternate.invalid_dates';
    END IF;

    UPDATE public.leave_requests
       SET alternate_start_date = p_start_date,
           alternate_end_date = p_end_date,
           alternate_partial_day_period = v_request.partial_day_period,
           alternate_proposed_at = v_proposed_at,
           request_version = v_request.request_version + 1
     WHERE org_id = p_org_id AND id = p_request_id
    RETURNING * INTO v_request;

    INSERT INTO public.audit_events
        (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
         trace_id,span_id,occurred_at,org_id)
    VALUES
        (p_proposer,'leave_request.alternate_dates_proposed','leave_request',
         p_request_id::TEXT, v_request.branch_id,
         pg_catalog.jsonb_build_object(
            'start_date', v_request.start_date,
            'end_date', v_request.end_date),
         pg_catalog.jsonb_build_object(
            'alternate_start_date', p_start_date,
            'alternate_end_date', p_end_date,
            'alternate_partial_day_period', v_request.partial_day_period,
            'request_version', v_request.request_version),
         p_trace_id,p_span_id,v_proposed_at,p_org_id);

    RETURN QUERY SELECT
        v_request.id,
        v_request.request_version,
        v_request.alternate_start_date,
        v_request.alternate_end_date,
        v_request.alternate_partial_day_period,
        v_request.alternate_proposed_at;
END;
$$;


ALTER FUNCTION leave_api.propose_alternate_dates(p_org_id uuid, p_request_id uuid, p_proposer uuid, p_start_date date, p_end_date date, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: protected_audit_writer_guard(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.protected_audit_writer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    -- The expand window also preserves the base adapter's atomic audit write.
    -- It may attest only the legacy create/decide mutation already visible in
    -- the same transaction; exact-charge and employee-import actions remain
    -- exclusive to the command definer.
    IF current_user = 'console_rt' AND NEW.action = 'leave_request.create'
       AND NEW.target_type = 'leave_request'
       AND EXISTS (
           SELECT 1 FROM public.leave_requests lr
           WHERE lr.org_id = NEW.org_id
             AND lr.id::TEXT = NEW.target_id
             AND lr.requester_user_id = NEW.actor
             AND lr.branch_id IS NOT DISTINCT FROM NEW.branch_id
             AND lr.status = 'pending'
             AND lr.days IS NOT NULL
             AND lr.xmin = pg_catalog.pg_current_xact_id()::xid
       ) THEN
        RETURN NEW;
    ELSIF current_user = 'console_rt' AND NEW.action = 'leave_request.decide'
       AND NEW.target_type = 'leave_request'
       AND EXISTS (
           SELECT 1 FROM public.leave_requests lr
           WHERE lr.org_id = NEW.org_id
             AND lr.id::TEXT = NEW.target_id
             AND lr.decided_by = NEW.actor
             AND lr.branch_id IS NOT DISTINCT FROM NEW.branch_id
             AND lr.status IN ('approved', 'returned', 'rejected')
             AND lr.xmin = pg_catalog.pg_current_xact_id()::xid
       ) THEN
        RETURN NEW;
    ELSIF current_user = 'console_rt' AND NEW.action = 'data_import.apply'
       AND NEW.target_type = 'data_import_run'
       AND NEW.target_id ~ '^[0-9a-fA-F-]{36}$'
       AND NEW.branch_id IS NULL
       AND NEW.before_snap IS NULL
       AND NEW.ip IS NULL
       AND NEW.user_agent IS NULL
       AND NEW.auth_method IS NULL
       AND NEW.device IS NULL
       AND NEW.classification_badges IS NULL
       AND NEW.anomaly IS NULL
       AND NEW.reason IS NULL
       AND NEW.after_snap IS NOT DISTINCT FROM pg_catalog.jsonb_build_object(
            'run_id', NEW.target_id::UUID,
            'entity_type', 'employee_hr',
            'gate_outcome', pg_catalog.jsonb_build_object(
                'gates', pg_catalog.jsonb_build_array(
                    pg_catalog.jsonb_build_object(
                        'gate', 'authority',
                        'status', pg_catalog.jsonb_build_object('status', 'not_required')
                    ),
                    pg_catalog.jsonb_build_object(
                        'gate', 'self_checklist',
                        'status', pg_catalog.jsonb_build_object('status', 'satisfied')
                    ),
                    pg_catalog.jsonb_build_object(
                        'gate', 'four_eyes',
                        'status', pg_catalog.jsonb_build_object('status', 'not_required')
                    ),
                    pg_catalog.jsonb_build_object(
                        'gate', 'egress_dlp',
                        'status', pg_catalog.jsonb_build_object('status', 'not_required')
                    )
                ),
                'allow', true
            )
       )
       AND EXISTS (
           SELECT 1 FROM public.data_import_runs r
           JOIN public.users u
             ON u.id = NEW.actor
            AND u.org_id = NEW.org_id
            AND u.is_active
           WHERE r.org_id = NEW.org_id
             AND r.id = NEW.target_id::UUID
             AND r.entity_type = 'employee_hr'
             AND r.status = 'APPLIED'
             AND r.applied_by = NEW.actor
             AND r.xmin = pg_catalog.pg_current_xact_id()::xid
       ) THEN
        -- Exact f6ff236 with_audit ordering: the legacy run transition is
        -- visible in this transaction before its run-level audit is appended.
        -- This does not authorize command-owned balance receipts or any other
        -- protected leave action.
        RETURN NEW;
    END IF;
    IF NEW.action = ANY (ARRAY[
        'employee.home_branch_set',
        'employee.leave_balance_import',
        'data_import.apply',
        'leave_request.create',
        'leave_request.charge_resolve',
        'leave_request.decide',
        'leave_request.approval_blocked'
    ]::TEXT[]) AND current_user <> 'console_leave_definer' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_audit.command_required';
    END IF;
    RETURN NEW;
END;
$_$;


ALTER FUNCTION leave_api.protected_audit_writer_guard() OWNER TO console_leave_definer;

--
-- Name: protected_request_writer_guard(); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.protected_request_writer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF current_user = 'console_rt' AND TG_OP = 'INSERT' THEN
        IF NEW.days IS NULL
           OR NEW.status <> 'pending'
           OR NEW.decided_by IS NOT NULL
           OR NEW.decided_at IS NOT NULL
           OR NEW.decision_comment IS NOT NULL
           OR NEW.ap_run_id IS NOT NULL
           OR NEW.partial_day_period IS NOT NULL
           OR NEW.charge_state <> 'review_required'
           OR NEW.charge_review_reasons <> ARRAY['missing_calendar']::TEXT[]
           OR NEW.charge_units IS NOT NULL
           OR NEW.submission_key IS NOT NULL
           OR NEW.submission_digest IS NOT NULL
           OR NEW.submission_initial_charge_version IS NOT NULL
           OR NEW.request_version <> 1
           OR NEW.charge_version <> 0
           OR NEW.current_charge_resolution_id IS NOT NULL
           OR NEW.time_change_grounds IS NOT NULL
           OR NEW.time_change_evidence IS NOT NULL
           OR NEW.alternate_start_date IS NOT NULL
           OR NEW.alternate_end_date IS NOT NULL
           OR NEW.alternate_partial_day_period IS NOT NULL
           OR NEW.alternate_proposed_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
        END IF;
        RETURN NEW;
    ELSIF current_user = 'console_rt' AND TG_OP = 'UPDATE' THEN
        IF OLD.status <> 'pending'
           OR NEW.status <> 'approved'
           OR NEW.status IS NOT DISTINCT FROM OLD.status
           OR NEW.decided_by IS NULL
           OR NEW.decided_at IS NULL
           OR NEW.requester_user_id = NEW.decided_by
           OR NEW.id IS DISTINCT FROM OLD.id
           OR NEW.org_id IS DISTINCT FROM OLD.org_id
           OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
           OR NEW.requester_user_id IS DISTINCT FROM OLD.requester_user_id
           OR NEW.subject_employee_id IS DISTINCT FROM OLD.subject_employee_id
           OR NEW.leave_type IS DISTINCT FROM OLD.leave_type
           OR NEW.days IS DISTINCT FROM OLD.days
           OR NEW.start_date IS DISTINCT FROM OLD.start_date
           OR NEW.end_date IS DISTINCT FROM OLD.end_date
           OR NEW.reason IS DISTINCT FROM OLD.reason
           OR NEW.ap_run_id IS DISTINCT FROM OLD.ap_run_id
           OR NEW.partial_day_period IS DISTINCT FROM OLD.partial_day_period
           OR NEW.charge_state IS DISTINCT FROM OLD.charge_state
           OR NEW.charge_review_reasons IS DISTINCT FROM OLD.charge_review_reasons
           OR NEW.charge_units IS DISTINCT FROM OLD.charge_units
           OR NEW.submission_key IS DISTINCT FROM OLD.submission_key
           OR NEW.submission_digest IS DISTINCT FROM OLD.submission_digest
           OR NEW.submission_initial_charge_version IS DISTINCT FROM OLD.submission_initial_charge_version
           OR NEW.request_version IS DISTINCT FROM OLD.request_version
           OR NEW.charge_version IS DISTINCT FROM OLD.charge_version
           OR NEW.current_charge_resolution_id IS DISTINCT FROM OLD.current_charge_resolution_id
           OR NEW.time_change_grounds IS DISTINCT FROM OLD.time_change_grounds
           OR NEW.time_change_evidence IS DISTINCT FROM OLD.time_change_evidence
           OR NEW.alternate_start_date IS DISTINCT FROM OLD.alternate_start_date
           OR NEW.alternate_end_date IS DISTINCT FROM OLD.alternate_end_date
           OR NEW.alternate_partial_day_period IS DISTINCT FROM OLD.alternate_partial_day_period
           OR NEW.alternate_proposed_at IS DISTINCT FROM OLD.alternate_proposed_at THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
        END IF;
        NEW.request_version := OLD.request_version + 1;
        NEW.charge_state := 'legacy_unverified';
        NEW.charge_review_reasons := ARRAY[]::TEXT[];
        NEW.charge_units := OLD.days;
        RETURN NEW;
    ELSIF current_user <> 'console_leave_definer' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'leave_write.command_required';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION leave_api.protected_request_writer_guard() OWNER TO console_leave_definer;

--
-- Name: resolve_charge(uuid, uuid, uuid, bigint, jsonb, jsonb, jsonb, jsonb, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.resolve_charge(p_org_id uuid, p_request_id uuid, p_resolver uuid, p_expected_version bigint, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb, p_trace_id text, p_span_id text) RETURNS TABLE(request_id uuid, request_version bigint, charge_version bigint, charge_micros bigint, server_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_request public.leave_requests%ROWTYPE;
    v_snapshot JSONB;
    v_units NUMERIC(16,6);
    v_digest TEXT;
    v_next_request BIGINT;
    v_next_charge BIGINT;
    v_resolution_id UUID := public.gen_random_uuid();
BEGIN
    PERFORM leave_api.assert_context(p_org_id, p_resolver, p_trace_id, p_span_id);
    SELECT * INTO v_request FROM public.leave_requests lr
     WHERE lr.org_id = p_org_id AND lr.id = p_request_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_resolve.not_found'; END IF;
    PERFORM leave_api.assert_manager(p_org_id, p_resolver, v_request.branch_id);
    IF v_request.status <> 'pending' THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_resolve.not_pending';
    END IF;
    IF v_request.request_version <> p_expected_version THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_resolve.concurrent_modification';
    END IF;
    IF v_request.requester_user_id = p_resolver THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='leave_resolve.requester_forbidden';
    END IF;
    SELECT c.snapshot, c.charge_units, c.server_digest
      INTO v_snapshot, v_units, v_digest
      FROM leave_api.canonical_charge_snapshot(v_request.branch_id,
           v_request.leave_type, v_request.partial_day_period,
           v_request.start_date, v_request.end_date, p_date_charges,
           p_calendar_revision_ref, p_policy_revision_ref,
           p_supporting_source_refs) c;
    v_next_request := v_request.request_version + 1;
    v_next_charge := v_request.charge_version + 1;
    IF v_next_request <= v_request.request_version OR v_next_charge <= v_request.charge_version THEN
        RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='leave_resolve.version_exhausted';
    END IF;
    INSERT INTO public.leave_charge_resolutions
        (id, org_id, request_id, charge_version, home_branch_id, charge_units,
         date_charges, calendar_revision_ref, policy_revision_ref,
         supporting_source_refs, snapshot, server_digest, resolution_origin,
         resolved_by, resolved_at)
    VALUES
        (v_resolution_id, p_org_id, p_request_id, v_next_charge, v_request.branch_id,
         v_units, p_date_charges, p_calendar_revision_ref, p_policy_revision_ref,
         p_supporting_source_refs, v_snapshot, v_digest, 'manual', p_resolver, pg_catalog.statement_timestamp());
    UPDATE public.leave_requests
       SET charge_state='resolved', charge_review_reasons=ARRAY[]::TEXT[],
           charge_units=v_units, request_version=v_next_request,
           charge_version=v_next_charge,
           current_charge_resolution_id=v_resolution_id
     WHERE org_id=p_org_id AND id=p_request_id;
    INSERT INTO public.audit_events
        (actor, action, target_type, target_id, branch_id, before_snap, after_snap,
         trace_id, span_id, occurred_at, org_id)
    VALUES
        (p_resolver,'leave_request.charge_resolve','leave_request',p_request_id::TEXT,
         v_request.branch_id,
         pg_catalog.jsonb_build_object('charge_state',v_request.charge_state,
             'request_version',v_request.request_version,
             'charge_version',v_request.charge_version),
         pg_catalog.jsonb_build_object('charge_state','resolved',
             'request_version',v_next_request,'charge_version',v_next_charge,
             'charge_units',v_units,'server_digest',v_digest),
         p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
    RETURN QUERY SELECT p_request_id,v_next_request,v_next_charge,
        (v_units * 1000000)::BIGINT,v_digest;
END;
$$;


ALTER FUNCTION leave_api.resolve_charge(p_org_id uuid, p_request_id uuid, p_resolver uuid, p_expected_version bigint, p_date_charges jsonb, p_calendar_revision_ref jsonb, p_policy_revision_ref jsonb, p_supporting_source_refs jsonb, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: set_employee_home_branch(uuid, uuid, uuid, timestamp with time zone, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.set_employee_home_branch(p_org_id uuid, p_employee_id uuid, p_home_branch_id uuid, p_expected_updated_at timestamp with time zone, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(employee_id uuid, home_branch_id uuid, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_old_branch UUID;
    v_old_updated TIMESTAMPTZ;
    v_new_updated TIMESTAMPTZ;
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_actor,p_trace_id,p_span_id);
    SELECT e.home_branch_id,e.updated_at INTO v_old_branch,v_old_updated
      FROM public.employees e WHERE e.org_id=p_org_id AND e.id=p_employee_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_home_branch.employee_not_found'; END IF;
    IF v_old_updated IS DISTINCT FROM p_expected_updated_at THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_home_branch.concurrent_modification';
    END IF;
    IF v_old_branch IS NULL OR v_old_branch = p_home_branch_id THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_home_branch_id::TEXT, 166));
    ELSIF v_old_branch::TEXT < p_home_branch_id::TEXT THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_old_branch::TEXT, 166));
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_home_branch_id::TEXT, 166));
    ELSE
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_home_branch_id::TEXT, 166));
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_old_branch::TEXT, 166));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.branches b WHERE b.org_id=p_org_id
                   AND b.id=p_home_branch_id AND b.deactivated_at IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_home_branch.active_branch_required';
    END IF;
    IF v_old_branch IS NULL THEN
        -- An unassigned employee has no branch-scoped owner yet. Only the
        -- organization-wide SUPER_ADMIN capability may establish that first
        -- routing authority; a target-branch admin cannot claim the employee.
        PERFORM leave_api.assert_org_admin(p_org_id,p_actor);
    ELSE
        PERFORM leave_api.assert_manager(p_org_id,p_actor,v_old_branch);
        PERFORM leave_api.assert_manager(p_org_id,p_actor,p_home_branch_id);
    END IF;
    UPDATE public.employees e SET home_branch_id=p_home_branch_id,updated_at=pg_catalog.now()
     WHERE e.org_id=p_org_id AND e.id=p_employee_id RETURNING e.updated_at INTO v_new_updated;
    INSERT INTO public.audit_events
        (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
         trace_id,span_id,occurred_at,org_id)
    VALUES
        (p_actor,'employee.home_branch_set','employee',p_employee_id::TEXT,p_home_branch_id,
         pg_catalog.jsonb_build_object('home_branch_id',v_old_branch,'updated_at',v_old_updated),
         pg_catalog.jsonb_build_object('home_branch_id',p_home_branch_id,'updated_at',v_new_updated),
         p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
    RETURN QUERY SELECT p_employee_id,p_home_branch_id,v_new_updated;
END;
$$;


ALTER FUNCTION leave_api.set_employee_home_branch(p_org_id uuid, p_employee_id uuid, p_home_branch_id uuid, p_expected_updated_at timestamp with time zone, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: set_employee_home_branch_create(uuid, uuid, uuid, timestamp with time zone, uuid, text, text); Type: FUNCTION; Schema: leave_api; Owner: console_leave_definer
--

CREATE FUNCTION leave_api.set_employee_home_branch_create(p_org_id uuid, p_employee_id uuid, p_home_branch_id uuid, p_expected_updated_at timestamp with time zone, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(employee_id uuid, home_branch_id uuid, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_old_branch UUID;
    v_old_updated TIMESTAMPTZ;
    v_new_updated TIMESTAMPTZ;
BEGIN
    PERFORM leave_api.assert_context(p_org_id,p_actor,p_trace_id,p_span_id);
    SELECT e.home_branch_id,e.updated_at INTO v_old_branch,v_old_updated
      FROM public.employees e WHERE e.org_id=p_org_id AND e.id=p_employee_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_home_branch.employee_not_found'; END IF;
    IF v_old_updated IS DISTINCT FROM p_expected_updated_at THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_home_branch.concurrent_modification';
    END IF;
    IF v_old_branch IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='leave_home_branch.already_assigned';
    END IF;
    -- Server-side creation evidence: the actor must have CREATED this employee via
    -- the create flow (an `employee.create` audit by p_actor for THIS employee with
    -- the requested branch). Not caller-controllable, so the create-scoped
    -- directory-manager authority cannot be claimed for an arbitrary employee.
    IF NOT EXISTS (
        SELECT 1 FROM public.audit_events a
        WHERE a.org_id = p_org_id
          AND a.action = 'employee.create'
          AND a.actor = p_actor
          AND a.target_type = 'employee'
          AND a.target_id = p_employee_id::TEXT
          AND a.after_snap->>'requested_home_branch_id' = p_home_branch_id::TEXT
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'employee_create.home_branch_create_required';
    END IF;
    -- The SAME predicate the in-transaction create recheck ran.
    PERFORM leave_api.assert_employee_directory_manager(p_org_id,p_actor);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_home_branch_id::TEXT, 166));
    IF NOT EXISTS (SELECT 1 FROM public.branches b WHERE b.org_id=p_org_id
                   AND b.id=p_home_branch_id AND b.deactivated_at IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='leave_home_branch.active_branch_required';
    END IF;
    UPDATE public.employees e SET home_branch_id=p_home_branch_id,updated_at=pg_catalog.now()
     WHERE e.org_id=p_org_id AND e.id=p_employee_id RETURNING e.updated_at INTO v_new_updated;
    INSERT INTO public.audit_events
        (actor,action,target_type,target_id,branch_id,before_snap,after_snap,
         trace_id,span_id,occurred_at,org_id)
    VALUES
        (p_actor,'employee.home_branch_set','employee',p_employee_id::TEXT,p_home_branch_id,
         pg_catalog.jsonb_build_object('home_branch_id',v_old_branch,'updated_at',v_old_updated),
         pg_catalog.jsonb_build_object('home_branch_id',p_home_branch_id,'updated_at',v_new_updated),
         p_trace_id,p_span_id,pg_catalog.statement_timestamp(),p_org_id);
    RETURN QUERY SELECT p_employee_id,p_home_branch_id,v_new_updated;
END;
$$;


ALTER FUNCTION leave_api.set_employee_home_branch_create(p_org_id uuid, p_employee_id uuid, p_home_branch_id uuid, p_expected_updated_at timestamp with time zone, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_leave_definer;

--
-- Name: attach_object_policy(uuid, uuid, uuid, text, jsonb, text, text, text); Type: FUNCTION; Schema: ont_policy_api; Owner: console_ontology_writer
--

CREATE FUNCTION ont_policy_api.attach_object_policy(p_org_id uuid, p_created_by uuid, p_object_type_id uuid, p_effect text, p_normalized_row jsonb, p_schema_version text, p_trace_id text, p_span_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_policy_id UUID;
    v_occurred_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    v_policy_id := ont_policy_api.attach_object_policy_rows(
        p_org_id, p_created_by, p_object_type_id, p_effect,
        p_normalized_row, p_schema_version);

    -- LAST. See the header: the catalog INSERT inside the row-writer is what the
    -- org floor refuses on a cross-org call, and moving this above it moves that
    -- proof onto `audit_events`.
    --
    -- `id` is omitted so the 0003:11 `DEFAULT gen_random_uuid()` supplies it:
    -- column defaults carry resolved function OIDs, so they are unaffected by
    -- this routine's pinned `search_path`.
    --
    -- The request-context columns (ip, user_agent, auth_method, device,
    -- classification) stay NULL, which is exactly what the application wrote:
    -- `audit_event` (`platform/authz-rest/src/store.rs`) built the event with
    -- `AuditEvent::new` and never attached a request context.
    INSERT INTO public.audit_events
        (actor, action, target_type, target_id, branch_id,
         before_snap, after_snap, trace_id, span_id, occurred_at, org_id)
    VALUES
        (p_created_by, 'ontology.object_policy.attach',
         'ont_object_policies', p_object_type_id::TEXT, NULL,
         NULL, p_normalized_row, p_trace_id, p_span_id, v_occurred_at, p_org_id);

    RETURN v_policy_id;
END;
$$;


ALTER FUNCTION ont_policy_api.attach_object_policy(p_org_id uuid, p_created_by uuid, p_object_type_id uuid, p_effect text, p_normalized_row jsonb, p_schema_version text, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: attach_object_policy_rows(uuid, uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: ont_policy_api; Owner: console_ontology_writer
--

CREATE FUNCTION ont_policy_api.attach_object_policy_rows(p_org_id uuid, p_created_by uuid, p_object_type_id uuid, p_effect text, p_normalized_row jsonb, p_schema_version text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_policy_id UUID;
    v_type_key TEXT;
BEGIN
    -- The attached type, resolved under the caller's org floor. There is no FK
    -- on ont_object_policies.object_type_id (0154:29), so an unresolvable or
    -- foreign id would otherwise attach an enforced policy to nothing.
    SELECT stable_key INTO v_type_key
      FROM public.ont_object_types
     WHERE id = p_object_type_id;
    IF v_type_key IS NULL THEN
        RAISE EXCEPTION 'attach refused: unknown object type %', p_object_type_id;
    END IF;

    -- A row whose resource_type disagrees with the type it is attached to never
    -- matches `applicable_object_policies`, so it denies forever at HTTP 200 []
    -- — a silent failure no post-hoc test can see.
    IF p_normalized_row ->> 'resource_type' IS DISTINCT FROM v_type_key THEN
        RAISE EXCEPTION 'attach refused: normalized_row resource_type % is not the attached object type %',
            p_normalized_row ->> 'resource_type', v_type_key;
    END IF;

    -- The route pins this to `authoring::OBJECT_POLICY_ACTION`; so does the
    -- read path's `applicable_object_policies` filter.
    IF p_normalized_row ->> 'action' IS DISTINCT FROM 'view' THEN
        RAISE EXCEPTION 'attach refused: normalized_row action % is not the object-policy action',
            p_normalized_row ->> 'action';
    END IF;

    -- The 0170 trigger only compares CATALOG to ATTACHMENT, and both of those
    -- are bound from p_effect below, so a blocks/catalog disagreement sails
    -- through it. This is the only place that comparison happens.
    IF p_normalized_row ->> 'effect' IS DISTINCT FROM p_effect THEN
        RAISE EXCEPTION 'attach refused: normalized_row effect % disagrees with the attachment effect %',
            p_normalized_row ->> 'effect', p_effect;
    END IF;

    -- Mirrors MAX_ATTACHED_CONDITIONS (`ontology/rest/src/lib.rs:494`). Both
    -- tables are append-only, so an oversized list is permanent work charged to
    -- every later read of the type.
    IF jsonb_typeof(p_normalized_row -> 'conditions') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_normalized_row -> 'conditions') > 32 THEN
        RAISE EXCEPTION 'attach refused: conditions must be an array of at most 32 entries';
    END IF;

    INSERT INTO public.cedar_policy_catalog_entries
        (org_id, stable_key, title, natural_language_rule, effect, status, source,
         principal, action, resource, conditions,
         policy_version, schema_version, bundle_digest,
         validation_status, normalized_row, generated_policy_text,
         created_by, updated_by)
    VALUES
        (p_org_id,
         -- Dotted with >= 2 segments (0150:11) and UNIQUE per (org, key, status),
         -- so it carries the type it policies plus a fresh discriminator: two
         -- policies on one type is a supported shape, not a conflict.
         'object_policy.' || v_type_key || '.' || replace(gen_random_uuid()::text, '-', ''),
         -- title is bounded to 120 chars and the rule to 1000 (0150:12-13),
         -- while an object-type key has no length CHECK at all (0152:20 is
         -- shape-only). Bound the human-readable label; never the matching key.
         'Object policy: ' || left(v_type_key, 80),
         CASE p_effect WHEN 'permit' THEN 'Permit' ELSE 'Forbid' END
             || ' viewing rows of ' || left(v_type_key, 80)
             || ' when every authored condition holds.',
         p_effect,
         'enforced', 'no_code_draft',
         '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[]'::jsonb,
         1, p_schema_version,
         -- Derived from the row actually stored beside it. A supplied digest is a
         -- stored false attestation that nothing ever re-checks. `normalized_row`
         -- and not the policy text, because the policy text is no longer stored:
         -- a digest over a NULL is NULL and fails the enforced-row CHECK, and a
         -- digest over the empty string would attest nothing at all.
         -- `jsonb::text` is canonical (keys sorted, whitespace fixed), so this is
         -- stable for a given row.
         'sha256:' || encode(sha256(convert_to(p_normalized_row::text, 'UTF8')), 'hex'),
         'valid', p_normalized_row, NULL,
         p_created_by, p_created_by)
    RETURNING id INTO v_policy_id;

    INSERT INTO public.ont_object_policies
        (org_id, object_type_id, cedar_policy_id, effect, created_by)
    VALUES
        (p_org_id, p_object_type_id, v_policy_id, p_effect, p_created_by);

    RETURN v_policy_id;
END;
$$;


ALTER FUNCTION ont_policy_api.attach_object_policy_rows(p_org_id uuid, p_created_by uuid, p_object_type_id uuid, p_effect text, p_normalized_row jsonb, p_schema_version text) OWNER TO console_ontology_writer;

--
-- Name: assert_write_context(uuid, uuid, text, text); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.assert_write_context(p_org_id uuid, p_actor uuid, p_trace_id text, p_span_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $_$
DECLARE
    v_current_org UUID := NULLIF(pg_catalog.current_setting('app.current_org', true), '')::UUID;
BEGIN
    IF v_current_org IS NULL OR v_current_org <> p_org_id THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_write.tenant_context_mismatch';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.users u
        WHERE u.id = p_actor AND u.org_id = p_org_id AND u.is_active
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_write.actor_forbidden';
    END IF;
    IF p_trace_id !~ '^[0-9a-f]{32}$' OR p_span_id !~ '^[0-9a-f]{16}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_write.invalid_trace';
    END IF;
END;
$_$;


ALTER FUNCTION ontology_api.assert_write_context(p_org_id uuid, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: create_object_type(uuid, jsonb, uuid, text, text); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.create_object_type(p_org_id uuid, p_snapshot jsonb, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(object_type_id uuid, stable_key text, title text, backing_kind text, schema_version bigint, lifecycle_state text, key_write_validator_id uuid, key_write_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_id UUID := public.gen_random_uuid();
    v_validator UUID;
    v_stable_key TEXT := pg_catalog.btrim(p_snapshot->>'stable_key');
    v_title TEXT := pg_catalog.btrim(p_snapshot->>'title');
    v_backing_kind TEXT := p_snapshot->>'backing_kind';
    v_occurred_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    PERFORM ontology_api.assert_write_context(p_org_id, p_actor, p_trace_id, p_span_id);
    IF pg_catalog.jsonb_typeof(p_snapshot) <> 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_write.invalid_snapshot_shape';
    END IF;

    -- Serialize the only two paths that can create a tenant's first registry
    -- row. The installer must never pass its empty-org check concurrently with
    -- an ordinary create, regardless of catalog version.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('ontology-bootstrap:' || p_org_id::TEXT, 0)
    );

    INSERT INTO public.ont_object_type_key_revisions (org_id, stable_key)
    VALUES (p_org_id, v_stable_key)
    RETURNING ont_object_type_key_revisions.validator_id INTO v_validator;

    INSERT INTO public.ont_object_types
        (id, org_id, stable_key, title, title_property_key, backing_kind,
         backing_table, primary_key_property, schema_version, lifecycle_state,
         created_by, created_at, updated_at)
    VALUES
        (v_id, p_org_id, v_stable_key, v_title, NULLIF(p_snapshot->>'title_property_key', ''),
         v_backing_kind, NULLIF(p_snapshot->>'backing_table', ''),
         NULLIF(p_snapshot->>'primary_key_property', ''), 1, 'draft', p_actor,
         v_occurred_at, v_occurred_at);

    PERFORM ontology_api.insert_children(p_org_id, v_id, p_snapshot, FALSE);
    PERFORM ontology_api.write_audit(
        p_org_id, p_actor, 'ontology.object_type.create', v_id, NULL,
        pg_catalog.jsonb_build_object('stable_key', v_stable_key, 'schema_version', 1, 'lifecycle_state', 'draft'),
        p_trace_id, p_span_id, v_occurred_at);
    RETURN QUERY SELECT v_id, v_stable_key, v_title, v_backing_kind,
                        1::BIGINT, 'draft'::TEXT, v_validator, 1::BIGINT;
END;
$$;


ALTER FUNCTION ontology_api.create_object_type(p_org_id uuid, p_snapshot jsonb, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: insert_children(uuid, uuid, jsonb, boolean); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.insert_children(p_org_id uuid, p_object_type_id uuid, p_snapshot jsonb, p_allow_existing boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_item JSONB;
    v_existing JSONB;
    v_key TEXT;
BEGIN
    IF pg_catalog.jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object'
       OR pg_catalog.jsonb_typeof(p_snapshot->'properties') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_snapshot->'links') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_snapshot->'actions') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(p_snapshot->'analytics') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_write.invalid_snapshot_shape';
    END IF;

    -- A staged draft is append-only for child identities. Its submitted full
    -- snapshot must retain every existing child byte-semantically after the
    -- same trim/default canonicalization used for incoming rows.
    IF p_allow_existing AND EXISTS (
        SELECT 1 FROM public.ont_property_defs d
        WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'properties', '[]'::JSONB)) i
              WHERE pg_catalog.btrim(i->>'key') = d.key
                AND pg_catalog.jsonb_build_object(
                    'key', pg_catalog.btrim(i->>'key'),
                    'title', pg_catalog.btrim(i->>'title'),
                    'field_type', pg_catalog.btrim(i->>'field_type'),
                    'config', COALESCE(i->'config', '{}'::JSONB),
                    'backing_column', i->'backing_column',
                    'required', COALESCE((i->>'required')::BOOLEAN, FALSE),
                    'in_property_policy', COALESCE((i->>'in_property_policy')::BOOLEAN, FALSE)
                ) = pg_catalog.jsonb_build_object(
                    'key', d.key, 'title', d.title, 'field_type', d.type,
                    'config', d.config, 'backing_column', pg_catalog.to_jsonb(d.backing_column),
                    'required', d.required, 'in_property_policy', d.in_property_policy
                )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.property_snapshot_conflict';
    END IF;

    IF p_allow_existing AND EXISTS (
        SELECT 1 FROM public.ont_link_types d
        WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'links', '[]'::JSONB)) i
              WHERE pg_catalog.btrim(i->>'stable_key') = d.stable_key
                AND pg_catalog.jsonb_build_object(
                    'stable_key', pg_catalog.btrim(i->>'stable_key'),
                    'title', pg_catalog.btrim(i->>'title'),
                    'reverse_title', CASE WHEN i->>'reverse_title' IS NULL THEN 'null'::JSONB ELSE pg_catalog.to_jsonb(pg_catalog.btrim(i->>'reverse_title')) END,
                    'to_object_type_id', i->'to_object_type_id',
                    'cardinality', i->'cardinality',
                    'traversable', COALESCE((i->>'traversable')::BOOLEAN, TRUE)
                ) = pg_catalog.jsonb_build_object(
                    'stable_key', d.stable_key, 'title', d.title,
                    'reverse_title', pg_catalog.to_jsonb(d.reverse_title),
                    'to_object_type_id', pg_catalog.to_jsonb(d.to_object_type_id),
                    'cardinality', d.cardinality, 'traversable', d.traversable
                )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.link_snapshot_conflict';
    END IF;

    IF p_allow_existing AND EXISTS (
        SELECT 1 FROM public.ont_action_types d
        WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'actions', '[]'::JSONB)) i
              WHERE pg_catalog.btrim(i->>'stable_key') = d.stable_key
                AND pg_catalog.jsonb_build_object(
                    'stable_key', pg_catalog.btrim(i->>'stable_key'),
                    'title', pg_catalog.btrim(i->>'title'),
                    'params_schema', COALESCE(i->'params_schema', '{}'::JSONB),
                    'edits', COALESCE(i->'edits', '[]'::JSONB),
                    'submission_criteria', COALESCE(i->'submission_criteria', '[]'::JSONB),
                    'side_effects', COALESCE(i->'side_effects', '[]'::JSONB),
                    'dispatch', i->'dispatch',
                    'dispatch_target', i->'dispatch_target',
                    'control_points', COALESCE(i->'control_points', '[]'::JSONB)
                ) = pg_catalog.jsonb_build_object(
                    'stable_key', d.stable_key, 'title', d.title,
                    'params_schema', d.params_schema, 'edits', d.edits,
                    'submission_criteria', d.submission_criteria,
                    'side_effects', d.side_effects, 'dispatch', d.dispatch,
                    'dispatch_target', pg_catalog.to_jsonb(d.dispatch_target),
                    'control_points', d.control_points
                )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.action_snapshot_conflict';
    END IF;

    IF p_allow_existing AND EXISTS (
        SELECT 1 FROM public.ont_analytics d
        WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'analytics', '[]'::JSONB)) i
              WHERE pg_catalog.btrim(i->>'key') = d.key
                AND pg_catalog.jsonb_build_object(
                    'key', pg_catalog.btrim(i->>'key'),
                    'title', pg_catalog.btrim(i->>'title'),
                    'formula', COALESCE(i->'formula', '{}'::JSONB),
                    'result_type', COALESCE(i->'result_type', '{}'::JSONB)
                ) = pg_catalog.jsonb_build_object(
                    'key', d.key, 'title', d.title,
                    'formula', d.formula, 'result_type', d.result_type
                )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.analytic_snapshot_conflict';
    END IF;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'properties', '[]'::JSONB)) LOOP
        v_key := pg_catalog.btrim(v_item->>'key');
        SELECT pg_catalog.jsonb_build_object(
                   'key', d.key, 'title', d.title, 'field_type', d.type,
                   'config', d.config, 'backing_column', pg_catalog.to_jsonb(d.backing_column),
                   'required', d.required, 'in_property_policy', d.in_property_policy)
          INTO v_existing
          FROM public.ont_property_defs d
         WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id AND d.key = v_key;
        IF FOUND THEN
            IF NOT p_allow_existing OR v_existing <> pg_catalog.jsonb_build_object(
                'key', v_key, 'title', pg_catalog.btrim(v_item->>'title'),
                'field_type', pg_catalog.btrim(v_item->>'field_type'),
                'config', COALESCE(v_item->'config', '{}'::JSONB),
                'backing_column', v_item->'backing_column',
                'required', COALESCE((v_item->>'required')::BOOLEAN, FALSE),
                'in_property_policy', COALESCE((v_item->>'in_property_policy')::BOOLEAN, FALSE)) THEN
                RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.property_key_conflict';
            END IF;
        ELSE
            INSERT INTO public.ont_property_defs
                (id, org_id, object_type_id, key, title, type, config, backing_column, required, in_property_policy)
            VALUES
                (public.gen_random_uuid(), p_org_id, p_object_type_id, v_key,
                 pg_catalog.btrim(v_item->>'title'), pg_catalog.btrim(v_item->>'field_type'),
                 COALESCE(v_item->'config', '{}'::JSONB), NULLIF(v_item->>'backing_column', ''),
                 COALESCE((v_item->>'required')::BOOLEAN, FALSE),
                 COALESCE((v_item->>'in_property_policy')::BOOLEAN, FALSE));
        END IF;
    END LOOP;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'links', '[]'::JSONB)) LOOP
        v_key := pg_catalog.btrim(v_item->>'stable_key');
        SELECT pg_catalog.jsonb_build_object(
                   'stable_key', d.stable_key, 'title', d.title,
                   'reverse_title', pg_catalog.to_jsonb(d.reverse_title),
                   'to_object_type_id', pg_catalog.to_jsonb(d.to_object_type_id),
                   'cardinality', d.cardinality, 'traversable', d.traversable)
          INTO v_existing
          FROM public.ont_link_types d
         WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id AND d.stable_key = v_key;
        IF FOUND THEN
            IF NOT p_allow_existing OR v_existing <> pg_catalog.jsonb_build_object(
                'stable_key', v_key, 'title', pg_catalog.btrim(v_item->>'title'),
                'reverse_title', CASE WHEN v_item->>'reverse_title' IS NULL THEN 'null'::JSONB ELSE pg_catalog.to_jsonb(pg_catalog.btrim(v_item->>'reverse_title')) END,
                'to_object_type_id', v_item->'to_object_type_id', 'cardinality', v_item->'cardinality',
                'traversable', COALESCE((v_item->>'traversable')::BOOLEAN, TRUE)) THEN
                RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.link_key_conflict';
            END IF;
        ELSE
            INSERT INTO public.ont_link_types
                (id, org_id, object_type_id, stable_key, title, reverse_title, to_object_type_id, cardinality, traversable)
            VALUES
                (public.gen_random_uuid(), p_org_id, p_object_type_id, v_key,
                 pg_catalog.btrim(v_item->>'title'), NULLIF(pg_catalog.btrim(v_item->>'reverse_title'), ''),
                 NULLIF(v_item->>'to_object_type_id', '')::UUID, v_item->>'cardinality',
                 COALESCE((v_item->>'traversable')::BOOLEAN, TRUE));
        END IF;
    END LOOP;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'actions', '[]'::JSONB)) LOOP
        v_key := pg_catalog.btrim(v_item->>'stable_key');
        SELECT pg_catalog.jsonb_build_object(
                   'stable_key', d.stable_key, 'title', d.title,
                   'params_schema', d.params_schema, 'edits', d.edits,
                   'submission_criteria', d.submission_criteria, 'side_effects', d.side_effects,
                   'dispatch', d.dispatch, 'dispatch_target', pg_catalog.to_jsonb(d.dispatch_target),
                   'control_points', d.control_points)
          INTO v_existing
          FROM public.ont_action_types d
         WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id AND d.stable_key = v_key;
        IF FOUND THEN
            IF NOT p_allow_existing OR v_existing <> pg_catalog.jsonb_build_object(
                'stable_key', v_key, 'title', pg_catalog.btrim(v_item->>'title'),
                'params_schema', COALESCE(v_item->'params_schema', '{}'::JSONB),
                'edits', COALESCE(v_item->'edits', '[]'::JSONB),
                'submission_criteria', COALESCE(v_item->'submission_criteria', '[]'::JSONB),
                'side_effects', COALESCE(v_item->'side_effects', '[]'::JSONB),
                'dispatch', v_item->'dispatch', 'dispatch_target', v_item->'dispatch_target',
                'control_points', COALESCE(v_item->'control_points', '[]'::JSONB)) THEN
                RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.action_key_conflict';
            END IF;
        ELSE
            INSERT INTO public.ont_action_types
                (id, org_id, object_type_id, stable_key, title, params_schema, edits,
                 submission_criteria, side_effects, dispatch, dispatch_target, control_points)
            VALUES
                (public.gen_random_uuid(), p_org_id, p_object_type_id, v_key,
                 pg_catalog.btrim(v_item->>'title'), COALESCE(v_item->'params_schema', '{}'::JSONB),
                 COALESCE(v_item->'edits', '[]'::JSONB), COALESCE(v_item->'submission_criteria', '[]'::JSONB),
                 COALESCE(v_item->'side_effects', '[]'::JSONB), v_item->>'dispatch',
                 NULLIF(v_item->>'dispatch_target', ''), COALESCE(v_item->'control_points', '[]'::JSONB));
        END IF;
    END LOOP;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(p_snapshot->'analytics', '[]'::JSONB)) LOOP
        v_key := pg_catalog.btrim(v_item->>'key');
        SELECT pg_catalog.jsonb_build_object('key', d.key, 'title', d.title, 'formula', d.formula, 'result_type', d.result_type)
          INTO v_existing
          FROM public.ont_analytics d
         WHERE d.org_id = p_org_id AND d.object_type_id = p_object_type_id AND d.key = v_key;
        IF FOUND THEN
            IF NOT p_allow_existing OR v_existing <> pg_catalog.jsonb_build_object(
                'key', v_key, 'title', pg_catalog.btrim(v_item->>'title'),
                'formula', COALESCE(v_item->'formula', '{}'::JSONB),
                'result_type', COALESCE(v_item->'result_type', '{}'::JSONB)) THEN
                RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'ontology_write.analytic_key_conflict';
            END IF;
        ELSE
            INSERT INTO public.ont_analytics
                (id, org_id, object_type_id, key, title, formula, result_type)
            VALUES
                (public.gen_random_uuid(), p_org_id, p_object_type_id, v_key,
                 pg_catalog.btrim(v_item->>'title'), COALESCE(v_item->'formula', '{}'::JSONB),
                 COALESCE(v_item->'result_type', '{}'::JSONB));
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION ontology_api.insert_children(p_org_id uuid, p_object_type_id uuid, p_snapshot jsonb, p_allow_existing boolean) OWNER TO console_ontology_writer;

--
-- Name: install_builtin_catalog(uuid, text, jsonb, uuid, text, text); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.install_builtin_catalog(p_org_id uuid, p_catalog_version text, p_manifest jsonb, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(installed boolean, object_type_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_digest BYTEA;
    v_allowed_digest BYTEA;
    v_snapshot JSONB;
    v_link JSONB;
    v_links JSONB;
    v_stable_key TEXT;
    v_target_key TEXT;
    v_target_id UUID;
    v_id UUID;
    v_count BIGINT;
    v_upgrade BOOLEAN;
    v_new_keys TEXT[] := ARRAY[]::TEXT[];
    v_retained_keys TEXT[] := ARRAY[]::TEXT[];
    v_existing_backing_kind TEXT;
    v_existing_backing_table TEXT;
    v_existing_primary_key TEXT;
    v_occurred_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    PERFORM ontology_api.assert_write_context(p_org_id, p_actor, p_trace_id, p_span_id);
    IF pg_catalog.jsonb_typeof(p_manifest) <> 'object'
       OR p_manifest->>'catalog_version' IS DISTINCT FROM p_catalog_version
       OR pg_catalog.jsonb_typeof(p_manifest->'object_types') <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_builtin.invalid_manifest_shape';
    END IF;

    v_digest := public.digest(pg_catalog.convert_to(p_manifest::TEXT, 'UTF8'), 'sha256');
    SELECT a.manifest_digest INTO v_allowed_digest
      FROM public.ont_builtin_catalog_allowlist a
     WHERE a.catalog_version = p_catalog_version;
    IF v_allowed_digest IS NULL OR v_allowed_digest <> v_digest THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_builtin.manifest_not_allowlisted';
    END IF;

    -- Share the org-scoped bootstrap/write lock with ordinary creation. The
    -- lock intentionally excludes catalog version so two versions cannot race
    -- one another or race a first custom type.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('ontology-bootstrap:' || p_org_id::TEXT, 0)
    );

    v_count := pg_catalog.jsonb_array_length(p_manifest->'object_types')::BIGINT;

    -- Exact re-application of a version this tenant already recorded is a
    -- database-owned no-op, which is what makes install idempotent under retry.
    IF EXISTS (
        SELECT 1 FROM public.ont_builtin_catalog_installs i
         WHERE i.org_id = p_org_id
           AND i.catalog_version = p_catalog_version
           AND i.manifest_digest = v_digest
    ) THEN
        RETURN QUERY SELECT FALSE, v_count;
        RETURN;
    END IF;

    v_upgrade := EXISTS (
        SELECT 1 FROM public.ont_builtin_catalog_installs i WHERE i.org_id = p_org_id
    );
    IF NOT v_upgrade AND EXISTS (
        SELECT 1 FROM public.ont_object_types o WHERE o.org_id = p_org_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ontology_builtin.empty_org_required';
    END IF;

    -- Pass 1 creates every key this tenant does not already hold, plus that
    -- key's non-link children. IDs are generated in the database, and every
    -- built-in starts published without exposing a general draft->published
    -- capability. Keys the tenant already holds are recorded as retained and
    -- otherwise untouched.
    FOR v_snapshot IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_manifest->'object_types')
    LOOP
        v_stable_key := pg_catalog.btrim(v_snapshot->>'stable_key');
        IF EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(COALESCE(v_snapshot->'links', '[]'::JSONB)) l
            WHERE l ? 'to_object_type_id' AND l->>'to_object_type_id' IS NOT NULL
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_builtin.physical_link_id_forbidden';
        END IF;

        SELECT o.backing_kind, o.backing_table, o.primary_key_property
          INTO v_existing_backing_kind, v_existing_backing_table, v_existing_primary_key
          FROM public.ont_object_types o
         WHERE o.org_id = p_org_id AND o.stable_key = v_stable_key
         ORDER BY o.schema_version DESC
         LIMIT 1;
        IF FOUND THEN
            IF v_existing_backing_kind IS DISTINCT FROM v_snapshot->>'backing_kind'
               OR v_existing_backing_table IS DISTINCT FROM NULLIF(v_snapshot->>'backing_table', '')
               OR v_existing_primary_key IS DISTINCT FROM NULLIF(v_snapshot->>'primary_key_property', '') THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'ontology_builtin.existing_key_projection_conflict';
            END IF;
            v_retained_keys := v_retained_keys || v_stable_key;
            CONTINUE;
        END IF;

        v_new_keys := v_new_keys || v_stable_key;
        v_id := public.gen_random_uuid();
        INSERT INTO public.ont_object_type_key_revisions (org_id, stable_key)
        VALUES (p_org_id, v_stable_key);
        INSERT INTO public.ont_object_types
            (id, org_id, stable_key, title, title_property_key, backing_kind,
             backing_table, primary_key_property, schema_version, lifecycle_state,
             created_by, created_at, updated_at)
        VALUES
            (v_id, p_org_id, v_stable_key, pg_catalog.btrim(v_snapshot->>'title'),
             NULLIF(v_snapshot->>'title_property_key', ''), v_snapshot->>'backing_kind',
             NULLIF(v_snapshot->>'backing_table', ''), NULLIF(v_snapshot->>'primary_key_property', ''),
             1, 'published', p_actor, v_occurred_at, v_occurred_at);
        PERFORM ontology_api.insert_children(
            p_org_id, v_id, pg_catalog.jsonb_set(v_snapshot, '{links}', '[]'::JSONB, TRUE), FALSE);
        PERFORM ontology_api.write_audit(
            p_org_id, p_actor, 'ontology.object_type.builtin_install', v_id, NULL,
            pg_catalog.jsonb_build_object('stable_key', v_stable_key,
                                          'schema_version', 1,
                                          'lifecycle_state', 'published',
                                          'catalog_version', p_catalog_version,
                                          'manifest_digest', pg_catalog.encode(v_digest, 'hex')),
            p_trace_id, p_span_id, v_occurred_at);
    END LOOP;

    -- Pass 2 resolves logical link targets for the newly installed types only,
    -- against this tenant's published heads — which may have arrived with an
    -- earlier catalog version — then enters the same private child validator.
    -- Types the tenant already held gain no links: retained means untouched.
    FOR v_snapshot IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_manifest->'object_types')
    LOOP
        v_stable_key := pg_catalog.btrim(v_snapshot->>'stable_key');
        IF NOT (v_stable_key = ANY (v_new_keys)) THEN
            CONTINUE;
        END IF;
        SELECT o.id INTO v_id
          FROM public.ont_object_types o
         WHERE o.org_id = p_org_id AND o.stable_key = v_stable_key AND o.schema_version = 1;
        v_links := '[]'::JSONB;
        FOR v_link IN
            SELECT value FROM pg_catalog.jsonb_array_elements(COALESCE(v_snapshot->'links', '[]'::JSONB))
        LOOP
            v_target_key := NULLIF(pg_catalog.btrim(v_link->>'to_stable_key'), '');
            v_target_id := NULL;
            IF v_target_key IS NOT NULL THEN
                SELECT o.id INTO v_target_id
                  FROM public.ont_object_types o
                 WHERE o.org_id = p_org_id
                   AND o.stable_key = v_target_key
                   AND o.lifecycle_state = 'published';
                IF v_target_id IS NULL THEN
                    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'ontology_builtin.link_target_not_found';
                END IF;
            END IF;
            v_links := v_links || pg_catalog.jsonb_build_array(
                (v_link - 'to_stable_key' - 'to_object_type_id')
                || pg_catalog.jsonb_build_object('to_object_type_id', v_target_id)
            );
        END LOOP;
        PERFORM ontology_api.insert_children(
            p_org_id, v_id, pg_catalog.jsonb_set(v_snapshot, '{links}', v_links, TRUE), TRUE);
    END LOOP;

    INSERT INTO public.ont_builtin_catalog_installs
        (org_id, catalog_version, manifest_digest, installed_by, installed_at)
    VALUES
        (p_org_id, p_catalog_version, v_digest, p_actor, v_occurred_at);

    -- The marker append is itself a governed state change — on an upgrade that
    -- adds no key it is the ONLY change — and the retained-key list is the
    -- record of what the installer deliberately did not touch. Neither action
    -- name is in the protected set enforced by
    -- ontology_api.protected_audit_writer_guard, and neither satisfies the
    -- per-mutation audit requirement: the per-type builtin_install rows above
    -- still do that on their own.
    INSERT INTO public.audit_events
        (id, actor, action, target_type, target_id, branch_id, before_snap, after_snap,
         trace_id, span_id, occurred_at, org_id)
    VALUES
        (public.gen_random_uuid(), p_actor,
         CASE WHEN v_upgrade THEN 'ontology.builtin_catalog.upgrade'
              ELSE 'ontology.builtin_catalog.install' END,
         'ont_builtin_catalog_installs', p_org_id::TEXT, NULL, NULL,
         pg_catalog.jsonb_build_object('catalog_version', p_catalog_version,
                                       'manifest_digest', pg_catalog.encode(v_digest, 'hex'),
                                       'installed_keys', pg_catalog.to_jsonb(v_new_keys),
                                       'retained_keys', pg_catalog.to_jsonb(v_retained_keys)),
         p_trace_id, p_span_id, v_occurred_at, p_org_id);

    RETURN QUERY SELECT TRUE, v_count;
END;
$$;


ALTER FUNCTION ontology_api.install_builtin_catalog(p_org_id uuid, p_catalog_version text, p_manifest jsonb, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: invoker_role(); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.invoker_role() RETURNS name
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT CASE
        WHEN pg_catalog.current_setting('role', true) IS NOT NULL
         AND pg_catalog.current_setting('role', true) <> 'none'
        THEN pg_catalog.current_setting('role', true)::NAME
        ELSE SESSION_USER::NAME
    END
$$;


ALTER FUNCTION ontology_api.invoker_role() OWNER TO console_ontology_writer;

--
-- Name: prepare_legacy_object_type_write(); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.prepare_legacy_object_type_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
BEGIN
    IF ontology_api.invoker_role() <> 'console_rt'::NAME THEN
        RETURN NEW;
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('ontology-bootstrap:' || NEW.org_id::TEXT, 0)
    );
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.ont_object_type_key_revisions (org_id, stable_key)
        VALUES (NEW.org_id, NEW.stable_key)
        ON CONFLICT (org_id, stable_key) DO NOTHING;
    ELSIF ROW(
        NEW.id, NEW.org_id, NEW.stable_key, NEW.title, NEW.title_property_key,
        NEW.backing_kind, NEW.backing_table, NEW.primary_key_property,
        NEW.schema_version, NEW.created_by, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.id, OLD.org_id, OLD.stable_key, OLD.title, OLD.title_property_key,
        OLD.backing_kind, OLD.backing_table, OLD.primary_key_property,
        OLD.schema_version, OLD.created_by, OLD.created_at
    ) OR NEW.lifecycle_state IS NOT DISTINCT FROM OLD.lifecycle_state
      OR NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'ontology_legacy.lifecycle_update_only';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION ontology_api.prepare_legacy_object_type_write() OWNER TO console_ontology_writer;

--
-- Name: protected_audit_writer_guard(); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.protected_audit_writer_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_invoker NAME := ontology_api.invoker_role();
    v_stable_key TEXT;
BEGIN
    IF NEW.action <> ALL (ARRAY[
        'ontology.object_type.create',
        'ontology.object_type.stage_revision',
        'ontology.object_type.transition',
        'ontology.object_type.builtin_install'
    ]::TEXT[]) THEN
        RETURN NEW;
    END IF;

    -- Direct command credentials cannot INSERT audit_events. When an approved
    -- command reaches this trigger it is nested inside the writer-owned
    -- SECURITY DEFINER routine, while the old compatibility path arrives as
    -- console_rt and must prove a matching parent mutation in this transaction.
    IF v_invoker = 'console_rt'::NAME THEN
        IF NEW.action = 'ontology.object_type.builtin_install'
           OR NEW.target_type <> 'ont_object_types'
           OR NOT EXISTS (
               SELECT 1
               FROM public.users u
               WHERE u.id = NEW.actor AND u.org_id = NEW.org_id AND u.is_active
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_audit.command_required';
        END IF;

        SELECT o.stable_key INTO v_stable_key
        FROM public.ont_object_types o
        WHERE o.org_id = NEW.org_id
          AND o.id::TEXT = NEW.target_id
          AND o.updated_at = NEW.occurred_at
          AND o.xmin = pg_catalog.pg_current_xact_id()::xid
          AND (
              (NEW.action = 'ontology.object_type.create' AND o.schema_version = 1 AND o.created_at = NEW.occurred_at)
              OR (NEW.action = 'ontology.object_type.stage_revision' AND o.schema_version > 1 AND o.created_at = NEW.occurred_at)
              OR NEW.action = 'ontology.object_type.transition'
          );
        IF v_stable_key IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_audit.command_required';
        END IF;
        IF NEW.action IN ('ontology.object_type.stage_revision', 'ontology.object_type.transition') THEN
            UPDATE public.ont_object_type_key_revisions k
               SET revision = k.revision + 1, updated_at = NEW.occurred_at
             WHERE k.org_id = NEW.org_id AND k.stable_key = v_stable_key;
            IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'ontology_legacy.key_revision_missing';
            END IF;
        END IF;
    ELSIF v_invoker <> 'console_ontology_cmd'::NAME THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'ontology_audit.command_required';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION ontology_api.protected_audit_writer_guard() OWNER TO console_ontology_writer;

--
-- Name: require_current_transaction_audit(); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.require_current_transaction_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_parent_id UUID;
    v_org_id UUID;
    v_stable_key TEXT;
    v_parent_is_current BOOLEAN;
BEGIN
    IF TG_TABLE_NAME = 'ont_object_types' THEN
        v_parent_id := NEW.id;
        v_org_id := NEW.org_id;
        v_stable_key := NEW.stable_key;
        v_parent_is_current := TRUE;
    ELSE
        v_parent_id := NEW.object_type_id;
        v_org_id := NEW.org_id;
        SELECT o.stable_key,
               o.xmin = pg_catalog.pg_current_xact_id()::xid
          INTO v_stable_key, v_parent_is_current
          FROM public.ont_object_types o
         WHERE o.id = v_parent_id AND o.org_id = v_org_id;
    END IF;

    IF COALESCE(v_parent_is_current, FALSE) AND TG_TABLE_NAME <> 'ont_object_types' THEN
        RETURN NEW;
    END IF;
    IF (
        SELECT COUNT(*) = 1
        FROM public.audit_events e
        LEFT JOIN public.ont_object_types target
          ON target.org_id = e.org_id AND target.id::TEXT = e.target_id
        WHERE e.org_id = v_org_id
          AND e.action = ANY (ARRAY[
              'ontology.object_type.create',
              'ontology.object_type.stage_revision',
              'ontology.object_type.transition',
              'ontology.object_type.builtin_install'
          ]::TEXT[])
          AND e.xmin = pg_catalog.pg_current_xact_id()::xid
          AND (
              e.target_id = v_parent_id::TEXT
              OR (e.action = 'ontology.object_type.transition' AND target.stable_key = v_stable_key)
          )
    ) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'ontology_write.exactly_one_current_transaction_audit_required';
END;
$$;


ALTER FUNCTION ontology_api.require_current_transaction_audit() OWNER TO console_ontology_writer;

--
-- Name: stage_object_type(uuid, text, uuid, bigint, jsonb, uuid, text, text); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.stage_object_type(p_org_id uuid, p_stable_key text, p_expected_validator uuid, p_expected_revision bigint, p_snapshot jsonb, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(object_type_id uuid, stable_key text, title text, backing_kind text, schema_version bigint, lifecycle_state text, key_write_validator_id uuid, key_write_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_id UUID;
    v_validator UUID;
    v_revision BIGINT;
    v_schema_version BIGINT;
    v_state TEXT;
    v_snapshot_key TEXT := pg_catalog.btrim(p_snapshot->>'stable_key');
    v_occurred_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    PERFORM ontology_api.assert_write_context(p_org_id, p_actor, p_trace_id, p_span_id);
    IF v_snapshot_key IS DISTINCT FROM p_stable_key THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ontology_write.stable_key_mismatch';
    END IF;

    SELECT k.validator_id, k.revision INTO v_validator, v_revision
      FROM public.ont_object_type_key_revisions k
     WHERE k.org_id = p_org_id AND k.stable_key = p_stable_key
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'ontology_write.key_not_found';
    END IF;
    IF v_validator <> p_expected_validator OR v_revision <> p_expected_revision THEN
        RETURN;
    END IF;

    SELECT o.id, o.schema_version, o.lifecycle_state
      INTO v_id, v_schema_version, v_state
      FROM public.ont_object_types o
     WHERE o.org_id = p_org_id AND o.stable_key = p_stable_key
       AND o.lifecycle_state IN ('draft', 'review_pending')
     FOR UPDATE;

    IF FOUND THEN
        IF v_state <> 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ontology_write.review_pending_immutable';
        END IF;
        UPDATE public.ont_object_types o
           SET title = pg_catalog.btrim(p_snapshot->>'title'),
               title_property_key = NULLIF(p_snapshot->>'title_property_key', ''),
               backing_kind = p_snapshot->>'backing_kind',
               backing_table = NULLIF(p_snapshot->>'backing_table', ''),
               primary_key_property = NULLIF(p_snapshot->>'primary_key_property', ''),
               updated_at = v_occurred_at
         WHERE o.id = v_id AND o.org_id = p_org_id AND o.lifecycle_state = 'draft';
        PERFORM ontology_api.insert_children(p_org_id, v_id, p_snapshot, TRUE);
    ELSE
        SELECT pg_catalog.max(o.schema_version) + 1 INTO v_schema_version
          FROM public.ont_object_types o
         WHERE o.org_id = p_org_id AND o.stable_key = p_stable_key;
        IF v_schema_version IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'ontology_write.key_not_found';
        END IF;
        v_id := public.gen_random_uuid();
        INSERT INTO public.ont_object_types
            (id, org_id, stable_key, title, title_property_key, backing_kind,
             backing_table, primary_key_property, schema_version, lifecycle_state,
             created_by, created_at, updated_at)
        VALUES
            (v_id, p_org_id, p_stable_key, pg_catalog.btrim(p_snapshot->>'title'),
             NULLIF(p_snapshot->>'title_property_key', ''), p_snapshot->>'backing_kind',
             NULLIF(p_snapshot->>'backing_table', ''), NULLIF(p_snapshot->>'primary_key_property', ''),
             v_schema_version, 'draft', p_actor, v_occurred_at, v_occurred_at);
        PERFORM ontology_api.insert_children(p_org_id, v_id, p_snapshot, FALSE);
    END IF;

    UPDATE public.ont_object_type_key_revisions k
       SET revision = k.revision + 1, updated_at = v_occurred_at
     WHERE k.org_id = p_org_id AND k.stable_key = p_stable_key
    RETURNING k.revision INTO v_revision;

    PERFORM ontology_api.write_audit(
        p_org_id, p_actor, 'ontology.object_type.stage_revision', v_id, NULL,
        pg_catalog.jsonb_build_object('stable_key', p_stable_key,
                                      'schema_version', v_schema_version,
                                      'lifecycle_state', 'draft'),
        p_trace_id, p_span_id, v_occurred_at);
    RETURN QUERY SELECT v_id, p_stable_key, pg_catalog.btrim(p_snapshot->>'title'),
                        p_snapshot->>'backing_kind', v_schema_version, 'draft'::TEXT,
                        v_validator, v_revision;
END;
$$;


ALTER FUNCTION ontology_api.stage_object_type(p_org_id uuid, p_stable_key text, p_expected_validator uuid, p_expected_revision bigint, p_snapshot jsonb, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: transition_object_type(uuid, uuid, uuid, bigint, text, uuid, text, text); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.transition_object_type(p_org_id uuid, p_object_type_id uuid, p_expected_validator uuid, p_expected_revision bigint, p_to_state text, p_actor uuid, p_trace_id text, p_span_id text) RETURNS TABLE(object_type_id uuid, stable_key text, title text, backing_kind text, schema_version bigint, lifecycle_state text, key_write_validator_id uuid, key_write_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
DECLARE
    v_stable_key TEXT;
    v_title TEXT;
    v_from_state TEXT;
    v_backing_kind TEXT;
    v_schema_version BIGINT;
    v_validator UUID;
    v_revision BIGINT;
    v_approval_id UUID;
    v_params JSONB;
    v_edits JSONB;
    v_occurred_at TIMESTAMPTZ := pg_catalog.statement_timestamp();
BEGIN
    PERFORM ontology_api.assert_write_context(p_org_id, p_actor, p_trace_id, p_span_id);

    SELECT o.stable_key, o.title, o.lifecycle_state, o.backing_kind, o.schema_version
      INTO v_stable_key, v_title, v_from_state, v_backing_kind, v_schema_version
      FROM public.ont_object_types o
     WHERE o.id = p_object_type_id AND o.org_id = p_org_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'ontology_write.object_type_not_found';
    END IF;

    SELECT k.validator_id, k.revision INTO v_validator, v_revision
      FROM public.ont_object_type_key_revisions k
     WHERE k.org_id = p_org_id AND k.stable_key = v_stable_key
     FOR UPDATE;
    IF v_validator <> p_expected_validator OR v_revision <> p_expected_revision THEN
        RETURN;
    END IF;

    PERFORM 1 FROM public.ont_object_types o
     WHERE o.id = p_object_type_id AND o.org_id = p_org_id
       AND o.lifecycle_state = v_from_state
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'ontology_write.lifecycle_changed';
    END IF;

    IF v_from_state = 'draft' AND p_to_state = 'published' THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ontology_write.review_required';
    ELSIF v_from_state = 'review_pending' AND p_to_state = 'published' THEN
        SELECT ga.id INTO v_approval_id
          FROM public.gov_approvals ga
          JOIN public.gov_approval_requests gr
            ON gr.org_id = ga.org_id AND gr.request_ref = ga.request_ref
           AND gr.kind = ga.kind AND gr.target_ref = ga.target_ref
           AND gr.requested_by = ga.requested_by
          LEFT JOIN public.gov_approval_consumptions gc
            ON gc.org_id = ga.org_id AND gc.approval_id = ga.id
         WHERE ga.org_id = p_org_id
           AND ga.kind = 'ontology.schema.publish'
           AND ga.target_ref = p_object_type_id
           AND ga.requested_by = p_actor
           AND ga.decision = 'approved'
           AND (gr.payload_summary->>'key_revision')::BIGINT = v_revision
           AND gc.id IS NULL
         ORDER BY ga.decided_at DESC, ga.id
         LIMIT 1
         FOR UPDATE OF ga;
        IF v_approval_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'ontology_write.publish_approval_required';
        END IF;
        INSERT INTO public.gov_approval_consumptions
            (id, org_id, approval_id, consumed_by, consumed_at)
        VALUES
            (public.gen_random_uuid(), p_org_id, v_approval_id, p_actor, v_occurred_at);
    ELSIF NOT (
        (v_from_state = 'draft' AND p_to_state = 'review_pending')
        OR (v_from_state = 'review_pending' AND p_to_state = 'draft')
        OR (v_from_state = 'published' AND p_to_state IN ('superseded', 'retired'))
        OR (v_from_state = 'superseded' AND p_to_state = 'retired')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ontology_write.illegal_lifecycle_transition';
    END IF;

    IF p_to_state = 'published' AND v_backing_kind = 'instance'
       AND NOT EXISTS (
           SELECT 1 FROM public.ont_action_types a
           WHERE a.org_id = p_org_id AND a.object_type_id = p_object_type_id
             AND a.dispatch = 'instance_revision'
       ) THEN
        SELECT COALESCE(pg_catalog.jsonb_object_agg(p.key, pg_catalog.jsonb_build_object('required', p.required)), '{}'::JSONB),
               COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('property', p.key, 'param', p.key) ORDER BY p.key), '[]'::JSONB)
          INTO v_params, v_edits
          FROM public.ont_property_defs p
         WHERE p.org_id = p_org_id AND p.object_type_id = p_object_type_id;
        INSERT INTO public.ont_action_types
            (id, org_id, object_type_id, stable_key, title, params_schema, edits,
             submission_criteria, side_effects, dispatch, dispatch_target, control_points)
        VALUES
            (public.gen_random_uuid(), p_org_id, p_object_type_id, 'create', '저장',
             v_params, v_edits, '[]'::JSONB, '[]'::JSONB, 'instance_revision', NULL,
             '["authority"]'::JSONB);
    END IF;

    IF p_to_state = 'published' THEN
        UPDATE public.ont_object_types o
           SET lifecycle_state = 'superseded', updated_at = v_occurred_at
         WHERE o.org_id = p_org_id AND o.stable_key = v_stable_key
           AND o.lifecycle_state = 'published' AND o.id <> p_object_type_id;
    END IF;
    UPDATE public.ont_object_types o
       SET lifecycle_state = p_to_state, updated_at = v_occurred_at
     WHERE o.id = p_object_type_id AND o.org_id = p_org_id
       AND o.lifecycle_state = v_from_state;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'ontology_write.lifecycle_changed';
    END IF;

    UPDATE public.ont_object_type_key_revisions k
       SET revision = k.revision + 1, updated_at = v_occurred_at
     WHERE k.org_id = p_org_id AND k.stable_key = v_stable_key
    RETURNING k.revision INTO v_revision;

    PERFORM ontology_api.write_audit(
        p_org_id, p_actor, 'ontology.object_type.transition', p_object_type_id,
        pg_catalog.jsonb_build_object('stable_key', v_stable_key,
                                      'schema_version', v_schema_version,
                                      'lifecycle_state', v_from_state),
        pg_catalog.jsonb_build_object('stable_key', v_stable_key,
                                      'schema_version', v_schema_version,
                                      'lifecycle_state', p_to_state),
        p_trace_id, p_span_id, v_occurred_at);
    RETURN QUERY SELECT p_object_type_id, v_stable_key, v_title, v_backing_kind,
                        v_schema_version, p_to_state, v_validator, v_revision;
END;
$$;


ALTER FUNCTION ontology_api.transition_object_type(p_org_id uuid, p_object_type_id uuid, p_expected_validator uuid, p_expected_revision bigint, p_to_state text, p_actor uuid, p_trace_id text, p_span_id text) OWNER TO console_ontology_writer;

--
-- Name: write_audit(uuid, uuid, text, uuid, jsonb, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: ontology_api; Owner: console_ontology_writer
--

CREATE FUNCTION ontology_api.write_audit(p_org_id uuid, p_actor uuid, p_action text, p_object_type_id uuid, p_before jsonb, p_after jsonb, p_trace_id text, p_span_id text, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET row_security TO 'on'
    AS $$
    INSERT INTO public.audit_events
        (id, actor, action, target_type, target_id, branch_id, before_snap, after_snap,
         trace_id, span_id, occurred_at, org_id)
    VALUES
        (public.gen_random_uuid(), p_actor, p_action, 'ont_object_types', p_object_type_id::TEXT,
         NULL, p_before, p_after, p_trace_id, p_span_id, p_occurred_at, p_org_id)
$$;


ALTER FUNCTION ontology_api.write_audit(p_org_id uuid, p_actor uuid, p_action text, p_object_type_id uuid, p_before jsonb, p_after jsonb, p_trace_id text, p_span_id text, p_occurred_at timestamp with time zone) OWNER TO console_ontology_writer;

--
-- Name: access_log_retention_floor_years(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.access_log_retention_floor_years() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
    SELECT CASE
        WHEN EXISTS (
            SELECT 1
            -- Schema-qualified: `personal_data_columns` lives in `public`, so
            -- ordering `pg_catalog` first does not protect this call the way
            -- it protects the built-ins. Naming the schema does.
            FROM public.personal_data_columns() AS pdc,
                 LATERAL unnest(pdc.tokens) AS token
            WHERE token = 'unique-id' OR token LIKE 'unique-id/%'
               OR token = 'sensitive' OR token LIKE 'sensitive/%'
        ) THEN 2
        ELSE 1
    END;
$$;


ALTER FUNCTION public.access_log_retention_floor_years() OWNER TO console_app;

--
-- Name: FUNCTION access_log_retention_floor_years(); Type: COMMENT; Schema: public; Owner: console_app
--

COMMENT ON FUNCTION public.access_log_retention_floor_years() IS '접속기록 보관 기간의 하한(원문 단위: 년). 「개인정보의 안전성 확보조치 기준」 개인정보보호위원회 고시 제2026-9호(발령ㆍ시행 2026-07-01, 행정규칙일련번호 2100000281400) 제8조제1항: 1년 이상, 다만 제2호의 고유식별정보 또는 민감정보를 처리하는 경우 2년 이상. 법문이 년 단위이므로 고정 일수로 환산하지 않는다. 분류가 부분적인 동안 이 값은 하한이며 과대 산출되지 않는다. 이 함수는 의무 이행 여부를 주장하지 않는다. HR/payroll 개인정보 스키마의 내부 안전성 검증용이며 제품 API가 아니다.';


--
-- Name: append_equipment_maintenance_history(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.append_equipment_maintenance_history(p_org_id uuid, p_equipment_id uuid, p_work_order_id uuid, p_completed_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_history_id UUID;
BEGIN
  IF p_org_id IS DISTINCT FROM NULLIF(current_setting('app.current_org', true), '')::uuid THEN
    RAISE EXCEPTION 'maintenance history org does not match runtime org' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO equipment_maintenance_history (org_id,equipment_id,work_order_id,completed_at)
  VALUES (p_org_id,p_equipment_id,p_work_order_id,p_completed_at) RETURNING id INTO v_history_id;
  INSERT INTO equipment_maintenance_history_evidence (history_id,org_id,evidence_media_id)
  SELECT v_history_id,p_org_id,e.id FROM evidence_media e
  WHERE e.org_id=p_org_id AND e.work_order_id=p_work_order_id
    AND e.stage IN ('AFTER','REPORT') AND e.worm_replica_status='VERIFIED';
  INSERT INTO equipment_maintenance_history_costs (history_id,org_id,equipment_cost_ledger_id)
  SELECT v_history_id,p_org_id,l.id FROM equipment_cost_ledger l
  WHERE l.org_id=p_org_id AND l.work_order_id=p_work_order_id AND l.equipment_id=p_equipment_id;
  RETURN v_history_id;
END; $$;


ALTER FUNCTION public.append_equipment_maintenance_history(p_org_id uuid, p_equipment_id uuid, p_work_order_id uuid, p_completed_at timestamp with time zone) OWNER TO console_app;

