--
-- Name: comms_account_by_address(text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.comms_account_by_address(p_address text) RETURNS TABLE(org_id uuid, account_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;
    RETURN QUERY
        SELECT a.org_id, a.id
        FROM email_accounts a
        WHERE a.status = 'ACTIVE'
          AND lower(a.email_address) = lower(btrim(p_address))
        ORDER BY a.org_id, a.id;
    SET LOCAL row_security = on;
END;
$$;


ALTER FUNCTION public.comms_account_by_address(p_address text) OWNER TO console_app;

