--

CREATE FUNCTION public.comms_due_email_accounts(p_now timestamp with time zone, p_limit integer) RETURNS TABLE(org_id uuid, account_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT d.org_id, d.account_id
    FROM comms_due_email_accounts(p_now, p_limit, 600) AS d;
$$;


ALTER FUNCTION public.comms_due_email_accounts(p_now timestamp with time zone, p_limit integer) OWNER TO console_app;

--
-- Name: comms_due_email_accounts(timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.comms_due_email_accounts(p_now timestamp with time zone, p_limit integer, p_lease_secs integer) RETURNS TABLE(org_id uuid, account_id uuid, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;
    RETURN QUERY
        WITH due AS (
            SELECT a.id
            FROM email_accounts a
            WHERE a.status = 'ACTIVE'
              AND (
                    a.last_sync_at IS NULL
                 OR a.last_sync_at <= p_now - make_interval(secs => a.sync_cadence_secs)
              )
              AND (a.claimed_until IS NULL OR a.claimed_until <= p_now)
            ORDER BY a.last_sync_at ASC NULLS FIRST
            LIMIT GREATEST(p_limit, 0)
            FOR UPDATE SKIP LOCKED
        )
        UPDATE email_accounts a
        SET claimed_until = p_now + make_interval(secs => GREATEST(p_lease_secs, 1)),
            -- Fresh fencing token per claimed row: the worker that receives this
            -- token is the ONLY one allowed to clear the lease it just took.
            claim_token = gen_random_uuid()
        FROM due
        WHERE a.id = due.id
        RETURNING a.org_id, a.id, a.claim_token;
    SET LOCAL row_security = on;
END;
$$;


ALTER FUNCTION public.comms_due_email_accounts(p_now timestamp with time zone, p_limit integer, p_lease_secs integer) OWNER TO console_app;

