--
-- Name: console_attendance_exception_eligibility_lock(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.console_attendance_exception_eligibility_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF (TG_OP = 'INSERT' AND NEW.kind = 'NO_SHOW' AND NEW.status = 'OPEN')
       OR (TG_OP = 'UPDATE' AND OLD.kind = 'NO_SHOW' AND OLD.status = 'OPEN'
           AND NEW.status = 'RESOLVED') THEN
        PERFORM public.console_employee_day_eligibility_lock(NEW.org_id, NEW.employee_id, NEW.work_date);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.console_attendance_exception_eligibility_lock() OWNER TO console_app;

--
-- Name: console_attendance_substitution_eligibility_guard(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.console_attendance_substitution_eligibility_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.worker_employee_id IS NULL
       OR NOT ((TG_OP = 'INSERT' AND NEW.status = 'ASSIGNED')
               OR (TG_OP = 'UPDATE' AND OLD.status = 'ASSIGNED' AND NEW.status = 'CANCELLED')) THEN
        RETURN NEW;
    END IF;

    PERFORM public.console_employee_day_eligibility_lock(
        NEW.org_id, NEW.worker_employee_id, NEW.cover_date
    );

    IF TG_OP = 'INSERT' AND (
        EXISTS (
            SELECT 1
              FROM public.attendance_substitutions s
             WHERE s.org_id = NEW.org_id
               AND s.worker_employee_id = NEW.worker_employee_id
               AND s.cover_date = NEW.cover_date
               AND s.status = 'ASSIGNED'
               AND s.from_minutes < NEW.to_minutes
               AND s.to_minutes > NEW.from_minutes
        )
        OR EXISTS (
            SELECT 1
              FROM public.leave_requests lr
             WHERE lr.org_id = NEW.org_id
               AND lr.subject_employee_id = NEW.worker_employee_id
               AND lr.status = 'approved'
               AND NEW.cover_date BETWEEN lr.start_date AND lr.end_date
        )
        OR EXISTS (
            SELECT 1
              FROM public.attendance_exceptions e
             WHERE e.org_id = NEW.org_id
               AND e.employee_id = NEW.worker_employee_id
               AND e.work_date = NEW.cover_date
               AND e.kind = 'NO_SHOW'
               AND e.status = 'OPEN'
        )
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            MESSAGE = 'attendance_substitutions_worker_eligibility_guard';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.console_attendance_substitution_eligibility_guard() OWNER TO console_app;

--
-- Name: console_employee_day_eligibility_lock(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.console_employee_day_eligibility_lock(p_org_id uuid, p_employee_id uuid, p_work_date date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'attendance-substitution-eligibility-v1|' || p_org_id::TEXT || '|' ||
            p_employee_id::TEXT || '|' || pg_catalog.to_char(p_work_date, 'YYYY-MM-DD'),
            0
        )
    );
END;
$$;


ALTER FUNCTION public.console_employee_day_eligibility_lock(p_org_id uuid, p_employee_id uuid, p_work_date date) OWNER TO console_app;

--
-- Name: console_employee_number_unique(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.console_employee_number_unique() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.source_filename = 'console' AND NEW.employee_number IS NOT NULL THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtext(NEW.org_id::TEXT || ':' || NEW.employee_number)
        );
        IF EXISTS (
            SELECT 1 FROM public.employees e
            WHERE e.org_id = NEW.org_id
              AND e.employee_number = NEW.employee_number
        ) THEN
            RAISE EXCEPTION 'employee number already exists in this organization'
                USING ERRCODE = '23505';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.console_employee_number_unique() OWNER TO console_app;

--
-- Name: console_leave_request_eligibility_lock(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.console_leave_request_eligibility_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_work_date DATE;
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status
       AND (OLD.status = 'approved' OR NEW.status = 'approved') THEN
        FOR v_work_date IN
            SELECT work_date::DATE
              FROM pg_catalog.generate_series(NEW.start_date, NEW.end_date, INTERVAL '1 day') AS work_date
             ORDER BY work_date
        LOOP
            PERFORM public.console_employee_day_eligibility_lock(
                NEW.org_id, NEW.subject_employee_id, v_work_date
            );
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.console_leave_request_eligibility_lock() OWNER TO console_app;

--
-- Name: consulting_reject_terminal_child_write(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.consulting_reject_terminal_child_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' AND EXISTS (
    SELECT 1 FROM consulting_engagements
    WHERE id=OLD.engagement_id AND org_id=OLD.org_id AND status IN ('SUSTAINED','CORRECTIVE')
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'terminal consulting engagement is immutable',
      CONSTRAINT = 'consulting_terminal_immutable';
  END IF;
  IF TG_OP <> 'DELETE' AND EXISTS (
    SELECT 1 FROM consulting_engagements
    WHERE id=NEW.engagement_id AND org_id=NEW.org_id AND status IN ('SUSTAINED','CORRECTIVE')
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'terminal consulting engagement is immutable',
      CONSTRAINT = 'consulting_terminal_immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.consulting_reject_terminal_child_write() OWNER TO console_app;

