-- Name: consulting_reject_terminal_engagement_write(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.consulting_reject_terminal_engagement_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IN ('SUSTAINED','CORRECTIVE') THEN
    RAISE EXCEPTION USING
