      MESSAGE = 'terminal consulting engagement is immutable',
      CONSTRAINT = 'consulting_terminal_immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


