--
-- Name: docs_evidence_copy_bind_storage_attestation(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.docs_evidence_copy_bind_storage_attestation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    attested_at TIMESTAMPTZ;
BEGIN
    IF NEW.source_evidence_media_id IS NOT NULL THEN
        SELECT media.verified_at
        INTO attested_at
        FROM evidence_media AS media
        WHERE media.id = NEW.source_evidence_media_id
          AND media.org_id = NEW.org_id
          AND media.worm_replica_status = 'VERIFIED'
          AND media.verified_at IS NOT NULL
          AND media.s3_key = NEW.storage_object_id
          AND media.checksum_sha256 = encode(decode(NEW.digest_sha256, 'hex'), 'base64');
    END IF;

    IF attested_at IS NOT NULL THEN
        NEW.worm_status := 'VERIFIED';
        NEW.verified_at := attested_at;
    ELSE
        NEW.worm_status := 'PENDING';
        NEW.verified_at := NULL;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.docs_evidence_copy_bind_storage_attestation() OWNER TO console_app;

--
-- Name: docs_evidence_copy_worm_guard(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.docs_evidence_copy_worm_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'EV copies are WORM append-only and cannot be deleted id=%', OLD.id;
    END IF;
    IF NEW.copy_kind IS DISTINCT FROM OLD.copy_kind
        OR NEW.derivative_kind IS DISTINCT FROM OLD.derivative_kind
        OR NEW.parent_copy_id IS DISTINCT FROM OLD.parent_copy_id
        OR NEW.storage_provider IS DISTINCT FROM OLD.storage_provider
        OR NEW.storage_object_id IS DISTINCT FROM OLD.storage_object_id
        OR NEW.storage_key_ref IS DISTINCT FROM OLD.storage_key_ref
        OR NEW.storage_version_id IS DISTINCT FROM OLD.storage_version_id
        OR NEW.source_evidence_media_id IS DISTINCT FROM OLD.source_evidence_media_id
        OR NEW.digest_sha256 IS DISTINCT FROM OLD.digest_sha256
        OR NEW.content_type IS DISTINCT FROM OLD.content_type
        OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes
        OR NEW.created_by IS DISTINCT FROM OLD.created_by
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'immutable EV copy fields cannot be changed for id=%', OLD.id;
    END IF;
    IF OLD.worm_status = 'VERIFIED' AND (
        NEW.worm_status IS DISTINCT FROM OLD.worm_status OR NEW.verified_at IS DISTINCT FROM OLD.verified_at
    ) THEN
        RAISE EXCEPTION 'verified EV WORM copy cannot be mutated id=%', OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.docs_evidence_copy_worm_guard() OWNER TO console_app;

--
-- Name: docs_evidence_legal_hold_release_guard(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.docs_evidence_legal_hold_release_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'EV legal holds cannot be deleted id=%', OLD.id;
    END IF;
    IF NEW.evidence_object_id IS DISTINCT FROM OLD.evidence_object_id
        OR NEW.case_ref IS DISTINCT FROM OLD.case_ref
        OR NEW.basis IS DISTINCT FROM OLD.basis
        OR NEW.reason IS DISTINCT FROM OLD.reason
        OR NEW.applied_by IS DISTINCT FROM OLD.applied_by
        OR NEW.applied_at IS DISTINCT FROM OLD.applied_at
        OR NEW.audit_event_id IS DISTINCT FROM OLD.audit_event_id THEN
        RAISE EXCEPTION 'immutable EV legal hold fields cannot be changed id=%', OLD.id;
    END IF;
    IF OLD.status = 'RELEASED' THEN
        RAISE EXCEPTION 'released EV legal hold cannot be mutated id=%', OLD.id;
    END IF;
    IF NEW.status <> 'RELEASED' THEN
        RAISE EXCEPTION 'EV legal hold updates may only release an active hold id=%', OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.docs_evidence_legal_hold_release_guard() OWNER TO console_app;

--
-- Name: docs_evidence_object_immutable_fields(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.docs_evidence_object_immutable_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.code IS DISTINCT FROM OLD.code
        OR NEW.source_type IS DISTINCT FROM OLD.source_type
        OR NEW.source_id IS DISTINCT FROM OLD.source_id
        OR NEW.source_code IS DISTINCT FROM OLD.source_code
        OR NEW.created_by IS DISTINCT FROM OLD.created_by
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'immutable EV object fields cannot be changed for id=%', OLD.id;
    END IF;
    IF OLD.legal_hold_state = 'ACTIVE' AND NEW.current_custody_stage = 'DISPOSED' THEN
        RAISE EXCEPTION 'active legal hold blocks EV object disposal for id=%', OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.docs_evidence_object_immutable_fields() OWNER TO console_app;

