--
-- Name: equipment_maintenance_history_evidence_require_verified_snapsho(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.equipment_maintenance_history_evidence_require_verified_snapsho() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM equipment_maintenance_history h
        JOIN evidence_media e
          ON e.id = NEW.evidence_media_id
         AND e.org_id = NEW.org_id
        WHERE h.id = NEW.history_id
          AND h.org_id = NEW.org_id
          AND e.work_order_id = h.work_order_id
          AND e.stage IN ('AFTER', 'REPORT')
          AND e.worm_replica_status = 'VERIFIED'
    ) THEN
        RAISE EXCEPTION
            'maintenance history evidence must be verified completion evidence for the recorded work order'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.equipment_maintenance_history_evidence_require_verified_snapsho() OWNER TO console_app;

--
-- Name: equipment_maintenance_history_require_final_completion(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.equipment_maintenance_history_require_final_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM work_orders w
        WHERE w.id = NEW.work_order_id
          AND w.org_id = NEW.org_id
          AND w.equipment_id = NEW.equipment_id
          AND w.status = 'FINAL_COMPLETED'
          AND w.result_type = 'COMPLETED'
          AND EXISTS (
              SELECT 1
              FROM evidence_media e
              WHERE e.work_order_id = w.id
                AND e.org_id = w.org_id
                AND e.stage IN ('AFTER', 'REPORT')
                AND e.worm_replica_status = 'VERIFIED'
          )
          AND NOT EXISTS (
              SELECT 1
              FROM evidence_media e
              WHERE e.work_order_id = w.id
                AND e.org_id = w.org_id
                AND e.stage IN ('AFTER', 'REPORT')
                AND e.worm_replica_status <> 'VERIFIED'
          )
    ) THEN
        RAISE EXCEPTION
            'maintenance history requires a FINAL_COMPLETED work order with a verified completion evidence set'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.equipment_maintenance_history_require_final_completion() OWNER TO console_app;

