-- Name: erasure_ledger_append_only(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.erasure_ledger_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Statement-level: there is no OLD row to name, and referencing one here
    -- would raise "record old is not assigned yet" instead of the refusal.
    IF TG_OP = 'TRUNCATE' THEN
        RAISE EXCEPTION 'erasure_ledger is append-only: TRUNCATE is forbidden';
    END IF;
    RAISE EXCEPTION
        'erasure_ledger is append-only: % is forbidden (org_id=%, seq=%)',
        TG_OP, OLD.org_id, OLD.seq;
END;
$$;


ALTER FUNCTION public.erasure_ledger_append_only() OWNER TO console_app;

--
-- Name: erasure_ledger_assign_chain(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.erasure_ledger_assign_chain() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_genesis CONSTANT BYTEA := decode(repeat('00', 32), 'hex');
BEGIN
    NEW.seq := COALESCE(
        (SELECT max(seq) FROM erasure_ledger WHERE org_id = NEW.org_id), 0) + 1;
    NEW.prev_entry_hash := COALESCE(
        (SELECT entry_hash FROM erasure_ledger
          WHERE org_id = NEW.org_id AND seq = NEW.seq - 1), v_genesis);
    NEW.entry_hash := erasure_ledger_entry_hash(
        NEW.org_id, NEW.seq, NEW.prev_entry_hash,
        NEW.subject_kind, NEW.subject_digest,
        NEW.erased_relation, NEW.erased_selector, NEW.erased_row_count,
        NEW.actor, NEW.authority, NEW.effective_at);
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.erasure_ledger_assign_chain() OWNER TO console_app;

--
-- Name: erasure_ledger_entry_hash(uuid, bigint, bytea, text, bytea, text, text, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.erasure_ledger_entry_hash(p_org_id uuid, p_seq bigint, p_prev_entry_hash bytea, p_subject_kind text, p_subject_digest bytea, p_erased_relation text, p_erased_selector text, p_erased_row_count bigint, p_actor text, p_authority text, p_effective_at timestamp with time zone) RETURNS bytea
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT digest(convert_to('console.erasure_ledger.v1' || (
        SELECT string_agg(octet_length(v)::text || ':' || v, '' ORDER BY ord)
          FROM unnest(ARRAY[
              p_org_id::text,
              p_seq::text,
              encode(p_prev_entry_hash, 'hex'),
              p_subject_kind,
              encode(p_subject_digest, 'hex'),
              p_erased_relation,
              p_erased_selector,
              p_erased_row_count::text,
              p_actor,
              p_authority,
              to_char(p_effective_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
          ]) WITH ORDINALITY AS t(v, ord)
    ), 'UTF8'), 'sha256');
$$;


ALTER FUNCTION public.erasure_ledger_entry_hash(p_org_id uuid, p_seq bigint, p_prev_entry_hash bytea, p_subject_kind text, p_subject_digest bytea, p_erased_relation text, p_erased_selector text, p_erased_row_count bigint, p_actor text, p_authority text, p_effective_at timestamp with time zone) OWNER TO console_app;

--
-- Name: erasure_ledger_subject_digest(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.erasure_ledger_subject_digest(p_org_id uuid, p_subject_kind text, p_subject_id uuid) RETURNS bytea
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT digest(convert_to('console.erasure_ledger.subject.v1' || (
        SELECT string_agg(octet_length(v)::text || ':' || v, '' ORDER BY ord)
          FROM unnest(ARRAY[
              p_org_id::text,
              p_subject_kind,
              p_subject_id::text
          ]) WITH ORDINALITY AS t(v, ord)
    ), 'UTF8'), 'sha256');
$$;


ALTER FUNCTION public.erasure_ledger_subject_digest(p_org_id uuid, p_subject_kind text, p_subject_id uuid) OWNER TO console_app;

--
-- Name: evidence_media_reject_terminal_completion(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.evidence_media_reject_terminal_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_status TEXT;
BEGIN
    IF NEW.stage NOT IN ('AFTER', 'REPORT') THEN
        RETURN NEW;
    END IF;

    SELECT status
    INTO parent_status
    FROM work_orders
    WHERE id = NEW.work_order_id;

    IF parent_status IN ('FINAL_COMPLETED', 'ARCHIVED', 'CANCELLED') THEN
        RAISE EXCEPTION
            'cannot attach % evidence to work order % in terminal status %',
            NEW.stage, NEW.work_order_id, parent_status
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.evidence_media_reject_terminal_completion() OWNER TO console_app;

