--
-- Name: group_member_org_ids(uuid, uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.group_member_org_ids(p_group uuid, p_actor uuid) RETURNS TABLE(org_id uuid, slug text, name text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    result_rows organizations[];
BEGIN
    SET LOCAL row_security = off;
    SELECT array_agg(o ORDER BY o.created_at ASC, o.id ASC)
    INTO result_rows
    FROM organizations o
        JOIN group_memberships m ON m.org_id = o.id
    WHERE m.group_id = p_group
      AND o.status = 'ACTIVE'
      AND o.id <> '00000000-0000-0000-0000-00000000face'::uuid
      AND EXISTS (
          SELECT 1
          FROM group_role_grants g
              JOIN users u ON u.id = g.user_id
          WHERE g.group_id = p_group
            AND g.user_id = p_actor
            AND u.is_active
      );
    SET LOCAL row_security = on;

    RETURN QUERY
        SELECT r.id, r.slug, r.name, r.status
        FROM unnest(COALESCE(result_rows, ARRAY[]::organizations[])) AS r;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.group_member_org_ids(p_group uuid, p_actor uuid) OWNER TO console_app;

