--
-- Name: location_pings_create_day_partition(date); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.location_pings_create_day_partition(partition_day date) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    partition_name TEXT := 'location_pings_' || to_char(partition_day, 'YYYYMMDD');
    start_at TIMESTAMPTZ := partition_day::timestamp AT TIME ZONE 'UTC';
    end_at   TIMESTAMPTZ := (partition_day + 1)::timestamp AT TIME ZONE 'UTC';
BEGIN
    -- CREATE TABLE IF NOT EXISTS is not race-free for concurrent first pings.
    -- Serialize per-day partition creation while keeping different days independent.
    PERFORM pg_advisory_xact_lock(hashtextextended(partition_name, 0));

    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF location_pings FOR VALUES FROM (%L) TO (%L)',
        partition_name,
        start_at,
        end_at
    );

    RETURN partition_name;
END;
$$;


ALTER FUNCTION public.location_pings_create_day_partition(partition_day date) OWNER TO console_app;

--
-- Name: location_pings_ensure_partition(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.location_pings_ensure_partition(recorded_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    partition_day DATE := (recorded_at AT TIME ZONE 'UTC')::date;
BEGIN
    RETURN location_pings_create_day_partition(partition_day);
END;
$$;


