--
-- Name: period_locks_unlock_only(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.period_locks_unlock_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.unlocked_at IS NOT NULL THEN
        RAISE EXCEPTION 'period lock % is already unlocked and immutable', OLD.id
            USING ERRCODE = '25006';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.org_id IS DISTINCT FROM OLD.org_id
        OR NEW.domain IS DISTINCT FROM OLD.domain
        OR NEW.period_start IS DISTINCT FROM OLD.period_start
        OR NEW.period_end IS DISTINCT FROM OLD.period_end
        OR NEW.reason IS DISTINCT FROM OLD.reason
        OR NEW.locked_by IS DISTINCT FROM OLD.locked_by
        OR NEW.locked_at IS DISTINCT FROM OLD.locked_at
        OR NEW.unlocked_at IS NULL
    THEN
        RAISE EXCEPTION 'period lock rows only permit the one-shot unlock update'
            USING ERRCODE = '25006';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.period_locks_unlock_only() OWNER TO console_app;

--
-- Name: personal_data_columns(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.personal_data_columns() RETURNS TABLE(schema_name text, rel_name text, col_name text, tokens text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
    SELECT
        n.nspname::TEXT,
        c.relname::TEXT,
        a.attname::TEXT,
        string_to_array(
            (regexp_match(d.description, '^pd:([^[:space:]]*)'))[1],
            ','
        )
    FROM pg_catalog.pg_class AS c
    JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
    JOIN pg_catalog.pg_attribute AS a ON a.attrelid = c.oid
    JOIN pg_catalog.pg_description AS d
      ON d.objoid = c.oid AND d.objsubid = a.attnum
    WHERE n.nspname <> 'pg_catalog'
      AND c.relpersistence <> 't'
      AND c.relkind IN ('r', 'p', 'm', 'f')
      AND a.attnum > 0
      AND NOT a.attisdropped
      AND d.description LIKE 'pd:%';
$$;


ALTER FUNCTION public.personal_data_columns() OWNER TO console_app;

--
-- Name: FUNCTION personal_data_columns(); Type: COMMENT; Schema: public; Owner: console_app
--

COMMENT ON FUNCTION public.personal_data_columns() IS 'Field-level personal-data classification, read from the database catalog. Each row is a schema-qualified column carrying a pd: marker and its token list. The reader covers the same non-pg_catalog, non-temporary r/p/m/f relation universe as the catalog completeness assertion. Records what a column holds; asserts nothing about whether any obligation is met.';


