--
-- Name: platform_assign_org_to_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_assign_org_to_group(p_group_id uuid, p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_group_status TEXT;
    v_org_id UUID;
BEGIN
    SET LOCAL row_security = off;

    SELECT status INTO v_group_status
    FROM groups
    WHERE id = p_group_id;
    IF v_group_status IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;
    IF v_group_status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'group % is not active', p_group_id
            USING ERRCODE = '23514';
    END IF;

    SELECT id INTO v_org_id
    FROM organizations
    WHERE id = p_org_id
      AND id <> '00000000-0000-0000-0000-00000000face'::uuid;
    IF v_org_id IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;

    INSERT INTO group_memberships (group_id, org_id)
    VALUES (p_group_id, p_org_id)
    ON CONFLICT (org_id) DO UPDATE
        SET group_id = EXCLUDED.group_id,
            created_at = now();

    UPDATE organizations
    SET group_id = p_group_id,
        updated_at = now()
    WHERE id = p_org_id;

    SET LOCAL row_security = on;
    RETURN p_org_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_assign_org_to_group(p_group_id uuid, p_org_id uuid) OWNER TO console_app;

--
-- Name: platform_attach_group_of_one(uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_attach_group_of_one(p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_row_security TEXT := current_setting('row_security');
    v_org organizations%ROWTYPE;
    v_group_id UUID;
BEGIN
    SET LOCAL row_security = off;

    SELECT * INTO v_org FROM organizations WHERE id = p_org_id;
    IF v_org.id IS NULL THEN
        PERFORM set_config('row_security', v_row_security, true);
        RAISE EXCEPTION 'organization % not found', p_org_id USING ERRCODE = '23503';
    END IF;

    v_group_id := platform_mint_group_row(p_org_id, v_org.name, v_org.status);

    UPDATE organizations
       SET group_id = v_group_id, updated_at = now()
     WHERE id = p_org_id;

    PERFORM platform_attach_membership(v_group_id, p_org_id);

    PERFORM set_config('row_security', v_row_security, true);
    RETURN v_group_id;
EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('row_security', v_row_security, true);
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_attach_group_of_one(p_org_id uuid) OWNER TO console_app;

--
-- Name: platform_attach_membership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_attach_membership(p_group_id uuid, p_org_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_row_security TEXT := current_setting('row_security');
BEGIN
    SET LOCAL row_security = off;
    INSERT INTO group_memberships (group_id, org_id)
    VALUES (p_group_id, p_org_id)
    ON CONFLICT (org_id) DO UPDATE
        SET group_id = EXCLUDED.group_id,
            created_at = CASE
                WHEN group_memberships.group_id = EXCLUDED.group_id
                THEN group_memberships.created_at
                ELSE now()
            END;
    PERFORM set_config('row_security', v_row_security, true);
EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('row_security', v_row_security, true);
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_attach_membership(p_group_id uuid, p_org_id uuid) OWNER TO console_app;

--
-- Name: platform_console_route_adoption(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_console_route_adoption() RETURNS TABLE(org_id uuid, release_cycle text, console_route_events bigint, legacy_route_events bigint, rum_error_events bigint, rum_perf_p95_ms bigint, last_event_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            t.org_id,
            t.release_cycle,
            COUNT(*) FILTER (
                WHERE t.event_kind = 'route_selection' AND t.route_surface = 'console'
            )::BIGINT AS console_route_events,
            COUNT(*) FILTER (
                WHERE t.event_kind = 'route_selection' AND t.route_surface = 'legacy'
            )::BIGINT AS legacy_route_events,
            COUNT(*) FILTER (WHERE t.event_kind = 'rum_error')::BIGINT AS rum_error_events,
            (percentile_disc(0.95) WITHIN GROUP (ORDER BY t.duration_ms) FILTER (
                WHERE t.duration_ms IS NOT NULL
                  AND t.event_kind IN ('route_selection', 'rum_perf')
            ))::BIGINT AS rum_perf_p95_ms,
            MAX(t.occurred_at) AS last_event_at
        FROM console_route_telemetry t
        GROUP BY t.org_id, t.release_cycle
        ORDER BY MAX(t.occurred_at) DESC, t.release_cycle DESC;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_console_route_adoption() OWNER TO console_app;

