-- Name: platform_create_group(text, text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_create_group(p_slug text, p_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    SET LOCAL row_security = off;

    INSERT INTO groups (slug, name)
    VALUES (btrim(p_slug), btrim(p_name))
    RETURNING id INTO v_id;

    SET LOCAL row_security = on;
    RETURN v_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


