CREATE FUNCTION public.platform_get_organization(p_id uuid) RETURNS TABLE(id uuid, slug text, name text, status text, created_at timestamp with time zone, updated_at timestamp with time zone, group_id uuid, group_slug text, group_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            o.id,
            o.slug,
