            o.status,
            o.created_at,
            o.updated_at,
            g.id AS group_id,
            g.slug AS group_slug,
            g.name AS group_name
        FROM organizations o
        LEFT JOIN groups g ON g.id = o.group_id
        WHERE o.id = p_id
          AND o.id <> '00000000-0000-0000-0000-00000000face'::uuid;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_get_organization(p_id uuid) OWNER TO console_app;

--
-- Name: platform_list_group_accounts(uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_list_group_accounts(p_group_id uuid) RETURNS TABLE(user_id uuid, display_name text, phone text, tenant_roles text[], is_active boolean, has_passkey boolean, account_status text, org_id uuid, org_slug text, org_name text, group_roles text[], created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            u.id AS user_id,
            u.display_name,
            u.phone,
            u.roles AS tenant_roles,
            u.is_active,
            EXISTS (
                SELECT 1
                FROM auth_webauthn_credentials c
                WHERE c.user_id = u.id
            ) AS has_passkey,
            CASE
                WHEN NOT u.is_active THEN 'DEACTIVATED'
                WHEN EXISTS (
                    SELECT 1
                    FROM auth_webauthn_credentials c
                    WHERE c.user_id = u.id
                ) THEN 'ACTIVE'
                ELSE 'PENDING_SETUP'
            END AS account_status,
            o.id AS org_id,
            o.slug AS org_slug,
            o.name AS org_name,
            array_agg(gr.group_role ORDER BY gr.group_role) AS group_roles,
            u.created_at
        FROM group_role_grants gr
        JOIN group_memberships gm
          ON gm.group_id = gr.group_id
        JOIN users u
          ON u.id = gr.user_id
         AND u.org_id = gm.org_id
        JOIN organizations o
          ON o.id = u.org_id
         AND o.id <> '00000000-0000-0000-0000-00000000face'::uuid
        WHERE gr.group_id = p_group_id
        GROUP BY
            u.id,
            u.display_name,
            u.phone,
            u.roles,
            u.is_active,
            o.id,
            o.slug,
            o.name,
            u.created_at
        ORDER BY o.name ASC, u.display_name ASC, u.id ASC;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_list_group_accounts(p_group_id uuid) OWNER TO console_app;

--
-- Name: platform_list_groups(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_list_groups() RETURNS TABLE(id uuid, slug text, name text, status text, created_at timestamp with time zone, updated_at timestamp with time zone, member_count bigint, members jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            g.id,
            g.slug,
            g.name,
            g.status,
            g.created_at,
            g.updated_at,
            COUNT(o.id)::BIGINT AS member_count,
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'id', o.id,
                        'slug', o.slug,
                        'name', o.name,
                        'status', o.status
                    )
                    ORDER BY o.created_at ASC, o.id ASC
                ) FILTER (WHERE o.id IS NOT NULL),
                '[]'::jsonb
            ) AS members
        FROM groups g
        LEFT JOIN organizations o
            ON o.group_id = g.id
           AND o.id <> '00000000-0000-0000-0000-00000000face'::uuid
        WHERE g.id IS DISTINCT FROM (
            SELECT o2.group_id
            FROM organizations o2
            WHERE o2.id = '00000000-0000-0000-0000-00000000face'::uuid
        )
        GROUP BY g.id
        ORDER BY g.created_at ASC, g.id ASC;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


