CREATE FUNCTION public.platform_list_organizations() RETURNS TABLE(id uuid, slug text, name text, status text, created_at timestamp with time zone, updated_at timestamp with time zone, group_id uuid, group_slug text, group_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            o.id,
            o.slug,
            o.name,
            o.status,
            o.created_at,
            o.updated_at,
            g.id AS group_id,
            g.slug AS group_slug,
            g.name AS group_name
        FROM organizations o
        LEFT JOIN groups g ON g.id = o.group_id
        -- The platform sentinel is not a tenant; never list it.
        WHERE o.id <> '00000000-0000-0000-0000-00000000face'::uuid
        ORDER BY o.created_at ASC, o.id ASC;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


