--
-- Name: platform_mint_group_row(uuid, text, text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_mint_group_row(p_org_id uuid, p_name text, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_row_security TEXT := current_setting('row_security');
    v_hex TEXT := replace(p_org_id::text, '-', '');
    v_slug TEXT;
    v_group_id UUID;
    v_status TEXT;
    v_i INT;
    v_sentinel UUID := '00000000-0000-0000-0000-00000000face';
BEGIN
    SET LOCAL row_security = off;

    v_status := CASE
        WHEN p_org_id = v_sentinel THEN 'ARCHIVED'
        ELSE CASE
            WHEN COALESCE(p_status, '') IN ('ACTIVE', 'SUSPENDED', 'ARCHIVED')
            THEN p_status
            ELSE 'ACTIVE'
        END
    END;

    -- i=1 → go-{32hex}; i=2..9 → g{i}-{32hex}. All 35 chars, CHECK-valid.
    FOR v_i IN 1..9 LOOP
        IF v_i = 1 THEN
            v_slug := 'go-' || v_hex;
        ELSE
            v_slug := 'g' || v_i::text || '-' || v_hex;
        END IF;

        SELECT g.id INTO v_group_id
        FROM groups g
        WHERE g.slug = v_slug
          AND NOT EXISTS (
              SELECT 1 FROM group_memberships m
              WHERE m.group_id = g.id AND m.org_id <> p_org_id
          );
        IF v_group_id IS NOT NULL THEN
            PERFORM set_config('row_security', v_row_security, true);
            RETURN v_group_id;
        END IF;

        INSERT INTO groups (slug, name, status)
        VALUES (v_slug, p_name, v_status)
        ON CONFLICT (slug) DO NOTHING
        RETURNING id INTO v_group_id;
        IF v_group_id IS NOT NULL THEN
            PERFORM set_config('row_security', v_row_security, true);
            RETURN v_group_id;
        END IF;

        -- Lost the INSERT (concurrent winner or foreign occupant).
        -- Reuse if the occupant is empty/self; else next suffix.
        SELECT g.id INTO v_group_id
        FROM groups g
        WHERE g.slug = v_slug
          AND NOT EXISTS (
              SELECT 1 FROM group_memberships m
              WHERE m.group_id = g.id AND m.org_id <> p_org_id
          );
        IF v_group_id IS NOT NULL THEN
            PERFORM set_config('row_security', v_row_security, true);
            RETURN v_group_id;
        END IF;
    END LOOP;

    PERFORM set_config('row_security', v_row_security, true);
    RAISE EXCEPTION 'unable to mint group-of-one slug for org %', p_org_id
        USING ERRCODE = '23505';
EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('row_security', v_row_security, true);
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_mint_group_row(p_org_id uuid, p_name text, p_status text) OWNER TO console_app;

--
-- Name: platform_mint_missing_group_of_one(uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_mint_missing_group_of_one(p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_row_security TEXT := current_setting('row_security');
    v_group_id UUID;
BEGIN
    SET LOCAL row_security = off;
    SELECT group_id INTO v_group_id FROM organizations WHERE id = p_org_id;
    IF v_group_id IS NOT NULL THEN
        PERFORM set_config('row_security', v_row_security, true);
        RETURN v_group_id;
    END IF;
    v_group_id := platform_attach_group_of_one(p_org_id);
    PERFORM set_config('row_security', v_row_security, true);
    RETURN v_group_id;
EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('row_security', v_row_security, true);
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_mint_missing_group_of_one(p_org_id uuid) OWNER TO console_app;

--
-- Name: platform_org_health(); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_org_health() RETURNS TABLE(id uuid, slug text, name text, status text, group_id uuid, group_slug text, group_name text, user_count bigint, active_user_count bigint, active_work_orders bigint, open_work_orders bigint, last_activity_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    SET LOCAL row_security = off;

    RETURN QUERY
        SELECT
            o.id,
            o.slug,
            o.name,
            o.status,
            g.id AS group_id,
            g.slug AS group_slug,
            g.name AS group_name,
            COALESCE(u.total, 0)        AS user_count,
            COALESCE(u.active, 0)       AS active_user_count,
            COALESCE(w.active, 0)       AS active_work_orders,
            COALESCE(w.open_total, 0)   AS open_work_orders,
            GREATEST(u.last_user_at, w.last_wo_at, a.last_audit_at) AS last_activity_at
        FROM organizations o
        LEFT JOIN groups g ON g.id = o.group_id
        LEFT JOIN (
            SELECT
                users.org_id                             AS org_id,
                COUNT(*)                                 AS total,
                COUNT(*) FILTER (WHERE users.is_active)  AS active,
                MAX(users.created_at)                    AS last_user_at
            FROM users
            GROUP BY users.org_id
        ) u ON u.org_id = o.id
        LEFT JOIN (
            SELECT
                work_orders.org_id AS org_id,
                COUNT(*) FILTER (
                    WHERE work_orders.status IN (
                        'IN_PROGRESS', 'REPORT_SUBMITTED', 'ADMIN_REVIEW', 'ASSIGNED'
                    )
                ) AS active,
                COUNT(*) FILTER (
                    WHERE work_orders.status NOT IN (
                        'FINAL_COMPLETED', 'REJECTED', 'ARCHIVED', 'CANCELLED'
                    )
                ) AS open_total,
                MAX(work_orders.updated_at) AS last_wo_at
            FROM work_orders
            GROUP BY work_orders.org_id
        ) w ON w.org_id = o.id
        LEFT JOIN (
            SELECT
                audit_events.org_id AS org_id,
                MAX(audit_events.occurred_at) AS last_audit_at
            FROM audit_events
            WHERE audit_events.org_id IS NOT NULL
            GROUP BY audit_events.org_id
        ) a ON a.org_id = o.id
        -- The platform sentinel is not a tenant; never report on it.
        WHERE o.id <> '00000000-0000-0000-0000-00000000face'::uuid
        ORDER BY o.created_at ASC, o.id ASC;

    SET LOCAL row_security = on;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_org_health() OWNER TO console_app;

--
-- Name: platform_remove_org_from_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_remove_org_from_group(p_group_id uuid, p_org_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_org_id UUID;
    v_deleted INT;
BEGIN
    SET LOCAL row_security = off;

    SELECT id INTO v_org_id
    FROM organizations
    WHERE id = p_org_id
      AND id <> '00000000-0000-0000-0000-00000000face'::uuid;
    IF v_org_id IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;

    DELETE FROM group_memberships
    WHERE group_id = p_group_id
      AND org_id = p_org_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    IF v_deleted = 0 THEN
        SET LOCAL row_security = on;
        RETURN p_org_id;
    END IF;

    PERFORM platform_attach_group_of_one(p_org_id);

    SET LOCAL row_security = on;
    RETURN p_org_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_remove_org_from_group(p_group_id uuid, p_org_id uuid) OWNER TO console_app;

--
-- Name: platform_remove_organization(uuid); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_remove_organization(p_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    sentinel_org CONSTANT UUID := '00000000-0000-0000-0000-00000000face'::uuid;
    org_exists   BOOLEAN;
    has_data     BOOLEAN;
BEGIN
    IF p_id = sentinel_org THEN
        RETURN 'not_found';
    END IF;

    SET LOCAL row_security = off;

    SELECT EXISTS (SELECT 1 FROM organizations WHERE id = p_id) INTO org_exists;
    IF NOT org_exists THEN
        SET LOCAL row_security = on;
        RETURN 'not_found';
    END IF;

    SELECT
        EXISTS (SELECT 1 FROM registry_equipment           WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM work_orders                   WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM registry_sites               WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM registry_customers           WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM inspection_rounds            WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM regular_inspection_schedules WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM sales_listings               WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM customer_inquiries           WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM financial_rental_quotes      WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM financial_purchase_requests  WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM financial_purchase_attachments WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM financial_regular_purchase_prices WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM financial_expense_ledger      WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM equipment_cost_ledger        WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM messenger_threads            WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM location_consents            WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM site_attendance_events       WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM governance_findings          WHERE org_id = p_id)
     OR EXISTS (SELECT 1 FROM registered_devices rd
                JOIN users u ON u.id = rd.user_id WHERE u.org_id = p_id)
    INTO has_data;

    IF has_data THEN
        SET LOCAL row_security = on;
        RETURN 'blocked_has_data';
    END IF;

    DELETE FROM auth_refresh_tokens         WHERE org_id = p_id;
    DELETE FROM auth_refresh_token_families WHERE org_id = p_id;
    DELETE FROM auth_webauthn_credentials   WHERE org_id = p_id;
    DELETE FROM auth_webauthn_ceremonies
        WHERE user_id IN (SELECT id FROM users WHERE org_id = p_id);
    DELETE FROM auth_bootstrap_credentials  WHERE org_id = p_id;

    DELETE FROM user_branches WHERE org_id = p_id;

    PERFORM set_config('app.audit_rehome', 'on', true);
    UPDATE audit_events
    SET org_id    = sentinel_org,
        actor     = NULL,
        branch_id = NULL
    WHERE org_id = p_id;
    PERFORM set_config('app.audit_rehome', 'off', true);

    DELETE FROM users    WHERE org_id = p_id;
    DELETE FROM branches WHERE org_id = p_id;
    DELETE FROM regions  WHERE org_id = p_id;

    DELETE FROM organizations WHERE id = p_id;

    SET LOCAL row_security = on;
    RETURN 'removed';
END;
$$;


ALTER FUNCTION public.platform_remove_organization(p_id uuid) OWNER TO console_app;

