--
-- Name: platform_revoke_group_role(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_revoke_group_role(p_group_id uuid, p_user_id uuid, p_group_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_org UUID;
    v_deleted UUID;
BEGIN
    SET LOCAL row_security = off;

    SELECT u.org_id INTO v_user_org
    FROM users u
    JOIN group_memberships gm
      ON gm.org_id = u.org_id
     AND gm.group_id = p_group_id
    WHERE u.id = p_user_id;
    IF v_user_org IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;

    DELETE FROM group_role_grants
    WHERE group_id = p_group_id
      AND user_id = p_user_id
      AND group_role = p_group_role
    RETURNING user_id INTO v_deleted;

    SET LOCAL row_security = on;
    RETURN v_deleted;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


ALTER FUNCTION public.platform_revoke_group_role(p_group_id uuid, p_user_id uuid, p_group_role text) OWNER TO console_app;

--
-- Name: platform_set_organization_status(uuid, text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_set_organization_status(p_id uuid, p_status text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    updated_id UUID;
BEGIN
    IF p_status NOT IN ('ACTIVE', 'SUSPENDED', 'ARCHIVED') THEN
        RAISE EXCEPTION 'invalid tenant status %', p_status;
    END IF;
    SET LOCAL row_security = off;
    UPDATE organizations
    SET status = p_status, updated_at = now()
    WHERE id = p_id
    RETURNING id INTO updated_id;
    SET LOCAL row_security = on;
    RETURN updated_id;  -- NULL when no such org
END;
$$;


