-- Name: platform_update_group(uuid, text, text); Type: FUNCTION; Schema: public; Owner: console_app
--

CREATE FUNCTION public.platform_update_group(p_id uuid, p_name text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    SET LOCAL row_security = off;

    UPDATE groups
    SET
        name = COALESCE(NULLIF(btrim(p_name), ''), name),
        status = COALESCE(p_status, status),
        updated_at = now()
    WHERE id = p_id
    RETURNING id INTO v_id;

    SET LOCAL row_security = on;
    RETURN v_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$$;


