    employee_id uuid NOT NULL,
    leave_year integer NOT NULL,
    leave_accrued numeric(10,2),
    leave_used numeric(10,2),
    leave_remaining numeric(10,2),
    status text NOT NULL,
    statutory_basis jsonb DEFAULT '{}'::jsonb NOT NULL,
    notification_plan jsonb DEFAULT '{}'::jsonb NOT NULL,
