    CONSTRAINT annual_leave_obligations_leave_year_check CHECK (((leave_year >= 2000) AND (leave_year <= 2100))),
    CONSTRAINT annual_leave_obligations_status_check CHECK ((status = ANY (ARRAY['NEEDS_HR_REVIEW'::text, 'USAGE_PROMOTION_DRAFT_REQUIRED'::text, 'PROMOTION_SENT'::text, 'PAYOUT_REVIEW_REQUIRED'::text, 'CLOSED'::text])))
