--
-- Name: attendance_exception_resolutions; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.attendance_exception_resolutions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    exception_id uuid NOT NULL,
    action text NOT NULL,
    reason text NOT NULL,
    linked_work_ref text,
    ot_hours numeric(5,2),
    actor_user_id uuid NOT NULL,
    resolved_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_exception_resolutions_action_check CHECK ((action = ANY (ARRAY['CONFIRM'::text, 'APPROVE_OVERTIME'::text]))),
    CONSTRAINT attendance_exception_resolutions_check CHECK (((action <> 'APPROVE_OVERTIME'::text) OR (linked_work_ref IS NOT NULL))),
    CONSTRAINT attendance_exception_resolutions_linked_work_ref_check CHECK (((linked_work_ref IS NULL) OR (btrim(linked_work_ref) <> ''::text))),
    CONSTRAINT attendance_exception_resolutions_ot_hours_check CHECK (((ot_hours IS NULL) OR (ot_hours > (0)::numeric))),
    CONSTRAINT attendance_exception_resolutions_reason_check CHECK ((btrim(reason) <> ''::text))
);

ALTER TABLE ONLY public.attendance_exception_resolutions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.attendance_exception_resolutions OWNER TO console_app;

--
-- Name: attendance_exceptions; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.attendance_exceptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    employee_id uuid NOT NULL,
    branch_id uuid,
    work_date date NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    detail text NOT NULL,
    evidence jsonb DEFAULT '[]'::jsonb NOT NULL,
    links jsonb DEFAULT '[]'::jsonb NOT NULL,
    idempotency_key text NOT NULL,
    request_fingerprint text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_exceptions_code_check CHECK (((char_length(btrim(code)) >= 1) AND (char_length(btrim(code)) <= 64))),
    CONSTRAINT attendance_exceptions_detail_check CHECK ((btrim(detail) <> ''::text)),
    CONSTRAINT attendance_exceptions_evidence_check CHECK ((jsonb_typeof(evidence) = 'array'::text)),
    CONSTRAINT attendance_exceptions_idempotency_key_check CHECK (((char_length(btrim(idempotency_key)) >= 16) AND (char_length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT attendance_exceptions_kind_check CHECK ((kind = ANY (ARRAY['LATE'::text, 'NO_SHOW'::text, 'UNAPPROVED_OVERTIME'::text, 'EARLY_LEAVE'::text]))),
    CONSTRAINT attendance_exceptions_links_check CHECK ((jsonb_typeof(links) = 'array'::text)),
    CONSTRAINT attendance_exceptions_request_fingerprint_check CHECK ((request_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT attendance_exceptions_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'RESOLVED'::text])))
);

ALTER TABLE ONLY public.attendance_exceptions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.attendance_exceptions OWNER TO console_app;

--
-- Name: attendance_month_closes; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.attendance_month_closes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    month date NOT NULL,
    branch_id uuid,
    checks jsonb NOT NULL,
    attested_by uuid NOT NULL,
    attested_at timestamp with time zone DEFAULT now() NOT NULL,
    period_lock_id uuid,
    closed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_month_closes_check CHECK ((((branch_id IS NULL) AND (period_lock_id IS NOT NULL)) OR ((branch_id IS NOT NULL) AND (period_lock_id IS NULL)))),
    CONSTRAINT attendance_month_closes_checks_check CHECK ((jsonb_typeof(checks) = 'object'::text)),
    CONSTRAINT attendance_month_closes_month_check CHECK (((date_trunc('month'::text, (month)::timestamp with time zone))::date = month))
);

ALTER TABLE ONLY public.attendance_month_closes FORCE ROW LEVEL SECURITY;


ALTER TABLE public.attendance_month_closes OWNER TO console_app;

--
-- Name: attendance_substitutions; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.attendance_substitutions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    site text NOT NULL,
    branch_id uuid,
    role text NOT NULL,
    cover_date date NOT NULL,
    from_minutes integer NOT NULL,
    to_minutes integer NOT NULL,
    covered_employee_id uuid NOT NULL,
    reason_kind text NOT NULL,
    reason_detail text,
    worker_employee_id uuid,
    worker_name text NOT NULL,
    worker_type text NOT NULL,
    worker_rate text,
    status text DEFAULT 'ASSIGNED'::text NOT NULL,
    cancel_reason text,
    approval_ref text,
    contract_ref text,
    exception_id uuid,
    idempotency_key text NOT NULL,
    request_fingerprint text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_substitutions_approval_ref_check CHECK (((approval_ref IS NULL) OR (btrim(approval_ref) <> ''::text))),
    CONSTRAINT attendance_substitutions_check CHECK ((((to_minutes >= 1) AND (to_minutes <= 1440)) AND (to_minutes > from_minutes))),
    CONSTRAINT attendance_substitutions_check1 CHECK (((status <> 'CANCELLED'::text) OR (btrim(COALESCE(cancel_reason, ''::text)) <> ''::text))),
    CONSTRAINT attendance_substitutions_contract_ref_check CHECK (((contract_ref IS NULL) OR (btrim(contract_ref) <> ''::text))),
    CONSTRAINT attendance_substitutions_from_minutes_check CHECK (((from_minutes >= 0) AND (from_minutes <= 1439))),
    CONSTRAINT attendance_substitutions_idempotency_key_check CHECK (((char_length(btrim(idempotency_key)) >= 16) AND (char_length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT attendance_substitutions_reason_detail_check CHECK (((reason_detail IS NULL) OR (btrim(reason_detail) <> ''::text))),
    CONSTRAINT attendance_substitutions_reason_kind_check CHECK ((reason_kind = ANY (ARRAY['NO_SHOW'::text, 'APPROVED_LEAVE'::text, 'HALF_DAY'::text, 'LONG_TERM'::text, 'OTHER'::text]))),
    CONSTRAINT attendance_substitutions_request_fingerprint_check CHECK ((request_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT attendance_substitutions_role_check CHECK ((btrim(role) <> ''::text)),
    CONSTRAINT attendance_substitutions_site_check CHECK ((btrim(site) <> ''::text)),
    CONSTRAINT attendance_substitutions_status_check CHECK ((status = ANY (ARRAY['ASSIGNED'::text, 'CANCELLED'::text]))),
    CONSTRAINT attendance_substitutions_worker_name_check CHECK ((btrim(worker_name) <> ''::text)),
    CONSTRAINT attendance_substitutions_worker_rate_check CHECK (((worker_rate IS NULL) OR (btrim(worker_rate) <> ''::text))),
    CONSTRAINT attendance_substitutions_worker_type_check CHECK ((btrim(worker_type) <> ''::text))
);

ALTER TABLE ONLY public.attendance_substitutions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.attendance_substitutions OWNER TO console_app;

