    CONSTRAINT benefit_catalog_items_name_check CHECK (((btrim(name) <> ''::text) AND (char_length(name) <= 120))),
    CONSTRAINT benefit_catalog_items_note_check CHECK (((note IS NULL) OR (char_length(note) <= 500))),
