    CONSTRAINT benefit_catalog_items_scope_type_check CHECK ((scope_type = ANY (ARRAY['ORG'::text, 'BRANCH'::text, 'SITE'::text, 'TEAM'::text, 'ROLE'::text, 'EMPLOYEE_SEGMENT'::text])))
);

