--

CREATE TABLE public.compliance_obligations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    obligation_type text NOT NULL,
    scope_type text NOT NULL,
    scope_ref uuid,
    branch_id uuid,
    site_id uuid,
    owner_user_id uuid,
    severity text NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    effective_from date,
    effective_to date,
    review_cadence text,
    next_review_on date,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT compliance_obligations_check CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT compliance_obligations_check1 CHECK ((((scope_type = 'ORG'::text) AND (scope_ref IS NULL) AND (branch_id IS NULL) AND (site_id IS NULL)) OR ((scope_type = 'BRANCH'::text) AND (branch_id IS NOT NULL) AND (scope_ref = branch_id) AND (site_id IS NULL)) OR ((scope_type = 'SITE'::text) AND (site_id IS NOT NULL) AND (branch_id IS NOT NULL) AND (scope_ref = site_id)) OR ((scope_type = ANY (ARRAY['TEAM'::text, 'ROLE'::text])) AND (scope_ref IS NOT NULL)))),
    CONSTRAINT compliance_obligations_code_check CHECK ((code ~ '^CP-[0-9]{4,}$'::text)),
    CONSTRAINT compliance_obligations_description_check CHECK (((btrim(description) <> ''::text) AND (char_length(description) <= 4000))),
    CONSTRAINT compliance_obligations_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT compliance_obligations_obligation_type_check CHECK ((obligation_type = ANY (ARRAY['LEGAL'::text, 'REGULATORY'::text, 'CONTRACTUAL'::text, 'INTERNAL_POLICY'::text, 'CONTROL_REQUIREMENT'::text]))),
    CONSTRAINT compliance_obligations_review_cadence_check CHECK (((review_cadence IS NULL) OR (review_cadence = ANY (ARRAY['MONTHLY'::text, 'QUARTERLY'::text, 'SEMI_ANNUAL'::text, 'ANNUAL'::text, 'EVENT_DRIVEN'::text])))),
    CONSTRAINT compliance_obligations_scope_type_check CHECK ((scope_type = ANY (ARRAY['ORG'::text, 'BRANCH'::text, 'SITE'::text, 'TEAM'::text, 'ROLE'::text]))),
    CONSTRAINT compliance_obligations_severity_check CHECK ((severity = ANY (ARRAY['INFO'::text, 'LOW'::text, 'MEDIUM'::text, 'HIGH'::text, 'CRITICAL'::text]))),
    CONSTRAINT compliance_obligations_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'WAIVED'::text, 'SUPERSEDED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT compliance_obligations_title_check CHECK (((btrim(title) <> ''::text) AND (char_length(title) <= 200)))
);

ALTER TABLE ONLY public.compliance_obligations FORCE ROW LEVEL SECURITY;


ALTER TABLE public.compliance_obligations OWNER TO console_app;

--
-- Name: compliance_regulation_impacts; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.compliance_regulation_impacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    title text NOT NULL,
    jurisdiction text NOT NULL,
    regulator text,
    citation text NOT NULL,
    source_url text,
    impact_area text NOT NULL,
    impact_summary text NOT NULL,
    risk_level text NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    effective_from date,
    effective_to date,
    review_due_on date,
    owner_user_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT compliance_regulation_impacts_check CHECK (((effective_to IS NULL) OR (effective_from IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT compliance_regulation_impacts_citation_check CHECK (((btrim(citation) <> ''::text) AND (char_length(citation) <= 300))),
    CONSTRAINT compliance_regulation_impacts_code_check CHECK ((code ~ '^RG-[0-9]{4,}$'::text)),
    CONSTRAINT compliance_regulation_impacts_impact_area_check CHECK (((btrim(impact_area) <> ''::text) AND (char_length(impact_area) <= 80))),
    CONSTRAINT compliance_regulation_impacts_impact_summary_check CHECK (((btrim(impact_summary) <> ''::text) AND (char_length(impact_summary) <= 4000))),
    CONSTRAINT compliance_regulation_impacts_jurisdiction_check CHECK (((btrim(jurisdiction) <> ''::text) AND (char_length(jurisdiction) <= 80))),
    CONSTRAINT compliance_regulation_impacts_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT compliance_regulation_impacts_regulator_check CHECK (((regulator IS NULL) OR ((btrim(regulator) <> ''::text) AND (char_length(regulator) <= 160)))),
    CONSTRAINT compliance_regulation_impacts_risk_level_check CHECK ((risk_level = ANY (ARRAY['INFO'::text, 'LOW'::text, 'MEDIUM'::text, 'HIGH'::text, 'CRITICAL'::text]))),
    CONSTRAINT compliance_regulation_impacts_source_url_check CHECK (((source_url IS NULL) OR ((btrim(source_url) <> ''::text) AND (char_length(source_url) <= 500)))),
    CONSTRAINT compliance_regulation_impacts_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'SUPERSEDED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT compliance_regulation_impacts_title_check CHECK (((btrim(title) <> ''::text) AND (char_length(title) <= 200)))
);

ALTER TABLE ONLY public.compliance_regulation_impacts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.compliance_regulation_impacts OWNER TO console_app;

