    CONSTRAINT console_route_telemetry_event_kind_check CHECK ((event_kind = ANY (ARRAY['route_selection'::text, 'rum_error'::text, 'rum_perf'::text]))),
    CONSTRAINT console_route_telemetry_release_cycle_check CHECK ((((char_length(release_cycle) >= 1) AND (char_length(release_cycle) <= 80)) AND (release_cycle ~ '^[A-Za-z0-9._:-]+$'::text))),
    CONSTRAINT console_route_telemetry_route_path_check CHECK ((((char_length(route_path) >= 1) AND (char_length(route_path) <= 120)) AND (route_path ~ '^/[A-Za-z0-9._:/-]*$'::text))),
    CONSTRAINT console_route_telemetry_route_surface_check CHECK ((route_surface = ANY (ARRAY['console'::text, 'legacy'::text])))
);

