--
-- Name: docs_evidence_copies; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.docs_evidence_copies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    evidence_object_id uuid NOT NULL,
    copy_kind text NOT NULL,
    derivative_kind text,
    parent_copy_id uuid,
    storage_provider text NOT NULL,
    storage_object_id text NOT NULL,
    storage_key_ref text,
    storage_version_id text,
    source_evidence_media_id uuid,
    digest_sha256 text NOT NULL,
    content_type text NOT NULL,
    size_bytes bigint NOT NULL,
    worm_status text DEFAULT 'PENDING'::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    verified_at timestamp with time zone,
    evidentiary_status text GENERATED ALWAYS AS (
CASE
    WHEN (copy_kind = 'DERIVATIVE'::text) THEN 'NON_EVIDENTIARY_DERIVATIVE'::text
    WHEN (worm_status = 'VERIFIED'::text) THEN 'VERIFIED_ORIGINAL'::text
    ELSE 'ORIGINAL_UNVERIFIED'::text
END) STORED,
    CONSTRAINT docs_evidence_copies_check CHECK ((((copy_kind = 'ORIGINAL'::text) AND (parent_copy_id IS NULL) AND (derivative_kind IS NULL)) OR ((copy_kind = 'DERIVATIVE'::text) AND (parent_copy_id IS NOT NULL) AND (derivative_kind IS NOT NULL)))),
    CONSTRAINT docs_evidence_copies_check1 CHECK (((worm_status = 'VERIFIED'::text) = (verified_at IS NOT NULL))),
    CONSTRAINT docs_evidence_copies_content_type_check CHECK (((char_length(btrim(content_type)) >= 1) AND (char_length(btrim(content_type)) <= 160))),
    CONSTRAINT docs_evidence_copies_copy_kind_check CHECK ((copy_kind = ANY (ARRAY['ORIGINAL'::text, 'DERIVATIVE'::text]))),
    CONSTRAINT docs_evidence_copies_derivative_kind_check CHECK (((derivative_kind IS NULL) OR (derivative_kind = ANY (ARRAY['REDACTED'::text, 'THUMBNAIL'::text, 'TRANSCODED'::text, 'EXCERPT'::text, 'EXPORT_MANIFEST'::text, 'NORMALIZED_TEXT'::text, 'OTHER'::text])))),
    CONSTRAINT docs_evidence_copies_digest_sha256_check CHECK ((digest_sha256 ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT docs_evidence_copies_evidentiary_status_check CHECK ((evidentiary_status = ANY (ARRAY['VERIFIED_ORIGINAL'::text, 'ORIGINAL_UNVERIFIED'::text, 'NON_EVIDENTIARY_DERIVATIVE'::text]))),
    CONSTRAINT docs_evidence_copies_size_bytes_check CHECK ((size_bytes >= 0)),
    CONSTRAINT docs_evidence_copies_storage_key_ref_check CHECK (((storage_key_ref IS NULL) OR ((char_length(btrim(storage_key_ref)) >= 1) AND (char_length(btrim(storage_key_ref)) <= 500)))),
    CONSTRAINT docs_evidence_copies_storage_object_id_check CHECK (((char_length(btrim(storage_object_id)) >= 1) AND (char_length(btrim(storage_object_id)) <= 300))),
    CONSTRAINT docs_evidence_copies_storage_provider_check CHECK (((char_length(btrim(storage_provider)) >= 1) AND (char_length(btrim(storage_provider)) <= 80))),
    CONSTRAINT docs_evidence_copies_storage_version_id_check CHECK (((storage_version_id IS NULL) OR ((char_length(btrim(storage_version_id)) >= 1) AND (char_length(btrim(storage_version_id)) <= 200)))),
    CONSTRAINT docs_evidence_copies_worm_status_check CHECK ((worm_status = ANY (ARRAY['PENDING'::text, 'VERIFIED'::text, 'FAILED'::text])))
);

ALTER TABLE ONLY public.docs_evidence_copies FORCE ROW LEVEL SECURITY;


ALTER TABLE public.docs_evidence_copies OWNER TO console_app;

