    CONSTRAINT docs_evidence_tsa_proofs_token_storage_provider_check CHECK (((token_storage_provider IS NULL) OR ((char_length(btrim(token_storage_provider)) >= 1) AND (char_length(btrim(token_storage_provider)) <= 80)))),
    CONSTRAINT docs_evidence_tsa_proofs_token_storage_version_id_check CHECK (((token_storage_version_id IS NULL) OR ((char_length(btrim(token_storage_version_id)) >= 1) AND (char_length(btrim(token_storage_version_id)) <= 200)))),
    CONSTRAINT docs_evidence_tsa_proofs_tsa_cert_fingerprint_sha256_check CHECK (((tsa_cert_fingerprint_sha256 IS NULL) OR (tsa_cert_fingerprint_sha256 ~ '^[a-f0-9]{64}$'::text)))
);

