--
-- Name: email_accounts; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.email_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    branch_id uuid,
    display_name text NOT NULL,
    email_address text NOT NULL,
    from_name text,
    imap_host text NOT NULL,
    imap_port integer NOT NULL,
    imap_security text NOT NULL,
    imap_username text NOT NULL,
    smtp_host text NOT NULL,
    smtp_port integer NOT NULL,
    smtp_security text NOT NULL,
    smtp_username text NOT NULL,
    smtp_password_ct bytea NOT NULL,
    smtp_password_nonce bytea NOT NULL,
    imap_password_ct bytea NOT NULL,
    imap_password_nonce bytea NOT NULL,
    dek_wrapped bytea NOT NULL,
    dek_nonce bytea NOT NULL,
    key_version smallint DEFAULT 1 NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    last_sync_at timestamp with time zone,
    last_sync_error text,
    sync_status text DEFAULT 'NEVER_SYNCED'::text NOT NULL,
    sync_cadence_secs integer DEFAULT 120 NOT NULL,
    backfill_window_days integer DEFAULT 90 NOT NULL,
    consecutive_auth_failures integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    imap_dek_wrapped bytea NOT NULL,
    imap_dek_nonce bytea NOT NULL,
    claimed_until timestamp with time zone,
    claim_token uuid,
    CONSTRAINT email_accounts_backfill_window_days_check CHECK (((backfill_window_days >= 1) AND (backfill_window_days <= 3650))),
    CONSTRAINT email_accounts_consecutive_auth_failures_check CHECK ((consecutive_auth_failures >= 0)),
    CONSTRAINT email_accounts_display_name_check CHECK (((btrim(display_name) <> ''::text) AND (length(display_name) <= 200))),
    CONSTRAINT email_accounts_email_address_check CHECK (((btrim(email_address) <> ''::text) AND (length(email_address) <= 320))),
    CONSTRAINT email_accounts_from_name_check CHECK (((from_name IS NULL) OR (length(from_name) <= 200))),
    CONSTRAINT email_accounts_imap_host_check CHECK (((btrim(imap_host) <> ''::text) AND (length(imap_host) <= 255))),
    CONSTRAINT email_accounts_imap_port_check CHECK ((imap_port = ANY (ARRAY[143, 993]))),
    CONSTRAINT email_accounts_imap_security_check CHECK ((imap_security = ANY (ARRAY['TLS'::text, 'STARTTLS'::text]))),
    CONSTRAINT email_accounts_imap_username_check CHECK ((btrim(imap_username) <> ''::text)),
    CONSTRAINT email_accounts_smtp_host_check CHECK (((btrim(smtp_host) <> ''::text) AND (length(smtp_host) <= 255))),
    CONSTRAINT email_accounts_smtp_port_check CHECK ((smtp_port = ANY (ARRAY[465, 587]))),
    CONSTRAINT email_accounts_smtp_security_check CHECK ((smtp_security = ANY (ARRAY['TLS'::text, 'STARTTLS'::text]))),
    CONSTRAINT email_accounts_smtp_username_check CHECK ((btrim(smtp_username) <> ''::text)),
    CONSTRAINT email_accounts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'PAUSED'::text, 'ERROR'::text, 'DISABLED'::text]))),
    CONSTRAINT email_accounts_sync_cadence_secs_check CHECK ((sync_cadence_secs >= 30)),
    CONSTRAINT email_accounts_sync_status_check CHECK ((sync_status = ANY (ARRAY['OK'::text, 'AUTH_FAILED'::text, 'UNREACHABLE'::text, 'NEVER_SYNCED'::text])))
);

ALTER TABLE ONLY public.email_accounts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.email_accounts OWNER TO console_app;

