-- Name: email_messages; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.email_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    account_id uuid NOT NULL,
    folder_id uuid NOT NULL,
    thread_id uuid NOT NULL,
    imap_uid bigint,
    imap_uid_validity bigint,
    message_id text,
    in_reply_to text,
    references_ids text[] DEFAULT '{}'::text[] NOT NULL,
    direction text NOT NULL,
    from_address text NOT NULL,
    from_name text,
    to_addresses jsonb DEFAULT '[]'::jsonb NOT NULL,
    cc_addresses jsonb DEFAULT '[]'::jsonb NOT NULL,
    bcc_addresses jsonb DEFAULT '[]'::jsonb NOT NULL,
    subject text DEFAULT ''::text NOT NULL,
    snippet text DEFAULT ''::text NOT NULL,
    body_text text,
    body_html text,
    seen boolean DEFAULT false NOT NULL,
    flagged boolean DEFAULT false NOT NULL,
    answered boolean DEFAULT false NOT NULL,
    draft boolean DEFAULT false NOT NULL,
    has_attachments boolean DEFAULT false NOT NULL,
    send_status text,
    send_error text,
    received_at timestamp with time zone NOT NULL,
    sent_at timestamp with time zone,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple'::regconfig, ((((((COALESCE(subject, ''::text) || ' '::text) || COALESCE(snippet, ''::text)) || ' '::text) || COALESCE(from_name, ''::text)) || ' '::text) || COALESCE(from_address, ''::text)))) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT email_messages_direction_check CHECK ((direction = ANY (ARRAY['IN'::text, 'OUT'::text]))),
    CONSTRAINT email_messages_imap_uid_check CHECK (((imap_uid IS NULL) OR (imap_uid >= 0))),
    CONSTRAINT email_messages_send_status_check CHECK ((send_status = ANY (ARRAY['PENDING'::text, 'SENT'::text, 'FAILED'::text])))
);

