--

CREATE TABLE public.employee_absence_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    branch_id uuid,
    work_date date NOT NULL,
    source text DEFAULT 'attendance_direct_import'::text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    severity text DEFAULT 'WARNING'::text NOT NULL,
    audience_roles text[] DEFAULT ARRAY['site_manager'::text, 'employee_hr_manager'::text, 'hq_hr_manager'::text, 'payroll_manager'::text, 'insurance_loss_reporter'::text] NOT NULL,
    signal_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    detected_at timestamp with time zone DEFAULT now() NOT NULL,
    acknowledged_by uuid,
    acknowledged_at timestamp with time zone,
    linked_exit_case_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_absence_alerts_severity_check CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text]))),
    CONSTRAINT employee_absence_alerts_source_check CHECK ((source = ANY (ARRAY['attendance_direct_import'::text, 'employee_self_service_gap'::text, 'manual'::text]))),
    CONSTRAINT employee_absence_alerts_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'LINKED_EXIT'::text, 'RESOLVED'::text])))
);

ALTER TABLE ONLY public.employee_absence_alerts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.employee_absence_alerts OWNER TO console_app;

