CREATE TABLE public.employee_attendance_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    kind text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    work_date date DEFAULT ((now() AT TIME ZONE 'Asia/Seoul'::text))::date NOT NULL,
    state_after text NOT NULL,
    note text,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_attendance_records_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (char_length(idempotency_key) <= 128))),
    CONSTRAINT employee_attendance_records_kind_check CHECK ((kind = ANY (ARRAY['CLOCK_IN'::text, 'OUT_FOR_WORK'::text, 'BUSINESS_TRIP'::text, 'RETURNED'::text, 'CLOCK_OUT'::text]))),
    CONSTRAINT employee_attendance_records_note_check CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT employee_attendance_records_state_after_check CHECK ((state_after = ANY (ARRAY['CLOCKED_IN'::text, 'OUT_FOR_WORK'::text, 'BUSINESS_TRIP'::text, 'OFF_DUTY'::text])))
);

ALTER TABLE ONLY public.employee_attendance_records FORCE ROW LEVEL SECURITY;


