    amount_won bigint NOT NULL,
    monthly_standard_hours integer NOT NULL,
    source_note text DEFAULT ''::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_contract_wages_amount_won_check CHECK ((amount_won > 0)),
    CONSTRAINT employee_contract_wages_monthly_standard_hours_check CHECK (((monthly_standard_hours > 0) AND (monthly_standard_hours <= 400))),
    CONSTRAINT employee_contract_wages_source_note_check CHECK ((char_length(source_note) <= 500)),
    CONSTRAINT employee_contract_wages_wage_kind_check CHECK ((wage_kind = ANY (ARRAY['MONTHLY'::text, 'HOURLY'::text])))
);

ALTER TABLE ONLY public.employee_contract_wages FORCE ROW LEVEL SECURITY;


