    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT employee_exit_cases_confirmation_note_check CHECK (((confirmation_note IS NULL) OR (char_length(confirmation_note) <= 1000))),
    CONSTRAINT employee_exit_cases_site_manager_note_check CHECK (((btrim(site_manager_note) <> ''::text) AND (char_length(site_manager_note) <= 1000))),
    CONSTRAINT employee_exit_cases_status_check CHECK ((status = ANY (ARRAY['REPORTED'::text, 'HR_CONFIRMED'::text, 'HQ_CONFIRMED'::text, 'SETTLEMENT_READY'::text, 'APPROVAL_DRAFTED'::text, 'SUBMITTED'::text, 'REJECTED'::text, 'CANCELLED'::text])))
);

