ALTER TABLE public.employee_exit_cases OWNER TO console_app;

--
-- Name: employee_exit_settlement_packages; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.employee_exit_settlement_packages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    exit_case_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    status text DEFAULT 'NEEDS_SOURCE'::text NOT NULL,
    service_days integer,
    average_wage_period_start date,
    average_wage_period_end date,
    average_wage_calendar_days integer,
    average_wage_total_won bigint,
    average_daily_wage_milliwon bigint,
    severance_pay_won bigint,
    missing_source_fields text[] DEFAULT '{}'::text[] CONSTRAINT employee_exit_settlement_package_missing_source_fields_not_null NOT NULL,
    statutory_basis jsonb DEFAULT '{}'::jsonb NOT NULL,
    insurance_loss_payload jsonb DEFAULT '{}'::jsonb CONSTRAINT employee_exit_settlement_packag_insurance_loss_payload_not_null NOT NULL,
    approval_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    certification_status text DEFAULT 'UNCERTIFIED_DRAFT'::text NOT NULL,
    certification_artifact jsonb,
    certified_package_digest text,
    monthly_ordinary_wage_won bigint,
    ordinary_daily_wage_won bigint,
    statutory_daily_wage_milliwon bigint,
    CONSTRAINT employee_exit_settlement_pac_statutory_daily_wage_milliwo_check CHECK (((statutory_daily_wage_milliwon IS NULL) OR (statutory_daily_wage_milliwon >= 0))),
    CONSTRAINT employee_exit_settlement_pack_average_daily_wage_milliwon_check CHECK (((average_daily_wage_milliwon IS NULL) OR (average_daily_wage_milliwon >= 0))),
    CONSTRAINT employee_exit_settlement_packa_average_wage_calendar_days_check CHECK (((average_wage_calendar_days IS NULL) OR (average_wage_calendar_days > 0))),
    CONSTRAINT employee_exit_settlement_packag_monthly_ordinary_wage_won_check CHECK (((monthly_ordinary_wage_won IS NULL) OR (monthly_ordinary_wage_won >= 0))),
    CONSTRAINT employee_exit_settlement_packages_average_wage_total_won_check CHECK (((average_wage_total_won IS NULL) OR (average_wage_total_won >= 0))),
    CONSTRAINT employee_exit_settlement_packages_cert_artifact_shape_chk CHECK (((certification_artifact IS NULL) OR ((jsonb_typeof(certification_artifact) = 'object'::text) AND (certification_artifact ?& ARRAY['reviewer_kind'::text, 'reviewed_on'::text, 'artifact_sha256'::text, 'reviewer_reference'::text]) AND ((certification_artifact ->> 'artifact_sha256'::text) ~ '^[0-9a-f]{64}$'::text) AND ((certification_artifact ->> 'reviewer_kind'::text) = ANY (ARRAY['LABOR_ATTORNEY'::text, 'TAX_ACCOUNTANT'::text])) AND
CASE
    WHEN (jsonb_typeof(certification_artifact) = 'object'::text) THEN ((certification_artifact - ARRAY['reviewer_kind'::text, 'reviewed_on'::text, 'artifact_sha256'::text, 'reviewer_reference'::text]) = '{}'::jsonb)
    ELSE false
END))),
    CONSTRAINT employee_exit_settlement_packages_cert_digest_shape_chk CHECK (((certified_package_digest IS NULL) OR (certified_package_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT employee_exit_settlement_packages_cert_pairing_chk CHECK (((certification_status = 'UNCERTIFIED_DRAFT'::text) OR ((certification_artifact IS NOT NULL) AND (certified_package_digest IS NOT NULL)))),
    CONSTRAINT employee_exit_settlement_packages_certification_status_check CHECK ((certification_status = ANY (ARRAY['UNCERTIFIED_DRAFT'::text, 'CERTIFIED'::text]))),
    CONSTRAINT employee_exit_settlement_packages_ordinary_daily_wage_won_check CHECK (((ordinary_daily_wage_won IS NULL) OR (ordinary_daily_wage_won >= 0))),
    CONSTRAINT employee_exit_settlement_packages_service_days_check CHECK (((service_days IS NULL) OR (service_days >= 0))),
    CONSTRAINT employee_exit_settlement_packages_severance_pay_won_check CHECK (((severance_pay_won IS NULL) OR (severance_pay_won >= 0))),
    CONSTRAINT employee_exit_settlement_packages_status_check CHECK ((status = ANY (ARRAY['NEEDS_SOURCE'::text, 'READY_FOR_APPROVAL'::text, 'APPROVAL_DRAFTED'::text, 'SUBMITTED'::text])))
);

ALTER TABLE ONLY public.employee_exit_settlement_packages FORCE ROW LEVEL SECURITY;


ALTER TABLE public.employee_exit_settlement_packages OWNER TO console_app;

