--
-- Name: employees; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    company text NOT NULL,
    name text NOT NULL,
    source_filename text NOT NULL,
    source_sheet text NOT NULL,
    source_row integer NOT NULL,
    source_key text NOT NULL,
    raw_row jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    employee_number text,
    org_unit text,
    job text,
    "position" text,
    worksite_name text,
    worksite_address text,
    hire_date text,
    exit_date text,
    employment_status text DEFAULT 'ACTIVE'::text NOT NULL,
    leave_accrued numeric(16,6),
    leave_used numeric(16,6),
    leave_remaining numeric(16,6),
    identity_resolution_strategy text DEFAULT 'source_row_fingerprint'::text NOT NULL,
    identity_resolution_confidence text DEFAULT 'low'::text NOT NULL,
    identity_review_required boolean DEFAULT true NOT NULL,
    identity_name_only_merge boolean DEFAULT false NOT NULL,
    home_branch_id uuid,
    CONSTRAINT employees_company_check CHECK ((btrim(company) <> ''::text)),
    CONSTRAINT employees_employment_status_check CHECK ((employment_status = ANY (ARRAY['ACTIVE'::text, 'EXITED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT employees_identity_name_only_merge_check CHECK ((identity_name_only_merge = false)),
    CONSTRAINT employees_identity_resolution_confidence_check CHECK ((identity_resolution_confidence = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text]))),
    CONSTRAINT employees_identity_resolution_strategy_check CHECK ((identity_resolution_strategy = ANY (ARRAY['employee_number'::text, 'legal_identifier_hash'::text, 'birth_hire_fingerprint'::text, 'source_row_fingerprint'::text]))),
    CONSTRAINT employees_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT employees_source_filename_check CHECK ((btrim(source_filename) <> ''::text)),
    CONSTRAINT employees_source_key_check CHECK ((btrim(source_key) <> ''::text)),
    CONSTRAINT employees_source_row_check CHECK ((source_row > 0)),
    CONSTRAINT employees_source_sheet_check CHECK ((btrim(source_sheet) <> ''::text))
);

ALTER TABLE ONLY public.employees FORCE ROW LEVEL SECURITY;


ALTER TABLE public.employees OWNER TO console_app;

