--

CREATE TABLE public.equipment_3r_dispositions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    case_id uuid NOT NULL,
    assessment_id uuid NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    cost_minor bigint,
    sale_amount_minor bigint,
    buyer_name text,
    completed_by uuid,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT equipment_3r_dispositions_buyer_name_check CHECK (((buyer_name IS NULL) OR ((char_length(btrim(buyer_name)) >= 1) AND (char_length(btrim(buyer_name)) <= 160)))),
    CONSTRAINT equipment_3r_dispositions_cost_minor_check CHECK (((cost_minor IS NULL) OR (cost_minor >= 0))),
    CONSTRAINT equipment_3r_dispositions_kind_check CHECK ((kind = ANY (ARRAY['REPAIR'::text, 'REFURBISH'::text, 'RESALE'::text, 'REDEPLOY'::text]))),
    CONSTRAINT equipment_3r_dispositions_sale_amount_minor_check CHECK (((sale_amount_minor IS NULL) OR (sale_amount_minor >= 0))),
    CONSTRAINT equipment_3r_dispositions_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'COMPLETED'::text])))
);

ALTER TABLE ONLY public.equipment_3r_dispositions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.equipment_3r_dispositions OWNER TO console_app;

