    CONSTRAINT equipment_3r_inspections_maintenance_note_check CHECK (((maintenance_note IS NULL) OR ((char_length(btrim(maintenance_note)) >= 1) AND (char_length(btrim(maintenance_note)) <= 2000)))),
    CONSTRAINT equipment_3r_inspections_outcome_check CHECK ((outcome = ANY (ARRAY['PASS'::text, 'MAINTENANCE_PERFORMED'::text]))),
