--
-- Name: leave_requests; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.leave_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    requester_user_id uuid NOT NULL,
    subject_employee_id uuid NOT NULL,
    leave_type text NOT NULL,
    days numeric(16,6) NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    reason text,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_comment text,
    ap_run_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_days numeric(16,6) GENERATED ALWAYS AS (days) STORED,
    partial_day_period text,
    charge_state text DEFAULT 'review_required'::text NOT NULL,
    charge_review_reasons text[] DEFAULT ARRAY['missing_calendar'::text] NOT NULL,
    charge_units numeric(16,6),
    submission_key uuid,
    submission_digest character(64),
    submission_initial_charge_version bigint,
    request_version bigint DEFAULT 1 NOT NULL,
    charge_version bigint DEFAULT 0 NOT NULL,
    current_charge_resolution_id uuid,
    time_change_grounds text,
    time_change_evidence jsonb,
    alternate_start_date date,
    alternate_end_date date,
    alternate_partial_day_period text,
    alternate_proposed_at timestamp with time zone,
    CONSTRAINT leave_requests_alternate_dates_atomic CHECK ((((alternate_start_date IS NULL) = (alternate_end_date IS NULL)) AND ((alternate_start_date IS NULL) = (alternate_proposed_at IS NULL)) AND ((alternate_start_date IS NULL) OR (alternate_end_date >= alternate_start_date)))),
    CONSTRAINT leave_requests_alternate_partial_day_period_check CHECK (((alternate_partial_day_period IS NULL) OR (alternate_partial_day_period = ANY (ARRAY['am'::text, 'pm'::text])))),
    CONSTRAINT leave_requests_charge_review_reason_values CHECK (((array_position(charge_review_reasons, NULL::text) IS NULL) AND (charge_review_reasons <@ ARRAY['missing_calendar'::text, 'ambiguous_calendar'::text, 'calendar_source_unavailable'::text, 'missing_policy'::text, 'ambiguous_policy'::text, 'policy_source_unavailable'::text]))),
    CONSTRAINT leave_requests_charge_shape CHECK ((((charge_state = 'review_required'::text) AND (cardinality(charge_review_reasons) > 0) AND (charge_units IS NULL) AND (current_charge_resolution_id IS NULL)) OR ((charge_state = 'resolved'::text) AND (cardinality(charge_review_reasons) = 0) AND (charge_units IS NOT NULL) AND (current_charge_resolution_id IS NOT NULL)) OR ((charge_state = 'legacy_unverified'::text) AND (cardinality(charge_review_reasons) = 0) AND (charge_units IS NOT NULL) AND (current_charge_resolution_id IS NULL)) OR ((charge_state = 'not_required'::text) AND (cardinality(charge_review_reasons) = 0) AND (charge_units IS NULL) AND (current_charge_resolution_id IS NULL)))),
    CONSTRAINT leave_requests_charge_state_check CHECK ((charge_state = ANY (ARRAY['review_required'::text, 'resolved'::text, 'not_required'::text, 'legacy_unverified'::text]))),
    CONSTRAINT leave_requests_charge_units_check CHECK (((charge_units IS NULL) OR ((charge_units > (0)::numeric) AND (charge_units <= (366)::numeric)))),
    CONSTRAINT leave_requests_charge_version_check CHECK ((charge_version >= 0)),
    CONSTRAINT leave_requests_check CHECK ((end_date >= start_date)),
    CONSTRAINT leave_requests_days_check CHECK (((days > (0)::numeric) AND (days <= (366)::numeric))),
    CONSTRAINT leave_requests_decision_atomic CHECK (((decided_by IS NULL) = (decided_at IS NULL))),
    CONSTRAINT leave_requests_decision_comment_check CHECK (((decision_comment IS NULL) OR ((char_length(btrim(decision_comment)) >= 1) AND (char_length(btrim(decision_comment)) <= 500)))),
    CONSTRAINT leave_requests_leave_type_check CHECK ((leave_type = ANY (ARRAY['annual'::text, 'half_day'::text]))),
    CONSTRAINT leave_requests_partial_day_period_check CHECK ((partial_day_period = ANY (ARRAY['am'::text, 'pm'::text]))),
    CONSTRAINT leave_requests_partial_day_shape CHECK (((legacy_days IS NOT NULL) OR ((leave_type = 'half_day'::text) = (partial_day_period IS NOT NULL)))),
    CONSTRAINT leave_requests_pending_iff_undecided CHECK (((status = 'pending'::text) = (decided_by IS NULL))),
    CONSTRAINT leave_requests_request_version_check CHECK ((request_version > 0)),
    CONSTRAINT leave_requests_sod CHECK (((decided_by IS NULL) OR (decided_by <> requester_user_id))),
    CONSTRAINT leave_requests_status_charge_state CHECK ((((status = 'pending'::text) AND (charge_state = ANY (ARRAY['review_required'::text, 'resolved'::text]))) OR ((status = 'approved'::text) AND (charge_state = ANY (ARRAY['resolved'::text, 'legacy_unverified'::text]))) OR ((status = 'time_change_consult'::text) AND (charge_state = 'not_required'::text)) OR ((status = ANY (ARRAY['returned'::text, 'rejected'::text])) AND (charge_state = 'not_required'::text)))),
    CONSTRAINT leave_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'time_change_consult'::text, 'returned'::text, 'rejected'::text]))),
    CONSTRAINT leave_requests_submission_digest_check CHECK (((submission_digest IS NULL) OR (submission_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT leave_requests_submission_initial_charge_version_check CHECK ((submission_initial_charge_version = ANY (ARRAY[(0)::bigint, (1)::bigint]))),
    CONSTRAINT leave_requests_submission_pair CHECK ((((submission_key IS NULL) = (submission_digest IS NULL)) AND ((submission_key IS NULL) = (submission_initial_charge_version IS NULL)))),
    CONSTRAINT leave_requests_time_change_fields_status CHECK (((status = 'time_change_consult'::text) OR ((time_change_grounds IS NULL) AND (alternate_start_date IS NULL)))),
    CONSTRAINT leave_requests_time_change_grounds_atomic CHECK (((time_change_grounds IS NULL) = (time_change_evidence IS NULL))),
    CONSTRAINT leave_requests_time_change_grounds_check CHECK (((time_change_grounds IS NULL) OR (time_change_grounds = 'branch_coverage_shortfall'::text)))
);

