--

CREATE TABLE public.location_pings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    latitude double precision NOT NULL,
    longitude double precision NOT NULL,
    accuracy_m double precision,
    recorded_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    on_duty boolean NOT NULL,
    org_id uuid NOT NULL,
    CONSTRAINT location_pings_accuracy_m_check CHECK (((accuracy_m IS NULL) OR (((accuracy_m)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])) AND (accuracy_m >= (0)::double precision)))),
    CONSTRAINT location_pings_latitude_check CHECK ((((latitude)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])) AND ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)))),
    CONSTRAINT location_pings_longitude_check CHECK ((((longitude)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])) AND ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))))
)
PARTITION BY RANGE (recorded_at);

ALTER TABLE ONLY public.location_pings FORCE ROW LEVEL SECURITY;


ALTER TABLE public.location_pings OWNER TO console_app;

