--

CREATE TABLE public.logistics_asns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    warehouse_code text NOT NULL,
    external_reference text NOT NULL,
    sku text NOT NULL,
    expected_quantity bigint NOT NULL,
    received_quantity bigint DEFAULT 0 NOT NULL,
    status text DEFAULT 'EXPECTED'::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT logistics_asns_check CHECK (((received_quantity >= 0) AND (received_quantity <= expected_quantity))),
    CONSTRAINT logistics_asns_expected_quantity_check CHECK ((expected_quantity > 0)),
    CONSTRAINT logistics_asns_external_reference_check CHECK (((char_length(btrim(external_reference)) >= 1) AND (char_length(btrim(external_reference)) <= 120))),
    CONSTRAINT logistics_asns_sku_check CHECK (((char_length(btrim(sku)) >= 1) AND (char_length(btrim(sku)) <= 80))),
    CONSTRAINT logistics_asns_status_check CHECK ((status = ANY (ARRAY['EXPECTED'::text, 'PARTIAL_RECEIVED'::text, 'RECEIVED'::text, 'PUTAWAY'::text]))),
    CONSTRAINT logistics_asns_warehouse_code_check CHECK (((char_length(btrim(warehouse_code)) >= 1) AND (char_length(btrim(warehouse_code)) <= 80)))
);

