    CONSTRAINT logistics_fulfillments_requested_quantity_check CHECK ((requested_quantity > 0)),
    CONSTRAINT logistics_fulfillments_status_check CHECK ((status = ANY (ARRAY['RELEASED'::text, 'PICKED'::text, 'SHORT_PICK'::text, 'PACKED'::text, 'DISPATCHED'::text, 'DELIVERED'::text, 'SETTLED'::text])))
