    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_aliases_alias_kind_check CHECK ((alias_kind = ANY (ARRAY['DIRECT'::text, 'SHARED'::text, 'ROLE'::text, 'GROUP'::text, 'CATCH_ALL'::text]))),
    CONSTRAINT mailbox_aliases_check CHECK ((((alias_kind = 'CATCH_ALL'::text) AND (local_part = '*'::text)) OR ((alias_kind <> 'CATCH_ALL'::text) AND (local_part <> '*'::text)))),
    CONSTRAINT mailbox_aliases_local_part_check CHECK ((((char_length(local_part) >= 1) AND (char_length(local_part) <= 64)) AND (local_part = lower(local_part)) AND ((local_part = '*'::text) OR ((local_part ~ '^[a-z0-9]([a-z0-9._+-]{0,62}[a-z0-9])?$'::text) AND (local_part !~ '\.\.'::text))))),
    CONSTRAINT mailbox_aliases_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text])))
);

