--

CREATE TABLE public.mailbox_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    mailbox_message_id uuid,
    direction text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    envelope_from text,
    recipient_domain text NOT NULL,
    recipient_local_part text NOT NULL,
    remote_addr_hash text,
    queue_key text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    locked_by text,
    locked_until timestamp with time zone,
    rejection_reason text,
    error_payload jsonb,
    accepted_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_deliveries_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT mailbox_deliveries_check CHECK (((completed_at IS NULL) OR (status = ANY (ARRAY['STORED'::text, 'DELIVERED'::text, 'REJECTED'::text, 'FAILED'::text, 'BOUNCED'::text, 'DEAD_LETTERED'::text, 'CANCELLED'::text])))),
    CONSTRAINT mailbox_deliveries_check1 CHECK (((rejection_reason IS NULL) OR (status = ANY (ARRAY['REJECTED'::text, 'FAILED'::text, 'BOUNCED'::text, 'DEAD_LETTERED'::text])))),
    CONSTRAINT mailbox_deliveries_direction_check CHECK ((direction = ANY (ARRAY['IN'::text, 'OUT'::text]))),
    CONSTRAINT mailbox_deliveries_envelope_from_check CHECK (((envelope_from IS NULL) OR (char_length(envelope_from) <= 320))),
    CONSTRAINT mailbox_deliveries_error_payload_check CHECK (((error_payload IS NULL) OR (jsonb_typeof(error_payload) = 'object'::text))),
    CONSTRAINT mailbox_deliveries_locked_by_check CHECK (((locked_by IS NULL) OR ((char_length(btrim(locked_by)) >= 1) AND (char_length(btrim(locked_by)) <= 160)))),
    CONSTRAINT mailbox_deliveries_queue_key_check CHECK (((char_length(btrim(queue_key)) >= 16) AND (char_length(btrim(queue_key)) <= 200))),
    CONSTRAINT mailbox_deliveries_recipient_domain_check CHECK (((recipient_domain = lower(recipient_domain)) AND ((char_length(recipient_domain) >= 4) AND (char_length(recipient_domain) <= 253)) AND (recipient_domain ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'::text))),
    CONSTRAINT mailbox_deliveries_recipient_local_part_check CHECK ((((char_length(recipient_local_part) >= 1) AND (char_length(recipient_local_part) <= 64)) AND (recipient_local_part = lower(recipient_local_part)) AND (recipient_local_part ~ '^[a-z0-9]([a-z0-9._+-]{0,62}[a-z0-9])?$'::text) AND (recipient_local_part !~ '\.\.'::text))),
    CONSTRAINT mailbox_deliveries_rejection_reason_check CHECK (((rejection_reason IS NULL) OR (rejection_reason ~ '^[a-z][a-z0-9_]{1,80}$'::text))),
    CONSTRAINT mailbox_deliveries_remote_addr_hash_check CHECK (((remote_addr_hash IS NULL) OR ((char_length(remote_addr_hash) >= 16) AND (char_length(remote_addr_hash) <= 128)))),
    CONSTRAINT mailbox_deliveries_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'ACCEPTED'::text, 'STORED'::text, 'QUEUED'::text, 'DELIVERED'::text, 'REJECTED'::text, 'FAILED'::text, 'BOUNCED'::text, 'DEAD_LETTERED'::text, 'CANCELLED'::text])))
);

