--

CREATE TABLE public.mailbox_domains (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    group_id uuid,
    domain text NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    verification_status text DEFAULT 'NOT_STARTED'::text NOT NULL,
    mx_verified boolean DEFAULT false NOT NULL,
    spf_verified boolean DEFAULT false NOT NULL,
    dkim_verified boolean DEFAULT false NOT NULL,
    dmarc_verified boolean DEFAULT false NOT NULL,
    mta_sts_verified boolean DEFAULT false NOT NULL,
    tls_rpt_verified boolean DEFAULT false NOT NULL,
    dkim_selector text,
    dkim_public_key_ref text,
    dkim_private_key_ref text,
    dns_last_checked_at timestamp with time zone,
    last_error_code text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_domains_check CHECK (((status <> 'ACTIVE'::text) OR ((verification_status = 'VERIFIED'::text) AND mx_verified AND spf_verified AND dkim_verified AND dmarc_verified))),
    CONSTRAINT mailbox_domains_dkim_private_key_ref_check CHECK (((dkim_private_key_ref IS NULL) OR ((char_length(btrim(dkim_private_key_ref)) >= 8) AND (char_length(btrim(dkim_private_key_ref)) <= 300)))),
    CONSTRAINT mailbox_domains_dkim_public_key_ref_check CHECK (((dkim_public_key_ref IS NULL) OR ((char_length(btrim(dkim_public_key_ref)) >= 8) AND (char_length(btrim(dkim_public_key_ref)) <= 300)))),
    CONSTRAINT mailbox_domains_dkim_selector_check CHECK (((dkim_selector IS NULL) OR (dkim_selector ~ '^[a-z0-9][a-z0-9_-]{0,62}$'::text))),
    CONSTRAINT mailbox_domains_domain_check CHECK (((domain = lower(domain)) AND ((char_length(domain) >= 4) AND (char_length(domain) <= 253)) AND (domain ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'::text))),
    CONSTRAINT mailbox_domains_last_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z][a-z0-9_]{1,80}$'::text))),
    CONSTRAINT mailbox_domains_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'VERIFYING'::text, 'ACTIVE'::text, 'PAUSED'::text, 'DISABLED'::text, 'FAILED'::text]))),
    CONSTRAINT mailbox_domains_verification_status_check CHECK ((verification_status = ANY (ARRAY['NOT_STARTED'::text, 'PENDING_DNS'::text, 'VERIFIED'::text, 'FAILED'::text, 'EXPIRED'::text])))
);

