CREATE TABLE public.mailbox_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    mailbox_id uuid NOT NULL,
    domain_id uuid NOT NULL,
    folder_role text DEFAULT 'INBOX'::text NOT NULL,
    direction text NOT NULL,
    rfc_message_id text,
    in_reply_to text,
    references_ids text[] DEFAULT '{}'::text[] NOT NULL,
    normalized_subject text DEFAULT ''::text NOT NULL,
    raw_object_key text NOT NULL,
    raw_size_bytes bigint NOT NULL,
    has_attachments boolean DEFAULT false NOT NULL,
    seen boolean DEFAULT false NOT NULL,
    flagged boolean DEFAULT false NOT NULL,
    answered boolean DEFAULT false NOT NULL,
    draft boolean DEFAULT false NOT NULL,
    sensitivity text DEFAULT 'INTERNAL'::text NOT NULL,
    received_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_messages_check CHECK ((((direction = 'IN'::text) AND (received_at IS NOT NULL)) OR (direction = 'OUT'::text))),
    CONSTRAINT mailbox_messages_direction_check CHECK ((direction = ANY (ARRAY['IN'::text, 'OUT'::text]))),
    CONSTRAINT mailbox_messages_folder_role_check CHECK ((folder_role = ANY (ARRAY['INBOX'::text, 'SENT'::text, 'DRAFTS'::text, 'ARCHIVE'::text, 'TRASH'::text, 'JUNK'::text, 'CUSTOM'::text]))),
    CONSTRAINT mailbox_messages_in_reply_to_check CHECK (((in_reply_to IS NULL) OR (char_length(in_reply_to) <= 998))),
    CONSTRAINT mailbox_messages_normalized_subject_check CHECK ((char_length(normalized_subject) <= 998)),
    CONSTRAINT mailbox_messages_raw_object_key_check CHECK (((char_length(btrim(raw_object_key)) >= 8) AND (char_length(btrim(raw_object_key)) <= 600))),
    CONSTRAINT mailbox_messages_raw_size_bytes_check CHECK ((raw_size_bytes >= 0)),
    CONSTRAINT mailbox_messages_rfc_message_id_check CHECK (((rfc_message_id IS NULL) OR (char_length(rfc_message_id) <= 998))),
    CONSTRAINT mailbox_messages_sensitivity_check CHECK ((sensitivity = ANY (ARRAY['PUBLIC'::text, 'INTERNAL'::text, 'CONFIDENTIAL'::text, 'HR'::text, 'PAYROLL'::text, 'LEGAL'::text, 'SECRET'::text])))
);

