CREATE TABLE public.mailboxes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    domain_id uuid NOT NULL,
    local_part text NOT NULL,
    owner_user_id uuid,
    display_name text NOT NULL,
    mailbox_kind text DEFAULT 'USER'::text NOT NULL,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    quota_bytes bigint DEFAULT 1073741824 NOT NULL,
    retention_policy_key text,
    legal_hold boolean DEFAULT false NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailboxes_check CHECK ((((mailbox_kind = 'USER'::text) AND (owner_user_id IS NOT NULL)) OR (mailbox_kind <> 'USER'::text))),
    CONSTRAINT mailboxes_display_name_check CHECK (((char_length(btrim(display_name)) >= 1) AND (char_length(btrim(display_name)) <= 200))),
    CONSTRAINT mailboxes_local_part_check CHECK ((((char_length(local_part) >= 1) AND (char_length(local_part) <= 64)) AND (local_part = lower(local_part)) AND (local_part ~ '^[a-z0-9]([a-z0-9._+-]{0,62}[a-z0-9])?$'::text) AND (local_part !~ '\.\.'::text))),
    CONSTRAINT mailboxes_mailbox_kind_check CHECK ((mailbox_kind = ANY (ARRAY['USER'::text, 'SHARED'::text, 'ROLE'::text, 'SYSTEM'::text, 'ARCHIVE'::text]))),
    CONSTRAINT mailboxes_quota_bytes_check CHECK (((quota_bytes >= 1048576) AND (quota_bytes <= '1099511627776'::bigint))),
    CONSTRAINT mailboxes_retention_policy_key_check CHECK (((retention_policy_key IS NULL) OR (retention_policy_key ~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$'::text))),
    CONSTRAINT mailboxes_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'LOCKED'::text, 'DISABLED'::text, 'OFFBOARDED'::text, 'ARCHIVED'::text])))
);

