-- Name: payroll_draft_lines; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.payroll_draft_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    run_id uuid NOT NULL,
    employee_id uuid,
    employee_source_key text NOT NULL,
    employee_display_name text NOT NULL,
    employee_company text NOT NULL,
    payroll_source_row_count integer DEFAULT 0 NOT NULL,
    attendance_source_row_count integer DEFAULT 0 NOT NULL,
    attendance_event_count integer DEFAULT 0 NOT NULL,
    work_days numeric(10,2),
    regular_hours numeric(10,2),
    overtime_hours numeric(10,2),
    night_hours numeric(10,2),
    holiday_hours numeric(10,2),
    leave_used numeric(10,2),
    leave_remaining numeric(10,2),
    gross_pay_source_present boolean DEFAULT false NOT NULL,
    net_pay_source_present boolean DEFAULT false NOT NULL,
    nts_tax_row_status text DEFAULT 'REQUIRED_NOT_SUPPLIED'::text NOT NULL,
    calculation_status text DEFAULT 'BLOCKED_LEGAL_GATE'::text NOT NULL,
    blockers jsonb DEFAULT '[]'::jsonb NOT NULL,
    source_data_import_row_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_draft_lines_attendance_event_count_check CHECK ((attendance_event_count >= 0)),
    CONSTRAINT payroll_draft_lines_attendance_source_row_count_check CHECK ((attendance_source_row_count >= 0)),
    CONSTRAINT payroll_draft_lines_calculation_status_check CHECK ((calculation_status = ANY (ARRAY['BLOCKED_LEGAL_GATE'::text, 'READY_FOR_REVIEW'::text, 'APPROVED'::text, 'ISSUED'::text, 'VOID'::text]))),
    CONSTRAINT payroll_draft_lines_employee_company_check CHECK ((btrim(employee_company) <> ''::text)),
    CONSTRAINT payroll_draft_lines_employee_display_name_check CHECK ((btrim(employee_display_name) <> ''::text)),
    CONSTRAINT payroll_draft_lines_employee_source_key_check CHECK ((btrim(employee_source_key) <> ''::text)),
    CONSTRAINT payroll_draft_lines_nts_tax_row_status_check CHECK ((nts_tax_row_status = ANY (ARRAY['REQUIRED_NOT_SUPPLIED'::text, 'SUPPLIED_UNVERIFIED'::text, 'VERIFIED_SOURCE_ROW'::text]))),
    CONSTRAINT payroll_draft_lines_payroll_source_row_count_check CHECK ((payroll_source_row_count >= 0)),
    CONSTRAINT payroll_draft_lines_same_org_employee CHECK (((employee_id IS NULL) OR (org_id IS NOT NULL)))
);

ALTER TABLE ONLY public.payroll_draft_lines FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_draft_lines OWNER TO console_app;

