--
-- Name: payroll_draft_runs; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.payroll_draft_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    source_label text NOT NULL,
    status text DEFAULT 'BLOCKED_LEGAL_GATE'::text NOT NULL,
    calculation_enabled boolean DEFAULT false NOT NULL,
    legal_basis jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    close_receipt jsonb,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    approval_ref uuid,
    CONSTRAINT payroll_draft_runs_enabled_requires_review CHECK (((calculation_enabled = false) OR (status = ANY (ARRAY['READY_FOR_REVIEW'::text, 'ATTENDANCE_CLOSED'::text, 'CALCULATING'::text, 'CALCULATED'::text, 'SUBMITTED'::text, 'REJECTED'::text, 'APPROVED'::text, 'DISBURSEMENT_SCHEDULED'::text, 'PAID'::text, 'ISSUED'::text])))),
    CONSTRAINT payroll_draft_runs_sod CHECK (((decided_by IS NULL) OR (submitted_by IS NULL) OR (decided_by <> submitted_by))),
    CONSTRAINT payroll_draft_runs_source_label_check CHECK ((btrim(source_label) <> ''::text)),
    CONSTRAINT payroll_draft_runs_status_check CHECK ((status = ANY (ARRAY['STAGED'::text, 'BLOCKED_LEGAL_GATE'::text, 'READY_FOR_REVIEW'::text, 'ATTENDANCE_CLOSED'::text, 'CALCULATING'::text, 'CALCULATED'::text, 'SUBMITTED'::text, 'REJECTED'::text, 'APPROVED'::text, 'DISBURSEMENT_SCHEDULED'::text, 'PAID'::text, 'ISSUED'::text, 'VOID'::text]))),
    CONSTRAINT payroll_draft_runs_valid_period CHECK ((period_end >= period_start))
);

ALTER TABLE ONLY public.payroll_draft_runs FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_draft_runs OWNER TO console_app;

