    net_won bigint NOT NULL,
    tax_table_version text NOT NULL,
    payable boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_line_calculations_gross_won_check CHECK ((gross_won >= 0)),
    CONSTRAINT payroll_line_calculations_tax_table_version_check CHECK ((btrim(tax_table_version) <> ''::text)),
    CONSTRAINT payroll_line_calculations_total_deductions_won_check CHECK ((total_deductions_won >= 0)),
    CONSTRAINT payroll_line_calculations_version_check CHECK ((version >= 1))
);

