--
-- Name: payroll_run_exceptions; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.payroll_run_exceptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    run_id uuid NOT NULL,
    line_id uuid,
    employee_id uuid,
    employee_display_name text NOT NULL,
    kind text NOT NULL,
    severity text NOT NULL,
    amount_delta_won bigint,
    summary_ko text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    linked_refs jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'OPEN'::text NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolved_reason text,
    carried_from_run_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_run_exceptions_hold_reason CHECK (((status <> 'HELD'::text) OR (btrim(COALESCE(resolved_reason, ''::text)) <> ''::text))),
    CONSTRAINT payroll_run_exceptions_kind_check CHECK ((kind = ANY (ARRAY['OVERTIME_ALLOWANCE'::text, 'RETRO_ADJUSTMENT'::text, 'ABSENCE_DEDUCTION'::text, 'PRORATION'::text, 'ACCOUNT_VERIFICATION'::text]))),
    CONSTRAINT payroll_run_exceptions_resolution CHECK (((status = 'OPEN'::text) OR ((resolved_by IS NOT NULL) AND (resolved_at IS NOT NULL)))),
    CONSTRAINT payroll_run_exceptions_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warn'::text, 'danger'::text]))),
    CONSTRAINT payroll_run_exceptions_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'CONFIRMED'::text, 'HELD'::text]))),
    CONSTRAINT payroll_run_exceptions_summary_ko_check CHECK ((btrim(summary_ko) <> ''::text))
);

ALTER TABLE ONLY public.payroll_run_exceptions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.payroll_run_exceptions OWNER TO console_app;

