--
-- Name: payroll_statutory_rates; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.payroll_statutory_rates (
    code text NOT NULL,
    effective_from date NOT NULL,
    effective_to_exclusive date,
    rate_num bigint,
    rate_den bigint,
    floor_won bigint,
    cap_won bigint,
    basis text NOT NULL,
    bearer text NOT NULL,
    instrument_ko text NOT NULL,
    article_ko text NOT NULL,
    promulgation_ko text NOT NULL,
    enforced_on date NOT NULL,
    source_url text NOT NULL,
    retrieved_on date NOT NULL,
    provenance_ko text NOT NULL,
    CONSTRAINT payroll_statutory_rates_article_ko_check CHECK ((btrim(article_ko) <> ''::text)),
    CONSTRAINT payroll_statutory_rates_basis_check CHECK ((basis = ANY (ARRAY['PENSION_STANDARD_INCOME'::text, 'MONTHLY_REMUNERATION'::text, 'HEALTH_INSURANCE_PREMIUM'::text, 'INDUSTRY_TARIFF'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT payroll_statutory_rates_bearer_check CHECK ((bearer = ANY (ARRAY['EMPLOYEE_WHOLE'::text, 'HALF_EACH'::text, 'EMPLOYER_ONLY'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT payroll_statutory_rates_cap_won_check CHECK (((cap_won IS NULL) OR (cap_won >= 0))),
    CONSTRAINT payroll_statutory_rates_check CHECK (((effective_to_exclusive IS NULL) OR (effective_to_exclusive > effective_from))),
    CONSTRAINT payroll_statutory_rates_code_check CHECK ((code = ANY (ARRAY['NATIONAL_PENSION_EMPLOYEE'::text, 'HEALTH_INSURANCE_TOTAL'::text, 'LONG_TERM_CARE_TOTAL'::text, 'EMPLOYMENT_INSURANCE_EMPLOYEE'::text, 'INDUSTRIAL_ACCIDENT_EMPLOYEE'::text, 'PENSION_STANDARD_INCOME_BAND'::text, 'HEALTH_PREMIUM_BAND'::text, 'MINIMUM_WAGE'::text, 'SIMPLIFIED_WITHHOLDING_TABLE'::text]))),
    CONSTRAINT payroll_statutory_rates_floor_won_check CHECK (((floor_won IS NULL) OR (floor_won >= 0))),
    CONSTRAINT payroll_statutory_rates_instrument_ko_check CHECK ((btrim(instrument_ko) <> ''::text)),
    CONSTRAINT payroll_statutory_rates_not_backdated_before_instrument CHECK ((effective_from >= enforced_on)),
    CONSTRAINT payroll_statutory_rates_promulgation_ko_check CHECK ((btrim(promulgation_ko) <> ''::text)),
    CONSTRAINT payroll_statutory_rates_provenance_ko_check CHECK ((btrim(provenance_ko) <> ''::text)),
    CONSTRAINT payroll_statutory_rates_rate_den_check CHECK (((rate_den IS NULL) OR (rate_den > 0))),
    CONSTRAINT payroll_statutory_rates_rate_num_check CHECK (((rate_num IS NULL) OR (rate_num >= 0))),
    CONSTRAINT payroll_statutory_rates_source_url_check CHECK ((source_url ~~ 'https://www.law.go.kr/%'::text))
);


ALTER TABLE public.payroll_statutory_rates OWNER TO console_app;

