    source_snapshot jsonb NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    idempotency_key text NOT NULL,
    approval_ref uuid,
    ontology_type_id uuid NOT NULL,
    first_operation_id uuid NOT NULL,
    created_by uuid NOT NULL,
    released_by uuid,
    released_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    plan_digest text NOT NULL,
    CONSTRAINT production_plans_check CHECK ((((status = 'DRAFT'::text) AND (released_by IS NULL) AND (released_at IS NULL)) OR ((status = 'RELEASED'::text) AND (released_by IS NOT NULL) AND (released_at IS NOT NULL)))),
    CONSTRAINT production_plans_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (char_length(idempotency_key) <= 128))),
    CONSTRAINT production_plans_plan_digest_sha256 CHECK ((plan_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT production_plans_product_code_check CHECK (((btrim(product_code) <> ''::text) AND (char_length(product_code) <= 80))),
    CONSTRAINT production_plans_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT production_plans_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'RELEASED'::text]))),
    CONSTRAINT production_plans_version_check CHECK ((version > 0))
);

