-- Name: registry_sites; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.registry_sites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    branch_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid NOT NULL,
    address text,
    province text,
    city text,
    postal_code text,
    latitude double precision,
    longitude double precision,
    contact_name text,
    contact_phone text,
    contact_email text,
    geofence_radius_m double precision,
    CONSTRAINT registry_sites_address_max_chars CHECK (((address IS NULL) OR (char_length(address) <= 500))),
    CONSTRAINT registry_sites_city_max_chars CHECK (((city IS NULL) OR (char_length(city) <= 100))),
    CONSTRAINT registry_sites_contact_email_max_chars CHECK (((contact_email IS NULL) OR (char_length(contact_email) <= 320))),
    CONSTRAINT registry_sites_contact_name_max_chars CHECK (((contact_name IS NULL) OR (char_length(contact_name) <= 100))),
    CONSTRAINT registry_sites_contact_phone_max_chars CHECK (((contact_phone IS NULL) OR (char_length(contact_phone) <= 40))),
    CONSTRAINT registry_sites_geofence_radius_positive CHECK (((geofence_radius_m IS NULL) OR ((geofence_radius_m > (0)::double precision) AND (geofence_radius_m <= (100000)::double precision)))),
    CONSTRAINT registry_sites_lat_lon_paired CHECK (((latitude IS NULL) = (longitude IS NULL))),
    CONSTRAINT registry_sites_latitude_range CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision)))),
    CONSTRAINT registry_sites_longitude_range CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision)))),
    CONSTRAINT registry_sites_name_check CHECK ((name <> ''::text)),
    CONSTRAINT registry_sites_name_max_chars CHECK ((char_length(name) <= 200)),
    CONSTRAINT registry_sites_postal_code_max_chars CHECK (((postal_code IS NULL) OR (char_length(postal_code) <= 20))),
    CONSTRAINT registry_sites_province_max_chars CHECK (((province IS NULL) OR (char_length(province) <= 100)))
);

