CREATE TABLE public.regular_inspection_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    branch_id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    mechanic_id uuid NOT NULL,
    cycle text NOT NULL,
    interval_days integer NOT NULL,
    due_date date NOT NULL,
    status text NOT NULL,
    completed_at timestamp with time zone,
    completed_by uuid,
    note text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid NOT NULL,
    CONSTRAINT regular_inspection_schedules_check CHECK ((((status = 'COMPLETED'::text) AND (completed_at IS NOT NULL) AND (completed_by IS NOT NULL)) OR ((status <> 'COMPLETED'::text) AND (completed_at IS NULL) AND (completed_by IS NULL)))),
    CONSTRAINT regular_inspection_schedules_cycle_check CHECK ((cycle = ANY (ARRAY['DAILY'::text, 'WEEKLY'::text, 'MONTHLY'::text, 'QUARTERLY'::text, 'YEARLY'::text, 'CUSTOM'::text]))),
    CONSTRAINT regular_inspection_schedules_interval_days_check CHECK ((interval_days > 0)),
    CONSTRAINT regular_inspection_schedules_status_check CHECK ((status = ANY (ARRAY['SCHEDULED'::text, 'COMPLETED'::text, 'CANCELLED'::text])))
);

