    CONSTRAINT sales_listings_availability_check CHECK (((availability IS NULL) OR (char_length(availability) <= 80))),
    CONSTRAINT sales_listings_badge_check CHECK (((badge IS NULL) OR (char_length(badge) <= 60))),
    CONSTRAINT sales_listings_capacity_milli_check CHECK (((capacity_milli IS NULL) OR (capacity_milli > 0))),
    CONSTRAINT sales_listings_condition_check CHECK ((condition = ANY (ARRAY['USED'::text, 'NEW'::text]))),
    CONSTRAINT sales_listings_condition_label_check CHECK (((condition_label IS NULL) OR (char_length(condition_label) <= 80))),
    CONSTRAINT sales_listings_description_check CHECK (((description IS NULL) OR (char_length(description) <= 4000))),
    CONSTRAINT sales_listings_kind_check CHECK ((kind = ANY (ARRAY['ELECTRIC'::text, 'DIESEL'::text, 'LPG'::text, 'REACH'::text]))),
    CONSTRAINT sales_listings_listing_type_check CHECK ((listing_type = ANY (ARRAY['SALE'::text, 'RENTAL'::text, 'BOTH'::text]))),
    CONSTRAINT sales_listings_location_check CHECK (((location IS NULL) OR (char_length(location) <= 120))),
    CONSTRAINT sales_listings_model_name_check CHECK (((char_length(model_name) >= 1) AND (char_length(model_name) <= 200))),
    CONSTRAINT sales_listings_model_year_check CHECK (((model_year IS NULL) OR ((model_year >= 1980) AND (model_year <= 2100)))),
    CONSTRAINT sales_listings_price_won_check CHECK (((price_won IS NULL) OR (price_won >= 0))),
    CONSTRAINT sales_listings_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'RESERVED'::text, 'SOLD'::text, 'WITHDRAWN'::text]))),
    CONSTRAINT sales_listings_usage_hours_check CHECK (((usage_hours IS NULL) OR (usage_hours >= 0))),
    CONSTRAINT sales_listings_usage_label_check CHECK (((usage_label IS NULL) OR (char_length(usage_label) <= 80)))
);

