-- Name: support_tickets; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.support_tickets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    branch_id uuid,
    origin text NOT NULL,
    category text NOT NULL,
    priority text NOT NULL,
    status text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    requester_user_id uuid,
    requester_name text,
    requester_contact text,
    assignee_user_id uuid,
    due_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    org_id uuid NOT NULL,
    site_id uuid,
    customer_id uuid,
    work_order_id uuid,
    CONSTRAINT support_tickets_body_check CHECK ((btrim(body) <> ''::text)),
    CONSTRAINT support_tickets_body_max_chars CHECK ((char_length(body) <= 8000)),
    CONSTRAINT support_tickets_category_check CHECK ((category = ANY (ARRAY['SYSTEM_BUG'::text, 'ACCESS_REQUEST'::text, 'OPERATIONAL'::text, 'EQUIPMENT_INQUIRY'::text, 'COMPLAINT'::text, 'OTHER'::text]))),
    CONSTRAINT support_tickets_check CHECK ((((origin = 'INTERNAL'::text) AND (requester_user_id IS NOT NULL) AND (branch_id IS NOT NULL) AND (requester_name IS NULL) AND (requester_contact IS NULL)) OR ((origin = 'CUSTOMER'::text) AND (requester_user_id IS NULL) AND (requester_name IS NOT NULL) AND (requester_contact IS NOT NULL)))),
    CONSTRAINT support_tickets_origin_check CHECK ((origin = ANY (ARRAY['INTERNAL'::text, 'CUSTOMER'::text]))),
    CONSTRAINT support_tickets_priority_check CHECK ((priority = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text, 'URGENT'::text]))),
    CONSTRAINT support_tickets_requester_contact_max_chars CHECK (((requester_contact IS NULL) OR (char_length(requester_contact) <= 200))),
    CONSTRAINT support_tickets_requester_name_max_chars CHECK (((requester_name IS NULL) OR (char_length(requester_name) <= 200))),
    CONSTRAINT support_tickets_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'ON_HOLD'::text, 'RESOLVED'::text, 'CLOSED'::text]))),
    CONSTRAINT support_tickets_title_check CHECK ((btrim(title) <> ''::text)),
    CONSTRAINT support_tickets_title_max_chars CHECK ((char_length(title) <= 200)),
    CONSTRAINT support_tickets_wo_requires_site CHECK (((work_order_id IS NULL) OR (site_id IS NOT NULL)))
);

