--

CREATE TABLE public.work_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_no text NOT NULL,
    branch_id uuid NOT NULL,
    equipment_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    site_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    status text NOT NULL,
    priority text DEFAULT 'UNSET'::text NOT NULL,
    symptom text NOT NULL,
    customer_request text,
    target_due_at timestamp with time zone,
    delay_reason text,
    delay_note text,
    result_type text DEFAULT 'UNKNOWN'::text NOT NULL,
    diagnosis text,
    action_taken text,
    report_submitted_by uuid,
    report_submitted_at timestamp with time zone,
    kpi_excluded boolean DEFAULT false NOT NULL,
    evidence_verified boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    org_id uuid NOT NULL,
    maintenance_type text,
    maintenance_cause text,
    CONSTRAINT work_orders_delay_reason_check CHECK (((delay_reason IS NULL) OR (delay_reason = ANY (ARRAY['PART_WAITING'::text, 'CUSTOMER_ABSENT'::text, 'EQUIPMENT_IN_USE'::text, 'MECHANIC_OVERLOADED'::text, 'OUTSOURCE_DELAY'::text, 'ADDITIONAL_FAULT_FOUND'::text, 'SAFETY_ISSUE'::text, 'OTHER'::text])))),
    CONSTRAINT work_orders_maintenance_cause_check CHECK (((maintenance_cause IS NULL) OR (maintenance_cause = ANY (ARRAY['BREAKDOWN'::text, 'RETURN_PREP'::text, 'SCHEDULED'::text, 'INSPECTION_FINDING'::text, 'OTHER'::text])))),
    CONSTRAINT work_orders_maintenance_type_check CHECK (((maintenance_type IS NULL) OR (maintenance_type = ANY (ARRAY['EMERGENCY'::text, 'CORRECTIVE'::text, 'PREVENTIVE'::text, 'INSPECTION'::text])))),
    CONSTRAINT work_orders_priority_check CHECK ((priority = ANY (ARRAY['P1'::text, 'P2'::text, 'P3'::text, 'OUTSOURCE'::text, 'UNSET'::text]))),
    CONSTRAINT work_orders_request_no_check CHECK ((request_no ~ '^[0-9]{8}-[0-9]{3}$'::text)),
    CONSTRAINT work_orders_result_type_check CHECK ((result_type = ANY (ARRAY['COMPLETED'::text, 'TEMPORARY_ACTION'::text, 'INCOMPLETE'::text, 'REVISIT_REQUIRED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT work_orders_status_check CHECK ((status = ANY (ARRAY['RECEIVED'::text, 'UNASSIGNED'::text, 'ASSIGNED'::text, 'IN_PROGRESS'::text, 'REPORT_SUBMITTED'::text, 'ADMIN_REVIEW'::text, 'FINAL_COMPLETED'::text, 'REJECTED'::text, 'ON_HOLD'::text, 'DELAYED'::text, 'TEMPORARY_ACTION'::text, 'PART_WAITING'::text, 'EQUIPMENT_IN_USE'::text, 'REVISIT_REQUIRED'::text, 'ARCHIVED'::text, 'CANCELLED'::text]))),
    CONSTRAINT work_orders_symptom_check CHECK ((symptom <> ''::text))
);

ALTER TABLE ONLY public.work_orders FORCE ROW LEVEL SECURITY;


ALTER TABLE public.work_orders OWNER TO console_app;

--
-- Name: unverified_evidence_admin_queue; Type: VIEW; Schema: public; Owner: console_app
--

CREATE VIEW public.unverified_evidence_admin_queue AS
 SELECT e.id,
    e.work_order_id,
    w.request_no,
    w.branch_id,
    e.stage,
    e.s3_key,
    e.content_type,
    e.size_bytes,
    e.uploaded_by,
    e.worm_replica_status,
    e.retry_count,
    e.next_retry_at,
    e.last_error,
    e.created_at,
    e.updated_at
   FROM (public.evidence_media e
     JOIN public.work_orders w ON ((w.id = e.work_order_id)))
  WHERE (e.worm_replica_status = ANY (ARRAY['PENDING'::text, 'FAILED'::text]));


ALTER VIEW public.unverified_evidence_admin_queue OWNER TO console_app;

