    CONSTRAINT workflow_outbox_events_check1 CHECK (((dead_lettered_at IS NULL) OR (status = 'DEAD_LETTERED'::text))),
    CONSTRAINT workflow_outbox_events_dead_letter_requires_evidence CHECK (((status <> 'DEAD_LETTERED'::text) OR ((dead_lettered_at IS NOT NULL) AND (attempt_count >= 1) AND (error_payload IS NOT NULL) AND (jsonb_typeof(error_payload) = 'object'::text) AND (error_payload <> '{}'::jsonb)))),
    CONSTRAINT workflow_outbox_events_delivered_requires_timestamp CHECK (((status <> 'DELIVERED'::text) OR (delivered_at IS NOT NULL))),
    CONSTRAINT workflow_outbox_events_destination_ref_check CHECK (((destination_ref IS NULL) OR ((char_length(btrim(destination_ref)) >= 1) AND (char_length(btrim(destination_ref)) <= 300)))),
    CONSTRAINT workflow_outbox_events_error_payload_check CHECK (((error_payload IS NULL) OR (jsonb_typeof(error_payload) = 'object'::text))),
    CONSTRAINT workflow_outbox_events_idempotency_key_check CHECK (((char_length(btrim(idempotency_key)) >= 16) AND (char_length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT workflow_outbox_events_locked_by_check CHECK (((locked_by IS NULL) OR ((char_length(btrim(locked_by)) >= 1) AND (char_length(btrim(locked_by)) <= 160)))),
    CONSTRAINT workflow_outbox_events_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT workflow_outbox_events_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'IN_PROGRESS'::text, 'DELIVERED'::text, 'FAILED'::text, 'DEAD_LETTERED'::text, 'CANCELLED'::text])))
);

