--
-- Name: workflow_runs; Type: TABLE; Schema: public; Owner: console_app
--

CREATE TABLE public.workflow_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    definition_id uuid NOT NULL,
    definition_version integer NOT NULL,
    status text DEFAULT 'STARTING'::text NOT NULL,
    trigger_type text NOT NULL,
    object_type text,
    object_id uuid,
    idempotency_key text NOT NULL,
    correlation_id text NOT NULL,
    trace_id text,
    input_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    context_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    output_payload jsonb,
    error_payload jsonb,
    initiated_by uuid,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    failed_at timestamp with time zone,
    schedule_id uuid,
    CONSTRAINT workflow_runs_check CHECK ((((object_type IS NULL) AND (object_id IS NULL)) OR ((object_type IS NOT NULL) AND (object_id IS NOT NULL)))),
    CONSTRAINT workflow_runs_check1 CHECK (((completed_at IS NULL) OR (status = ANY (ARRAY['SUCCEEDED'::text, 'CANCELLED'::text])))),
    CONSTRAINT workflow_runs_check2 CHECK (((failed_at IS NULL) OR (status = ANY (ARRAY['FAILED'::text, 'DEAD_LETTERED'::text])))),
    CONSTRAINT workflow_runs_context_payload_check CHECK ((jsonb_typeof(context_payload) = 'object'::text)),
    CONSTRAINT workflow_runs_correlation_id_check CHECK (((char_length(btrim(correlation_id)) >= 8) AND (char_length(btrim(correlation_id)) <= 200))),
    CONSTRAINT workflow_runs_definition_version_check CHECK ((definition_version >= 1)),
    CONSTRAINT workflow_runs_error_payload_check CHECK (((error_payload IS NULL) OR (jsonb_typeof(error_payload) = 'object'::text))),
    CONSTRAINT workflow_runs_idempotency_key_check CHECK (((char_length(btrim(idempotency_key)) >= 16) AND (char_length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT workflow_runs_input_payload_check CHECK ((jsonb_typeof(input_payload) = 'object'::text)),
    CONSTRAINT workflow_runs_object_type_check CHECK (((object_type IS NULL) OR (object_type ~ '^[a-z][a-z0-9_]{1,63}$'::text))),
    CONSTRAINT workflow_runs_output_payload_check CHECK (((output_payload IS NULL) OR (jsonb_typeof(output_payload) = 'object'::text))),
    CONSTRAINT workflow_runs_status_check CHECK ((status = ANY (ARRAY['STARTING'::text, 'RUNNING'::text, 'WAITING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text, 'DEAD_LETTERED'::text]))),
    CONSTRAINT workflow_runs_trace_id_check CHECK (((trace_id IS NULL) OR ((char_length(btrim(trace_id)) >= 8) AND (char_length(btrim(trace_id)) <= 200)))),
    CONSTRAINT workflow_runs_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['MANUAL'::text, 'SCHEDULE'::text, 'OBJECT_EVENT'::text, 'IMPORT_EVENT'::text, 'MAIL_EVENT'::text, 'MESSENGER_EVENT'::text, 'CALENDAR_EVENT'::text, 'POLL_EVENT'::text, 'API'::text])))
);

